(542, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan empat bilangan berikut:0,65 ; 5/8 ; 68% ; 2/3Urutan bilangan tersebut dari yang memiliki nilai terkecil ke nilai terbesar adalah ....', NULL, TRUE),
(543, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan garis bilangan berikut!Pada garis bilangan di atas, terdapat empat titik yaitu P, Q, R, dan S yang mewakili posisi bilangan real tertentu.Pernyataan-pernyataan berikut berkaitan dengan posisi titik-titik tersebut:Pilih semua jawaban benar!', '/assets/images/soal/matematika/M01/lvl1_soal_02.png', TRUE),
(544, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Hasil perhitungan dari operasi hitung (−18)+12÷(−3)−(−5)×4 adalah ....', NULL, TRUE),
(545, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Bentuk sederhana dari operasi perpangkatan 2^5×6^3/3^2×4^3 adalah ....', NULL, TRUE),
(546, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Diberikan bentuk perhitungan matematika berikut:4,98×19,85+√(82)Tentukan kebenaran pernyataan-pernyataan mengenai estimasi nilai dari bentuk tersebut!Pilih semua jawaban benar!', NULL, TRUE),
(547, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Faktorisasi prima dari bilangan asli 840 adalah ....', NULL, TRUE),
(548, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Bentuk paling sederhana dari rasio antara 750 gram dan 2,5 kilogram adalah ....', NULL, TRUE),
(549, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan diagram pohon faktor penguraian bilangan 360 berikut!Berdasarkan diagram pohon faktor tersebut, tentukan kebenaran pernyataan-pernyataan berikut!Pilih semua jawaban benar!', '/assets/images/soal/matematika/M01/lvl1_soal_08.png', TRUE),
(550, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Di antara hubungan antara dua besaran berikut, manakah yang merupakan contoh perbandingan senilai?', NULL, TRUE),
(551, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Di antara bilangan-bilangan di bawah ini, bilangan manakah yang tergolong sebagai bilangan irasional?', NULL, TRUE),
(552, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan empat kesamaan operasi hitung pecahan berikut!Tentukan kesamaan mana saja yang bernilai BENAR!Pilih semua jawaban benar!', NULL, TRUE),
(553, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Bilangan desimal 0,00007865 jika dituliskan dalam bentuk notasi ilmiah (bentuk baku) dengan pembulatan sampai dua tempat desimal adalah ....', NULL, TRUE),
(554, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah kereta rel listrik menempuh lintasan sejauh 108 kilometer dalam durasi waktu 1,5 jam. Laju perubahan jarak terhadap waktu (kecepatan rata-rata) kereta tersebut dalam satuan meter per detik (m/s) adalah ....', NULL, TRUE),
(555, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan gambar denah ruang laboratorium sekolah berskala grafis berikut!Berdasarkan denah dan skala grafis tersebut, tentukan kebenaran pernyataan-pernyataan berikut!Pilih semua jawaban benar!', '/assets/images/soal/matematika/M01/lvl1_soal_14.png', TRUE),
(556, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Tabel berikut menunjukkan hubungan dua besaran x dan y yang saling berbalik nilai:Nilai x:   4  |  6  |  10Nilai y:  15  |  p  |   6Nilai p yang tepat untuk melengkapi tabel tersebut adalah ....', NULL, TRUE),
(557, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Tentukan kebenaran pernyataan-pernyataan mengenai sifat bilangan berpangkat berikut!Pilih semua jawaban benar!', NULL, TRUE),
(558, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Bentuk sederhana dari operasi aljabar akar √(75)+2√(12)−√(48) adalah ....', NULL, TRUE),
(559, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Diberikan dua bilangan asli A dan B dalam bentuk faktorisasi prima:A=2^3×3^2×5B=2^2×3^3×7Pernyataan-pernyataan berikut berkaitan dengan FPB dan KPK dari bilangan A dan B:Pilih semua jawaban benar!', NULL, TRUE),
(560, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan dua grafik hubungan antarbesaran berikut!Berdasarkan karakteristik kurva pada kedua grafik tersebut, manakah simpulan yang paling tepat?', '/assets/images/soal/matematika/M01/lvl1_soal_19.png', TRUE),
(561, 1, 1, 1, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Diberikan dua nilai bilangan berikut:Nilai K=47,8÷5,9Nilai M=2,363636…Pernyataan-pernyataan berikut berkaitan dengan kedua bilangan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(562, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah toko pakaian memberikan promosi akhir tahun dengan skema diskon ganda "Diskon 30%+10%". Ketentuan promo tersebut mengartikan bahwa harga barang didiskon sebesar 30% terlebih dahulu, kemudian dari harga setelah diskon tersebut diberikan potongan tambahan sebesar 10%.Jika seorang pembeli membeli jaket dengan label harga Rp200.000,00, jumlah uang yang harus dibayarkan ke kasir adalah ....', NULL, TRUE),
(563, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Panitia bakti sosial sekolah menerima sumbangan sembako berupa 180 kg beras, 90 liter minyak goreng, dan 60 kg gula pasir. Seluruh barang tersebut akan dikemas ke dalam sejumlah paket bantuan dengan isi dan komposisi yang sama persis tanpa ada barang yang tersisa.Pernyataan-pernyataan berikut berkaitan dengan pengemasan paket bantuan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(564, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Berdasarkan prinsip meteorologi, setiap kenaikan ketinggian 100 meter di atas permukaan laut (mdpl), suhu udara rata-rata akan mengalami penurunan sebesar 0,6^∘C.Jika suhu udara di sebuah kota pesisir (ketinggian 0 mdpl) tercatat sebesar 28^∘C, berapakah perkiraan suhu udara di puncak pos pendakian gunung yang berada pada ketinggian 1.500 mdpl?', NULL, TRUE),
(565, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan catatan suhu udara pada termometer di empat wilayah pada pukul 06.00 WIB berikut!Berdasarkan data pengukuran suhu udara pada gambar termometer tersebut, selisih suhu udara antara wilayah dengan suhu paling dingin dan wilayah dengan suhu paling panas adalah ....', '/assets/images/soal/matematika/M01/lvl2_soal_24.png', TRUE),
(566, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Ibu berbelanja di minimarket dengan membeli beberapa barang kebutuhan pokok berikut:* 3 bungkus sabun cuci seharga Rp8.950,00 per bungkus;* 2 botol kecap manis seharga Rp14.800,00 per botol;* 4 kg gula pasir seharga Rp17.100,00 per kg.Ibu membawa selembar uang pecahan Rp100.000,00 dan selembar pecahan Rp50.000,00 (total uang Rp150.000,00).Pernyataan-pernyataan berikut berkaitan dengan perkiraan dan total belanjaan Ibu:Pilih semua jawaban benar!', NULL, TRUE),
(567, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Tiga orang petugas keamanan lingkungan bertugas ronda malam secara berkala. Petugas A bertugas setiap 4 hari sekali, Petugas B setiap 6 hari sekali, dan Petugas C setiap 8 hari sekali.Jika mereka bertiga bertugas ronda malam bersama-sama untuk pertama kalinya pada hari Senin, tanggal 2 Oktober, pada hari dan tanggal berapakah mereka bertiga akan bertugas bersama-sama untuk kedua kalinya?', NULL, TRUE),
(568, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah toko roti menyiapkan 48 toples kue kastengel, 72 toples kue nastar, dan 96 toples kue putri salju untuk dibagikan ke dalam paket-paket parcel lebaran secara merata tanpa ada sisa toples.Tentukan kebenaran dari pernyataan-pernyataan berikut mengenai paket parcel tersebut!Pilih semua jawaban benar!', NULL, TRUE),
(569, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan skema tandon air silinder pada gambar berikut!Kapasitas maksimum tandon penampungan air tersebut adalah 600 liter. Saat ini tandon telah terisi air sebanyak 450 liter. Keran pengisi atas dialirkan dengan debit 15 liter/menit, namun pada saat yang sama keran pembuangan bawah secara tidak sengaja terbuka dengan debit aliran 5 liter/menit.Berapa lama waktu yang dibutuhkan hingga tandon air tersebut terisi penuh sampai batas maksimum 600 liter?', '/assets/images/soal/matematika/M01/lvl2_soal_28.png', TRUE),
(570, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah resep standar kue bolu untuk menyajikan 12 porsi memerlukan 300 gram tepung terigu, 180 gram gula pasir, dan 4 butir telur ayam.Jika seorang pembuat kue menerima pesanan untuk membuat kue bolu dengan cita rasa yang sama persis sebanyak 30 porsi, berapakah kebutuhan tepung terigu yang harus disiapkan?', NULL, TRUE),
(571, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah mobil penumpang menempuh perjalanan sejauh 96 km dan menghabiskan 8 liter bensin jenis pertalite.Dengan mengasumsikan efisiensi laju konsumsi bensin mobil tersebut selalu konstan, tentukan kebenaran dari pernyataan-pernyataan berikut!Pilih semua jawaban benar!', NULL, TRUE),
(572, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Seorang pedagang kelontong membeli 4,5 kg telur ayam dengan total harga Rp126.000,00. Jika pedagang tersebut ingin menambah pesanan telur ayam jenis yang sama sebanyak 12 kg lagi, berapakah tambahan biaya yang harus dibayarkan?', NULL, TRUE),
(573, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah bus antarkota melaju dari Kota P ke Kota Q dengan kecepatan rata-rata 60 km/jam dan tiba dalam waktu 4 jam.Pernyataan-pernyataan berikut berkaitan dengan variasi kecepatan dan waktu perjalanan pada rute yang sama:Pilih semua jawaban benar!', NULL, TRUE),
(574, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan diagram batang rata-rata konsumsi bahan bakar empat jenis mobil berikut!Untuk menempuh perjalanan dinas sejauh 240 km, sebuah kantor memilih menggunakan mobil yang paling hemat bahan bakar di antara keempat pilihan pada diagram.Berapa liter bensin yang dibutuhkan oleh mobil paling hemat tersebut untuk menyelesaikan perjalanan sejauh 240 km?', '/assets/images/soal/matematika/M01/lvl2_soal_33.png', TRUE),
(575, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Dalam sebuah eksperimen laboratorium IPA, siswa mengukur massa dan volume dari empat jenis zat cair berbeda yang tidak saling larut:* Cairan W: massa 180 gram, volume 200 cm^3* Cairan X: massa 250 gram, volume 200 cm^3* Cairan Y: massa 210 gram, volume 300 cm^3* Cairan Z: massa 100 gram, volume 100 cm^3 (air murni)Diketahui bahwa massa jenis dihitung dengan rumus ρ=massa/volume.Pilih semua jawaban benar!', NULL, TRUE),
(576, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah rumah tangga menggunakan peralatan listrik dengan rincian pemakaian rata-rata harian sebagai berikut:* 5 buah lampu LED masing-masing 20 watt menyala selama 10 jam per hari;* 1 unit lemari es dengan daya 100 watt menyala 24 jam per hari nonstop.Jika tarif energi listrik PLN adalah Rp1.500,00 per kilowatt-hour (kWh), berapakah total biaya pemakaian listrik untuk kedua jenis peralatan tersebut selama 30 hari (1 bulan)?', NULL, TRUE),
(577, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Seorang pedagang buah membeli 100 kg semangka dengan harga beli Rp6.000,00 per kg. Untuk membawa semangka tersebut ke kiosnya, pedagang membayar ongkos angkut sebesar Rp50.000,00. Saat disortir, ditemukan 10 kg semangka dalam kondisi busuk sehingga tidak layak untuk dijual. Pedagang kemudian menjual seluruh sisa semangka yang segar dengan harga Rp10.000,00 per kg hingga habis.Pernyataan-pernyataan berikut berkaitan dengan transaksi pedagang buah tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(578, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan grafik hubungan kecepatan rata-rata dan waktu tempuh untuk jarak perjalanan 180 km berikut!Jika seorang pengemudi mobil ditargetkan tiba di tempat tujuan dalam waktu tepat 2,5 jam (2 jam 30 menit), berapakah kecepatan rata-rata mobil yang harus dipertahankan?', '/assets/images/soal/matematika/M01/lvl2_soal_37.png', TRUE),
(579, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Keluarga Pak Budi berencana melakukan perjalanan mudik antarprovinsi menempuh rute sejauh 438 km. Mobil yang dikendarai memiliki efisiensi konsumsi bahan bakar rata-rata 10,8 km per liter. Harga bahan bakar bensin yang digunakan adalah Rp13.250,00 per liter.Pernyataan-pernyataan berikut berkaitan dengan estimasi kebutuhan bensin dan anggaran perjalanan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(580, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah media penyimpanan digital flashdisk memiliki ruang penyimpanan efektif yang tersisa sebesar 32 gigabyte (dapat dinyatakan sekitar 3,2×10^10 byte). Pengguna ingin menyimpan arsip foto resolusi tinggi yang masing-masing rata-rata berukuran 4,8 megabyte (sekitar 4,8×10^6 byte).Berapa perkiraan jumlah maksimum foto yang dapat dimuat ke dalam flashdisk tersebut?', NULL, TRUE),
(581, 1, 1, 2, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah peternakan memelihara 500 ekor ayam pedaging yang menghabiskan 35 kg pakan setiap harinya secara seragam. Peternak kemudian menambah bibit ayam sebanyak 200 ekor lagi ke dalam kandang sehingga jenis dan nafsu makan ayam dianggap sama rata.Pernyataan-pernyataan berikut berkaitan dengan kebutuhan pakan di peternakan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(582, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah proyek pembangunan jembatan desa ditargetkan selesai dalam waktu 40 hari kerja oleh 18 orang pekerja dengan produktivitas seragam.Setelah proyek berjalan selama 16 hari, pekerjaan terpaksa dihentikan sementara selama 6 hari akibat banjir bandang yang merendam lokasi konstruksi. Jika proyek tersebut harus tetap selesai tepat waktu sesuai batas perjanjian kontrak semula (40 hari), berapa banyak pekerja tambahan yang harus direkrut oleh mandor proyek?', NULL, TRUE),
(583, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Seorang peternak memiliki persediaan pakan konsentrat yang diperkirakan cukup untuk memberi makan 30 ekor sapi selama 16 hari. Setelah pakan tersebut digunakan selama 4 hari penuh, peternak memutuskan untuk menjual 10 ekor sapi miliknya ke pedagang ternak.Pernyataan-pernyataan berikut berkaitan dengan ketersediaan sisa pakan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(584, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan grafik perbandingan struktur tarif dari dua penyedia layanan transportasi online berikut!* Layanan Kilat: Tarif dasar Rp10.000,00 ditambah biaya perjalanan Rp3.500,00 per km.* Layanan Nyaman: Tarif dasar Rp16.000,00 ditambah biaya perjalanan Rp2.500,00 per km.Berdasarkan grafik dan model tarif tersebut, tentukan kebenaran pernyataan-pernyataan berikut!Pilih semua jawaban benar!', '/assets/images/soal/matematika/M01/lvl3_soal_43.png', TRUE),
(585, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah bilangan asli N memiliki bentuk faktorisasi prima N=2^a×3^b×5^c dengan a,b,c merupakan bilangan bulat positif. Jika N merupakan bilangan kuadrat sempurna terkecil yang habis dibagi oleh 120, berapakah nilai dari bilangan N tersebut?', NULL, TRUE),
(586, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Dua bilangan asli p dan q memenuhi sifat p<q. Diketahui bahwa FPB(p,q)=14 dan KPK(p,q)=420. Jika jumlah kedua bilangan tersebut adalah p+q=154, berapakah nilai selisih (q−p)?', NULL, TRUE),
(587, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Diberikan sebuah bilangan bulat positif M yang dinyatakan dalam bentuk faktorisasi prima:M=2^4×3^2×5^1Pernyataan-pernyataan berikut berkaitan dengan faktor pembagi bulat positif dari bilangan M:Pilih semua jawaban benar!', NULL, TRUE),
(588, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebidang tanah pekarangan berbentuk persegi panjang diukur panjang dan lebarnya dengan pembulatan ke satuan meter terdekat. Hasil pengukuran menunjukkan panjang 24 meter dan lebar 15 meter.Mengingat setiap pengukuran memiliki batas galat (toleransi pembulatan) sebesar ±0,5 meter, berapakah selisih antara estimasi luas maksimum yang mungkin dan estimasi luas minimum yang mungkin dari tanah tersebut?', NULL, TRUE),
(589, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah brosur kampanye hemat energi mengklaim bahwa dengan mengganti 10 buah lampu pijar 60 watt menggunakan lampu LED hemat energi 8 watt yang menyala rata-rata 8 jam per hari, sebuah rumah dapat menghemat pengeluaran rekening listrik lebih dari Rp700.000,00 dalam kurun waktu satu tahun (365 hari).Diasumsikan tarif listrik yang berlaku flat sebesar Rp1.500,00 per kWh.Tentukan kebenaran pernyataan-pernyataan berikut dalam mengevaluasi klaim tersebut!Pilih semua jawaban benar!', NULL, TRUE),
(590, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan skema transmisi rantai dan gir sepeda balap pada gambar berikut!Gir depan (dihubungkan dengan pedal kayuh) memiliki 48 gigi, sedangkan gir belakang (dihubungkan dengan poros roda belakang) memiliki 16 gigi. Roda sepeda memiliki diameter luar 70 cm (gunakan pendekatan nilai π=22/7).Berapakah jarak lintasan lurus yang ditempuh sepeda tersebut di atas jalan rata untuk setiap 1 putaran penuh kayuhan pedal?', '/assets/images/soal/matematika/M01/lvl3_soal_49.png', TRUE),
(591, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Di laboratorium kimia sekolah, seorang laboran mencampurkan 300 mL Larutan Alkohol jenis A berkonsentrasi 20% dengan 200 mL Larutan Alkohol jenis B berkonsentrasi 50%.Pernyataan-pernyataan berikut berkaitan dengan karakteristik larutan hasil pencampuran tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(592, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan empat bilangan real bentuk akar berikut:P=√(11)−√(7)Q=√(15)−√(11)R=√(19)−√(15)S=√(23)−√(19)Di antara keempat bilangan tersebut, bilangan manakah yang memiliki nilai numerik paling besar?', NULL, TRUE),
(593, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Diberikan tiga bilangan berpangkat berukuran sangat besar:x=2^60y=3^40z=5^20Pernyataan-pernyataan berikut berkaitan dengan perbandingan nilai ketiga bilangan tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(594, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Pada babak penyisihan Olimpiade Matematika SMP yang terdiri atas 50 butir soal, panitia menerapkan aturan penilaian sebagai berikut:* Setiap jawaban benar diberi skor +4;* Setiap jawaban salah diberi penalti skor -2;* Setiap butir soal yang tidak dijawab (kosong) diberi penalti skor -1.Seorang peserta berhasil menjawab 45 butir soal dan mengosongkan sisa soal lainnya. Setelah diperiksa, peserta tersebut memperoleh total skor akhir sebesar 127 poin. Berapa butir soal yang dijawab dengan benar oleh peserta tersebut?', NULL, TRUE),
(595, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Perhatikan denah gedung pertemuan serbaguna berskala 1 : 150 berikut!Denah tersebut membagi gedung menjadi tiga ruangan:* Aula Utama (Ruang A): ukuran denah 5 cm × 5 cm;* Ruang Rapat (Ruang B): ukuran denah 3 cm × 3 cm;* Pantry & Gudang (Ruang C): ukuran denah 3 cm × 2 cm.Lantai Ruang Rapat (B) akan dipasangi ubin granit dengan harga material Rp200.000,00 per m².Pilih semua jawaban benar!', '/assets/images/soal/matematika/M01/lvl3_soal_54.png', TRUE),
(596, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah kolam renang memiliki tiga unit pompa pengisi air (Pompa 1, Pompa 2, dan Pompa 3) dengan kapasitas berbeda. Dari hasil pengujian individu:* Pompa 1 dapat mengisi kolam hingga penuh sendirian dalam waktu 6 jam;* Pompa 2 dapat mengisi kolam hingga penuh sendirian dalam waktu 4 jam;* Pompa 3 dapat mengisi kolam hingga penuh sendirian dalam waktu 12 jam.Pernyataan-pernyataan berikut berkaitan dengan pengisian kolam renang tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(597, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Dalam suatu penelitian kimia, diketahui bahwa estimasi massa satu molekul air (H_2O) adalah sekitar 3,0×10^−23 gram. Dalam sebuah percobaan, satu tetes air murni ditimbang dan memiliki massa sebesar 0,06 gram (dapat ditulis 6,0×10^−2 gram).Berdasarkan data tersebut, berapakah perkiraan banyaknya molekul air yang terkandung di dalam satu tetes air tersebut?', NULL, TRUE),
(598, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah instalasi lampu hias panggung memiliki tiga warna lampu dengan interval kedip otomatis yang berbeda:* Lampu Merah menyala setiap 12 detik sekali;* Lampu Kuning menyala setiap 15 detik sekali;* Lampu Hijau menyala setiap 20 detik sekali.Ketiga lampu tersebut menyala bersama-sama untuk pertama kalinya tepat pada pukul 19.30.00 WIB.Pilih semua jawaban benar!', NULL, TRUE),
(599, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Perhatikan grafik kurva progres pekerjaan proyek pembangunan jembatan desa berikut!Proyek jembatan semula ditargetkan selesai 100% dalam waktu 60 hari kerja oleh 15 orang pekerja tetap. Selama 20 hari pertama pekerjaan berjalan lancar dan mencapai sepertiga bagian (33,33%). Namun, dari hari ke-20 sampai hari ke-30 terjadi banjir sehingga pekerjaan terhenti total selama 10 hari.Berapa orang pekerja tambahan yang harus segera didatangkan mulai hari ke-30 agar proyek tetap dapat rampung 100% tepat pada hari ke-60?', '/assets/images/soal/matematika/M01/lvl3_soal_58.png', TRUE),
(600, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Dalam suatu medium kultur biakan laboratorium, populasi awal suatu bakteri diamati berjumlah 200 sel. Setiap 20 menit sekali, setiap sel bakteri membelah diri menjadi 2 sel baru secara teratur.Pernyataan-pernyataan berikut berkaitan dengan perkiraan populasi bakteri tersebut:Pilih semua jawaban benar!', NULL, TRUE),
(601, 1, 1, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah tangki penampungan air limbah industri memiliki dua pipa drainase pembuangan di bagian bawah. Jika tangki terisi penuh air:* Pipa Drainase A dapat mengosongkan seluruh tangki sendirian dalam waktu 30 menit;* Pipa Drainase B dapat mengosongkan seluruh tangki sendirian dalam waktu 20 menit.Jika kedua pipa drainase tersebut dibuka secara bersamaan saat tangki terisi penuh, berapa lama waktu yang dibutuhkan hingga seluruh air di dalam tangki habis terkuras?', NULL, TRUE),
