(4531, 1138, 'C', 'Adanya selisih antara hasil empirik (110) dan frekuensi harapan teoretik (100) adalah hal yang wajar dalam probabilitas.', TRUE),
(4532, 1138, 'D', 'Jika dadu tersebut dilempar jutaan kali, rasio kemunculan angka "1" akan semakin mendekati 1/6.', TRUE),
(4533, 1139, 'A', 'Ruang sampel (kemungkinan yang terjadi) tersisa 7 titik sampel.', TRUE),
(4534, 1139, 'B', 'Kemungkinan munculnya ketiga koin bersisi Angka (AAA) sudah menjadi 0.', TRUE),
(4535, 1139, 'C', 'Peluang munculnya tepat dua sisi Angka (AAG, AGA, GAA) menjadi 3/7.', FALSE),
(4536, 1139, 'D', 'Peluang munculnya tepat tiga sisi Gambar (GGG) adalah 1/8.', TRUE),
(4537, 1140, 'A', 'Pada pengambilan pertama, peluang kelereng Merah dan Hitam sama besar (1/2).', TRUE),
(4538, 1140, 'B', 'Jika Kelereng Pertama yang terambil adalah Merah, maka peluang Kelereng Kedua berwarna Hitam menjadi 2/3.', TRUE),
(4539, 1140, 'C', 'Mengambil kelereng tanpa pengembalian membuat kejadian pertama dan kedua menjadi kejadian yang saling bergantung (tidak bebas).', FALSE),
(4540, 1140, 'D', 'Jika Kelereng Pertama Merah, ruang sampel untuk pengambilan kedua tetap 4 kelereng.', TRUE),
(4541, 1141, 'A', 'Total kelereng di dalam kantong haruslah kelipatan persekutuan terkecil (KPK) dari penyebut 2 dan 3, yaitu 6.', TRUE),
(4542, 1141, 'B', 'Peluang kelereng Kuning di dalam kantong tersebut pasti bernilai 1/6.', TRUE),
(4543, 1141, 'C', 'Desain terkecil akan berisi tepat 3 Merah, 2 Biru, dan 1 Kuning.', FALSE),
(4544, 1141, 'D', 'Tidak mungkin ada kelereng Kuning karena 1/2 dan 1/3 sudah memenuhi 100%.', TRUE)
