-- -----------------------------------------------------------------------------
-- 3. PEMBENIHAN PEMBAHASAN JAWABAN (QUESTION_EXPLANATIONS - 600 Pembahasan, ID 542..1141)
-- -----------------------------------------------------------------------------
INSERT INTO `question_explanations` (
    `id`, `question_id`, `explanation_text`, `reasoning_guide`, `reference_url`
) VALUES
(542, 542, 'Kunci: BUntuk membandingkan dan mengurutkan bilangan-bilangan tersebut, ubah seluruh bentuk bilangan ke dalam bentuk desimal dengan tiga angka di belakang koma:1. 5/8=0,6252. 0,65=0,6503. 2/3≈0,6674. 68%=68/100=0,680Membandingkan nilai desimalnya: 0,625<0,650<0,667<0,680.Dengan demikian, urutan dari nilai terkecil ke terbesar adalah 5/8 ; 0,65 ; 2/3 ; 68%.Jawaban yang benar adalah B.', NULL, NULL),
(543, 543, 'Kunci: A, B, C, DEvaluasi terhadap setiap pernyataan berdasarkan posisi titik pada garis bilangan:* Pernyataan A BENAR: Titik P berada pada posisi −2,25. Dalam bentuk pecahan biasa, −2,25=−225/100=−9/4.* Pernyataan B BENAR: Titik Q berada pada koordinat −0,6, yaitu tepat berada di sebelah kiri 0 dan di sebelah kanan −1 (di antara −1 dan 0).* Pernyataan C BENAR: Nilai pendekatan dari √(2) adalah 1,4142…, yang sesuai dengan posisi titik R (sedikit di bawah 1,5).* Pernyataan D BENAR: Jarak antara titik P dan S dihitung dengan selisih mutlak koordinatnya: |2,75−(−2,25)|=2,75+2,25=5,0 satuan.Seluruh pernyataan A, B, C, dan D bernilai benar.', NULL, NULL),
(544, 544, 'Kunci: BSesuai dengan aturan hierarki operasi matematika (urutan operasi BODMAS/KABATAKU):1. Lakukan operasi pembagian terlebih dahulu:   12÷(−3)=−42. Lakukan operasi perkalian:   (−5)×4=−203. Lakukan operasi penjumlahan dan pengurangan dari kiri ke kanan:   (−18)+(−4)−(−20)=−22−(−20)=−22+20=−2.Jawaban yang benar adalah B.', NULL, NULL),
(545, 545, 'Kunci: BUraikan semua bilangan pokok menjadi faktor-faktor prima (2 dan 3):* 6^3=(2×3)^3=2^3×3^3* 4^3=(2^2)^3=2^6Substitusikan ke dalam pecahan:Pembilang: 2^5×(2^3×3^3)=2^5+3×3^3=2^8×3^3Penyebut: 3^2×2^6=2^6×3^2Lakukan pembagian dengan mengurangkan eksponen basis yang sama:=2^8−6×3^3−2=2^2×3^1=4×3=12.Jawaban yang benar adalah B.', NULL, NULL),
(546, 546, 'Kunci: A, B, CAnalisis estimasi setiap komponen:* Bilangan 4,98 sangat dekat dengan 5.* Bilangan 19,85 sangat dekat dengan 20.* Bilangan √(82) berada di antara √(81)=9 dan √(100)=10, dan karena 82 sangat dekat dengan 81, maka √(82)≈9,05.Evaluasi opsi jawaban:* Pernyataan A BENAR: Estimasi cepat yang wajar adalah 5×20+9=100+9=109.* Pernyataan B BENAR: Karena 82 paling dekat ke 81 (9^2=81), pendekatan ke bilangan bulat terdekat adalah 9.* Pernyataan C BENAR: Nilai eksak adalah (4,98×19,85)+√(82)=98,853+9,055=107,908, yang berada di antara 100 dan 115.* Pernyataan D SALAH: Nilai hasil perhitungan adalah sekitar 108, sehingga tidak mungkin kurang dari 90.', NULL, NULL),
(547, 547, 'Kunci: ALakukan pembagian bertahap dengan bilangan prima terkecil:840÷2=420420÷2=210210÷2=105105÷3=3535÷5=77÷7=1Faktor prima yang diperoleh:Angka 2 muncul sebanyak 3 kali (2^3),Angka 3 muncul sebanyak 1 kali (3^1),Angka 5 muncul sebanyak 1 kali (5^1),Angka 7 muncul sebanyak 1 kali (7^1).Jadi, faktorisasi prima dari 840 adalah 2^3×3×5×7.Jawaban yang benar adalah A.', NULL, NULL),
(548, 548, 'Kunci: BSebelum membandingkan rasio, kedua besaran harus disamakan satuannya ke dalam satuan yang sama (gram):2,5 kg=2,5×1.000 gram=2.500 gram.Rasio = 750 gram:2.500 gram=750:2500.Bagi kedua bilangan dengan FPB dari 750 dan 2500, yaitu 250:750÷250=32500÷250=10Bentuk paling sederhana dari rasio tersebut adalah 3:10.Jawaban yang benar adalah B.', NULL, NULL),
(549, 549, 'Kunci: A, B, CPenguraian pohon faktor bilangan 360:360=2×180=2×2×90=2×2×2×45=2^3×3×15=2^3×3×3×5=2^3×3^2×5.Evaluasi pernyataan:* Pernyataan A BENAR: Faktorisasi primanya adalah 2^3×3^2×5.* Pernyataan B BENAR: Faktor prima uniknya adalah 2, 3, dan 5 (ada 3 bilangan prima berbeda).* Pernyataan C BENAR: 15 bukan bilangan prima dan diuraikan menjadi 3×5, yang keduanya merupakan bilangan prima.* Pernyataan D SALAH: Faktor prima yang berbeda hanya ada 3 (yaitu 2, 3, dan 5), bukan 4.', NULL, NULL),
(550, 550, 'Kunci: CAnalisis karakteristik perbandingan:* Hubungan A, B, dan D adalah perbandingan berbalik nilai, karena jika salah satu besaran bertambah, besaran pasangannya akan berkurang (hasil kalinya konstan).* Hubungan C merupakan perbandingan senilai karena semakin banyak volume bensin yang dibeli, semakin besar pula total biaya yang harus dibayar dengan tarif per liter yang tetap (hasil baginya bernilai konstan).Jawaban yang benar adalah C.', NULL, NULL),
(551, 551, 'Kunci: CDefinisi bilangan rasional adalah bilangan yang dapat dinyatakan dalam bentuk a/b dengan a,b bilangan bulat dan b≠0:* Opsi A: √(144)=12=12/1 (bilangan rasional).* Opsi B: 0,3333…=1/3 (desimal berulang periodik, merupakan bilangan rasional).* Opsi C: √(50)=√(25×2)=5√(2). Karena √(2) tidak dapat dinyatakan dalam pecahan bulat sederhana dan desimalnya tidak berulang serta tidak berhingga, maka 5√(2) adalah bilangan irasional.* Opsi D: −22/7 sudah dalam bentuk pecahan a/b, sehingga merupakan bilangan rasional.Jawaban yang benar adalah C.', NULL, NULL),
(552, 552, 'Kunci: A, B, CUji kebenaran masing-masing kesamaan:* Kesamaan A: 3/4+2/3=9/12+8/12=17/12 (BENAR).* Kesamaan B: 5/6−1/4=10/12−3/12=7/12 (BENAR).* Kesamaan C: 2×15/5×8=30/40=3/4 (BENAR).* Kesamaan D: 4/7÷2/7=4/7×7/2=28/14=2. Nilai pada opsi adalah 8/49, sehingga kesamaan D SALAH.Kesamaan yang benar adalah A, B, dan C.', NULL, NULL),
(553, 553, 'Kunci: BBentuk baku notasi ilmiah dituliskan sebagai a×10^n dengan 1≤a<10 dan n bilangan bulat:1. Geser tanda koma desimal ke kanan melewati angka tak nol pertama (angka 7) sebanyak 5 langkah:   0,00007865=7,865×10^−5.2. Bulatkan koefisien 7,865 ke dua tempat desimal:   Karena angka ketiga di belakang koma adalah 5, maka angka kedua (6) dibulatkan ke atas menjadi 7.   7,865 dibulatkan menjadi 7,87.Bentuk notasi ilmiahnya adalah 7,87×10^−5.Jawaban yang benar adalah B.', NULL, NULL),
(554, 554, 'Kunci: AHitung laju kecepatan dalam km/jam terlebih dahulu:Kecepatan = Jarak/Waktu=108 km/1,5 jam=72 km/jam.Konversikan km/jam ke meter per detik (m/s):1 km=1.000 meter1 jam=3.600 detikKecepatan = 72×1.000/3.600=72×5/18=4×5=20 m/s.Jawaban yang benar adalah A.', NULL, NULL),
(555, 555, 'Kunci: A, B, CAnalisis denah berskala grafis:* Skala batang menunjukkan tiap ruas 1 cm mewakili 2 meter sebenarnya.  2 meter=200 cm, sehingga rasio skala numerik adalah 1 cm:200 cm=1:200. (Pernyataan A BENAR).* Panjang denah = 7 cm. Ukuran sebenarnya = 7×2 m=14 meter. (Pernyataan B BENAR).* Lebar denah = 3,8 cm. Ukuran sebenarnya = 3,8×2 m=7,6 meter. (Pernyataan C BENAR).* Luas sebenarnya = Panjang sebenarnya × Lebar sebenarnya = 14 m×7,6 m=106,4 m^2.  Pernyataan D menyebutkan 53,2 m^2 (angka ini diperoleh jika membagi 106,4 dengan 2, suatu kesalahan umum), sehingga Pernyataan D SALAH.', NULL, NULL),
(556, 556, 'Kunci: BPada perbandingan berbalik nilai, hasil kali antara pasangan nilai x dan y selalu bernilai konstan (x×y=k):Konstanta k=4×15=60.Verifikasi dengan kolom ketiga: 10×6=60 (sesuai).Maka untuk kolom kedua ketika x=6:6×p=60p=60/6=10.Jawaban yang benar adalah B.', NULL, NULL),
(557, 557, 'Kunci: A, B, DEvaluasi konsep sifat bilangan berpangkat:* Pernyataan A BENAR: Menurut definisi pangkat nol, setiap bilangan real bukan nol dipangkatkan nol bernilai 1.* Pernyataan B BENAR: 2^−3=1/2^3=1/8.* Pernyataan C SALAH: (−3)^4=(−3)×(−3)×(−3)×(−3)=+81, sedangkan −(3^4)=−(81)=−81. Karena 81≠−81, maka kesamaan ini tidak benar.* Pernyataan D BENAR: −2)^−3=1/−2^3=1/−8=−1/8.', NULL, NULL),
(558, 558, 'Kunci: CSederhanakan setiap suku bentuk akar dengan mengeluarkan faktor kuadrat sempurnanya:* √(75)=√(25×3)=5√(3)* 2√(12)=2×√(4×3)=2×2√(3)=4√(3)* √(48)=√(16×3)=4√(3)Lakukan operasi penjumlahan dan pengurangan suku-suku sejenis:5√(3)+4√(3)−4√(3)=5√(3).Jawaban yang benar adalah C.', NULL, NULL),
(559, 559, 'Kunci: A, B, CAturan penentuan FPB dan KPK dari faktorisasi prima:1. FPB mengambil faktor prima yang bersekutu pada kedua bilangan dengan pangkat terendah:   Faktor bersekutu adalah 2 dan 3.   Pangkat terendah untuk 2 adalah 2^2, untuk 3 adalah 3^2.   FPB = 2^2×3^2=4×9=36. (Pernyataan A dan C BENAR).2. KPK mengambil semua faktor prima yang ada dengan pangkat tertinggi masing-masing:   Faktor prima yang ada: 2, 3, 5, 7. (Pernyataan B BENAR).   KPK = 2^3×3^3×5×7. Pernyataan D menjumlahkan pangkat menjadi 2^5×3^5, yang merupakan kesalahan konseptual (Pernyataan D SALAH).', NULL, NULL),
(560, 560, 'Kunci: BAnalisis grafik:1. Grafik I: Berupa garis lurus yang melalui titik asal (0,0). Titik yang dilalui antara lain (1; 2,5), (2; 5), dan (4; 10). Rasio Y/X=2,5/1=5/2=10/4=2,5 (konstan). Ini merupakan ciri utama perbandingan senilai dengan persamaan Y=2,5X. Opsi B benar.2. Grafik II: Berupa kurva hiperbola di kuadran I yang mendekati sumbu tetapi tidak memotongnya. Titik yang dilalui adalah (2,12), (3,8), dan (6,4). Hasil kalinya P×Q=2×12=3×8=6×4=24 (konstan). Ini merupakan perbandingan berbalik nilai dengan persamaan P×Q=24 atau Q=24/P, bukan P+Q=24 (bukan penjumlahan).Jawaban yang benar adalah B.', NULL, NULL),
(561, 561, 'Kunci: A, B, CEvaluasi pernyataan:* Pernyataan A BENAR: Pembulatan ke satuan terdekat: 47,8≈48 dan 5,9≈6. Estimasi K≈48÷6=8.* Pernyataan B BENAR: 8×5,9=47,2. Karena pembilang 47,8>47,2, maka nilai eksak 47,8÷5,9=8,1017… yang memang sedikit lebih besar daripada 8.* Pernyataan C BENAR: Misalkan x=2,363636… Maka 100x=236,3636… Pengurangan: 99x=234⟹x=234/99. Sederhanakan dengan membagi 9 pada pembilang dan penyebut: x=26/11.* Pernyataan D SALAH: Bilangan desimal berulang adalah bilangan rasional karena dapat diubah menjadi bentuk pecahan a/b (yaitu 26/11), bukan bilangan irasional.', NULL, NULL),
(562, 562, 'Kunci: BLangkah-langkah perhitungan diskon bertingkat:1. Diskon pertama (30%):   Potongan harga pertama = 30%×Rp200.000,00=Rp60.000,00.   Harga setelah diskon pertama = Rp200.000,00−Rp60.000,00=Rp140.000,00.2. Diskon kedua (10% dari sisa harga):   Potongan harga kedua = 10%×Rp140.000,00=Rp14.000,00.   Harga akhir yang harus dibayar = Rp140.000,00−Rp14.000,00=Rp126.000,00.Catatan: Diskon 30%+10% tidak sama dengan diskon langsung 40% (yang menghasilkan Rp120.000,00).Jawaban yang benar adalah B.', NULL, NULL),
(563, 563, 'Kunci: A, B, C, DMenentukan banyak paket maksimum dengan mencari FPB dari 180, 90, dan 60:* Faktorisasi prima: 180=2^2×3^2×5* Faktorisasi prima: 90=2×3^2×5* Faktorisasi prima: 60=2^2×3×5FPB = 2×3×5=30 paket. (Pernyataan A BENAR).Menghitung isi masing-masing barang per paket:* Beras = 180 kg÷30=6 kg per paket. (Pernyataan B BENAR).* Minyak goreng = 90 liter÷30=3 liter per paket. (Pernyataan B BENAR).* Gula pasir = 60 kg÷30=2 kg per paket. (Pernyataan C BENAR).* Total isi per paket = 6 kg beras+3 liter minyak+2 kg gula=11 satuan barang. (Pernyataan D BENAR).Seluruh pernyataan A, B, C, dan D bernilai benar.', NULL, NULL),
(564, 564, 'Kunci: BLangkah-langkah penyelesaian:1. Hitung total penurunan suhu:   Kenaikan ketinggian = 1.500 m/100 m=15 kali kenaikan 100 meter.   Besar penurunan suhu = 15×0,6^∘C=9^∘C.2. Hitung suhu akhir di ketinggian 1.500 mdpl:   Suhu puncak = Suhu awal - Penurunan suhu   Suhu puncak = 28^∘C−9^∘C=19^∘C.Jawaban yang benar adalah B.', NULL, NULL),
(565, 565, 'Kunci: CIdentifikasi nilai suhu pada masing-masing kota dari termometer:* Kota A (Puncak): −4^∘C (suhu paling dingin)* Kota B (Dataran Tinggi): 8^∘C* Kota C (Lembah): 16^∘C* Kota D (Pesisir): 29^∘C (suhu paling panas)Selisih suhu udara = Suhu tertinggi - Suhu terendahSelisih = 29^∘C−(−4^∘C)=29+4=33^∘C.Jawaban yang benar adalah C.', NULL, NULL),
(566, 566, 'Kunci: A, B, CAnalisis estimasi dan perhitungan eksak:1. Estimasi belanjaan dengan pembulatan ke ribuan terdekat:   * Sabun: 3×Rp9.000,00=Rp27.000,00   * Kecap: 2×Rp15.000,00=Rp30.000,00   * Gula: 4×Rp17.000,00=Rp68.000,00   Estimasi total = Rp27.000+Rp30.000+Rp68.000=Rp125.000,00. (Pernyataan A BENAR).2. Perhitungan eksak:   * Sabun = 3×8.950=Rp26.850,00   * Kecap = 2×14.800=Rp29.600,00   * Gula = 4×17.100=Rp68.400,00   Total eksak = 26.850+29.600+68.400=Rp124.850,00. (Pernyataan C BENAR).3. Evaluasi uang dan kembalian:   Total uang Ibu = Rp150.000,00>Rp124.850,00 (uang mencukupi, Pernyataan B BENAR).   Sisa kembalian = Rp150.000,00−Rp124.850,00=Rp25.150,00. Karena Rp25.150,00>Rp15.000,00, maka Pernyataan D SALAH.', NULL, NULL),
(567, 567, 'Kunci: BLangkah penyelesaian:1. Tentukan KPK dari periode ketiga petugas (4, 6, 8 hari):   * 4=2^2   * 6=2×3   * 8=2^3   KPK = 2^3×3=8×3=24 hari.   Artinya, mereka akan bertugas bersama setiap 24 hari sekali.2. Tentukan tanggal bertugas berikutnya:   Tanggal awal = 2 Oktober.   Tanggal berikutnya = 2+24=26 Oktober.3. Tentukan hari bertugas berikutnya:   24 hari÷7=3 minggu sisa 3 hari.   3 hari setelah hari Senin adalah hari Kamis (Selasa, Rabu, Kamis).Jadi, mereka bertugas bersama berikutnya pada hari Kamis, 26 Oktober.Jawaban yang benar adalah B.', NULL, NULL),
(568, 568, 'Kunci: A, B, CMenentukan banyak parcel dengan FPB dari 48, 72, dan 96:* 48=2^4×3* 72=2^3×3^2* 96=2^5×3FPB = 2^3×3=8×3=24 paket parcel. (Pernyataan A BENAR).Menghitung komposisi toples dalam setiap paket parcel:* Kastengel: 48÷24=2 toples* Nastar: 72÷24=3 toples (Pernyataan B BENAR)* Putri salju: 96÷24=4 toples* Selisih toples putri salju dan kastengel = 4−2=2 toples. (Pernyataan C BENAR).* Total toples kue dalam 1 paket parcel = 2+3+4=9 toples. Pernyataan D menyebutkan 12 toples, sehingga Pernyataan D SALAH.', NULL, NULL),
(569, 569, 'Kunci: BLangkah-langkah perhitungan:1. Hitung volume air yang masih perlu diisikan:   Volume sisa = Kapasitas maksimum - Volume awal   Volume sisa = 600 liter−450 liter=150 liter.2. Hitung laju pertambahan volume netto (debit netto):   Debit netto = Debit masuk - Debit keluar   Debit netto = 15 liter/menit−5 liter/menit=10 liter/menit.3. Hitung waktu yang diperlukan:   Waktu = Volume sisa/Debit netto=150 liter/10 liter/menit=15 menit.Jawaban yang benar adalah B.', NULL, NULL),
(570, 570, 'Kunci: CGunakan konsep proporsi (perbandingan senilai):Faktor pengali porsi = Porsi target/Porsi awal=30/12=2,5 kali.Kebutuhan tepung terigu = 300 gram×2,5=750 gram.(Alternatif: Tepung per porsi = 300/12=25 gram per porsi. Untuk 30 porsi = 30×25=750 gram).Jawaban yang benar adalah C.', NULL, NULL),
(571, 571, 'Kunci: A, B, CAnalisis rasio efisiensi bahan bakar:* Efisiensi per liter = Jarak tempuh/Bensin terpakai=96 km/8 liter=12 km/liter. (Pernyataan A BENAR).* Kebutuhan bensin untuk jarak 180 km = 180 km/12 km/liter=15 liter. (Pernyataan B BENAR).* Jarak tempuh dengan 25 liter bensin = 25 liter×12 km/liter=300 km. (Pernyataan C BENAR).* Rasio sebenarnya adalah 1 liter bensin untuk setiap 12 km perjalanan. Pernyataan D menyebutkan 15 km per liter, sehingga Pernyataan D SALAH.', NULL, NULL),
(572, 572, 'Kunci: BGunakan konsep perbandingan senilai:1. Hitung harga satuan telur per kilogram:   Harga per kg = Rp126.000,00/4,5 kg=Rp28.000,00 per kg.2. Hitung harga untuk 12 kg telur:   Biaya 12 kg = 12 kg×Rp28.000,00/kg=Rp336.000,00.Jawaban yang benar adalah B.', NULL, NULL),
(573, 573, 'Kunci: A, B, CAnalisis perbandingan berbalik nilai (Jarak=Kecepatan×Waktu=konstan):* Jarak = 60 km/jam×4 jam=240 km. (Pernyataan A BENAR).* Pada kecepatan 80 km/jam: Waktu = 240 km/80 km/jam=3 jam. (Pernyataan B BENAR).* Pada waktu tempuh 4,8 jam: Kecepatan = 240 km/4,8 jam=50 km/jam. 4,8 jam=4 jam+(0,8×60 menit)=4 jam 48 menit. (Pernyataan C BENAR).* Pada perbandingan berbalik nilai, jika kecepatan menjadi dua kali lipat (120 km/jam), waktu tempuh menjadi setengahnya (240/120=2 jam), bukan bertambah menjadi 8 jam. (Pernyataan D SALAH).', NULL, NULL),
(574, 574, 'Kunci: ALangkah-langkah penyelesaian:1. Tentukan mobil paling hemat dari diagram batang:   * Mobil P: 12,5 km/liter   * Mobil Q: 16,0 km/liter (paling hemat karena mampu menempuh jarak terjauh per 1 liter bensin)   * Mobil R: 10,0 km/liter   * Mobil S: 14,5 km/liter2. Hitung volume bensin yang dibutuhkan Mobil Q:   Volume bensin = Jarak total/Efisiensi Mobil Q   Volume bensin = 240 km/16,0 km/liter=15 liter.Jawaban yang benar adalah A.', NULL, NULL),
(575, 575, 'Kunci: A, B, DHitung massa jenis (ρ=m/V) masing-masing cairan:* ρ_W=180/200=0,90 g/cm^3* ρ_X=250/200=1,25 g/cm^3* ρ_Y=210/300=0,70 g/cm^3* ρ_Z=100/100=1,00 g/cm^3Evaluasi pernyataan:* Pernyataan A BENAR: Nilai terkecil adalah Cairan Y (0,70 g/cm^3).* Pernyataan B BENAR: Zat dengan massa jenis paling besar akan tenggelam ke lapisan terbawah (Cairan X dengan 1,25 g/cm^3 terbesar).* Pernyataan C SALAH: ρ_W=0,90 g/cm^3<ρ_Z=1,00 g/cm^3, sehingga massa jenis W lebih kecil dari Z.* Pernyataan D BENAR: Rasio ρ_Y:ρ_Z=0,70:1,00=70:100=7:10.', NULL, NULL),
(576, 576, 'Kunci: BLangkah-langkah perhitungan:1. Hitung konsumsi energi per hari:   * Lampu = 5×20 W×10 jam=1.000 Wh=1,0 kWh.   * Kulkas = 1×100 W×24 jam=2.400 Wh=2,4 kWh.   * Total per hari = 1,0 kWh+2,4 kWh=3,4 kWh per hari.2. Hitung total konsumsi selama 30 hari:   Total kWh sebulan = 3,4 kWh×30=102 kWh.3. Hitung tagihan listrik:   Biaya = 102 kWh×Rp1.500,00/kWh=Rp153.000,00.Jawaban yang benar adalah B.', NULL, NULL),
(577, 577, 'Kunci: A, B, CAnalisis keuangan pedagang:* Biaya beli buah = 100 kg×Rp6.000,00=Rp600.000,00.* Total modal = Biaya beli + Ongkos angkut = Rp600.000+Rp50.000=Rp650.000,00. (Pernyataan A BENAR).* Semangka terjual = 100 kg−10 kg=90 kg.* Penerimaan kotor penjualan = 90 kg×Rp10.000,00=Rp900.000,00. (Pernyataan B BENAR).* Laba bersih = Penerimaan - Total modal = Rp900.000,00−Rp650.000,00=Rp250.000,00. (Pernyataan C BENAR).* Karena hasil penjualan lebih besar dari total modal (laba positif Rp250.000,00), pedagang TIDAK mengalami kerugian. (Pernyataan D SALAH).', NULL, NULL),
(578, 578, 'Kunci: BBerdasarkan grafik, hubungan antara kecepatan (v) dan waktu (t) memenuhi persamaan perbandingan berbalik nilai:v×t=180 km (jarak konstan).Jika waktu tempuh t=2,5 jam, maka kecepatan yang diperlukan:v=180/2,5=180/5/2=180×2/5=36×2=72 km/jam.Jawaban yang benar adalah B.', NULL, NULL),
(579, 579, 'Kunci: A, B, CAnalisis estimasi:* Jarak 438 km dibulatkan ke 440 km, dan efisiensi 10,8 km/L dibulatkan ke 11 km/L.  Estimasi bensin = 440/11=40 liter. (Pernyataan B BENAR).* Nilai eksak bensin = 438/10,8=40,555… liter, yang berada di antara 40 dan 42 liter. (Pernyataan A BENAR).* Estimasi biaya = 40,56 liter×Rp13.250,00=Rp537.420,00. Nilai ini berada pada rentang Rp530.000,00 hingga Rp550.000,00. (Pernyataan C BENAR).* Karena total biaya sekitar Rp537.000,00, uang Rp400.000,00 jelas tidak mencukupi (masih kurang sekitar Rp137.000,00). (Pernyataan D SALAH).', NULL, NULL),
(580, 580, 'Kunci: CLakukan pembagian kapasitas total dengan ukuran per foto menggunakan notasi ilmiah:Jumlah foto = 3,2×10^10/4,8×10^6Jumlah foto = 3,2/4,8×10^10−6Jumlah foto = 2/3×10^4=0,6667×10^4≈6.667 foto.Tuliskan ke dalam bentuk notasi ilmiah:6.667≈6,7×10^3 foto.Jawaban yang benar adalah C.', NULL, NULL),
(581, 581, 'Kunci: A, B, CAnalisis perbandingan senilai kebutuhan pakan:* Konsumsi per ekor = 35 kg/500 ekor=0,07 kg per ekor per hari = 70 gram. (Pernyataan A BENAR).* Jumlah ayam sekarang = 500+200=700 ekor.* Kebutuhan pakan harian untuk 700 ekor = 700×0,07 kg=49 kg per hari. (Pernyataan B BENAR).* Tambahan pakan harian = 49 kg−35 kg=14 kg per hari (atau 200×0,07=14 kg). (Pernyataan C BENAR).* Total pakan sebulan (30 hari) = 49 kg/hari×30 hari=1.470 kg. Pernyataan D menyebutkan 1.050 kg (ini hanya pakan untuk 500 ayam awal: 35×30=1050), sehingga Pernyataan D SALAH.', NULL, NULL),
(582, 582, 'Kunci: BLangkah-langkah analisis beban kerja:1. Hitung total beban kerja proyek (dalam satuan orang-hari):   Beban kerja total = 40 hari×18 pekerja=720 orang-hari.2. Hitung beban kerja yang telah diselesaikan pada 16 hari pertama:   Pekerjaan selesai = 16 hari×18 pekerja=288 orang-hari.3. Hitung sisa beban kerja yang belum selesai:   Sisa beban kerja = 720−288=432 orang-hari.4. Hitung sisa hari kerja efektif yang tersedia:   Waktu terpakai = 16 hari (kerja) + 6 hari (terhenti) = 22 hari.   Sisa hari kerja = 40 hari−22 hari=18 hari kerja.5. Hitung total pekerja yang dibutuhkan pada 18 hari sisa:   Pekerja dibutuhkan = Sisa beban kerja/Sisa hari=432/18=24 orang.6. Hitung pekerja tambahan yang harus direkrut:   Pekerja tambahan = 24 orang−18 orang awal=6 orang pekerja tambahan.Jawaban yang benar adalah B.', NULL, NULL),
(583, 583, 'Kunci: A, B, CAnalisis daya tahan pakan:1. Beban pakan total = 30 sapi×16 hari=480 satuan porsi harian. (Pernyataan A BENAR).2. Pakan yang telah terkonsumsi dalam 4 hari pertama = 30 sapi×4 hari=120 porsi.   Sisa pakan yang tersedia di gudang = 480−120=360 porsi.3. Jumlah sapi yang tersisa setelah penjualan = 30 sapi−10 sapi=20 ekor sapi.4. Lama sisa pakan bertahan = Sisa porsi/Sisa sapi=360/20=18 hari lagi. (Pernyataan B BENAR).5. Total hari pakan bertahan sejak hari pertama = 4 hari+18 hari=22 hari. (Pernyataan C BENAR).6. Awalnya direncanakan 16 hari. Karena bertahan 22 hari, pakan tersebut bertahan 6 hari LEBIH LAMA, bukan lebih cepat. (Pernyataan D SALAH).', NULL, NULL),
(584, 584, 'Kunci: A, B, CAnalisis fungsi tarif:* Tarif Kilat (T_K) = 10.000+3.500x* Tarif Nyaman (T_N) = 16.000+2.500xTitik impas (perpotongan grafik): 10.000+3.500x=16.000+2.500x⟹1.000x=6.000⟹x=6 km.Pada x=6 km: Tarif = 10.000+(3.500×6)=10.000+21.000=Rp31.000,00. (Pernyataan B BENAR).Evaluasi pernyataan:* Untuk x<6 km: Karena tarif dasar Kilat lebih rendah, garis Kilat berada di bawah garis Nyaman (misal x=2 km: Kilat = Rp17.000 < Nyaman = Rp21.000). (Pernyataan A BENAR).* Untuk x=10 km:  Kilat = 10.000+35.000=Rp45.000,00  Nyaman = 16.000+25.000=Rp41.000,00  Penghematan dengan Layanan Nyaman = Rp45.000−Rp41.000=Rp4.000,00. (Pernyataan C BENAR).* Untuk x>6 km, Layanan Nyaman justru lebih murah dari Kilat, sehingga pernyataan D SALAH.', NULL, NULL),
(585, 585, 'Kunci: CLangkah-langkah penalaran matematis:1. Tentukan faktorisasi prima dari bilangan pembagi (120):   120=2^3×3^1×5^1.2. Syarat agar N habis dibagi 120:   Eksponen prima N harus memenuhi: a≥3, b≥1, c≥1.3. Syarat agar N merupakan bilangan kuadrat sempurna:   Semua eksponen faktorisasi prima dari N harus berupa bilangan bulat GENAP non-negatif.4. Tentukan eksponen genap terkecil yang memenuhi syarat batas:   * a adalah bilangan genap terkecil yang ≥3, maka a=4.   * b adalah bilangan genap terkecil yang ≥1, maka b=2.   * c adalah bilangan genap terkecil yang ≥1, maka c=2.5. Hitung nilai bilangan N:   N=2^4×3^2×5^2=16×9×25=144×25=3.600.   (Verifikasi: √(3600)=60 (kuadrat sempurna) dan 3.600÷120=30 (habis dibagi)).Jawaban yang benar adalah C.', NULL, NULL),
(586, 586, 'Kunci: ALangkah-langkah penalaran teoritis:1. Misalkan p=14x dan q=14y dengan FPB(x,y)=1 (relatif prima) dan x<y.2. Rumus KPK dua bilangan: KPK(p,q)=14×x×y=420.   x×y=420/14=30.3. Hubungan penjumlahan: p+q=14x+14y=14(x+y)=154.   x+y=154/14=11.4. Cari pasangan bilangan asli (x,y) yang memenuhi x+y=11 dan x×y=30:   Pasangan faktor dari 30: (1, 30), (2, 15), (3, 10), (5, 6).   Pasangan yang menghasilkan jumlah 11 adalah x=5 dan y=6 (karena 5+6=11 dan 5×6=30).   FPB(5,6)=1 (memenuhi syarat saling prima).5. Hitung nilai p dan q:   p=14×5=70   q=14×6=846. Hitung selisihnya:   q−p=84−70=14.Jawaban yang benar adalah A.', NULL, NULL),
(587, 587, 'Kunci: A, B, CAnalisis teori bilangan faktor pembagi:1. Rumus total faktor pembagi dari 2^a×3^b×5^c adalah a+1)(b+1)(c+1:   Total faktor = (4+1)(2+1)(1+1)=5×3×2=30 faktor. (Pernyataan A BENAR).2. Faktor bernilai ganjil diperoleh jika faktor tersebut tidak memuat faktor prima 2 (yaitu eksponen 2 bernilai 0):   Faktor ganjil = (1)×(2+1)(1+1)=1×3×2=6 faktor. (Pernyataan B BENAR).3. Faktor kelipatan 10 harus memuat sekurang-kurangnya faktor 2^1 dan 5^1:   Pilihan pangkat 2: {1, 2, 3, 4} (ada 4 kemungkinan)   Pilihan pangkat 3: {0, 1, 2} (ada 3 kemungkinan)   Pilihan pangkat 5: {1} (ada 1 kemungkinan)   Banyak faktor kelipatan 10 = 4×3×1=12 faktor. (Pernyataan C BENAR).4. Karena terdapat 6 faktor ganjil (yaitu 1, 3, 9, 5, 15, 45), maka tidak semua faktor dari M bernilai genap. (Pernyataan D SALAH).', NULL, NULL),
(588, 588, 'Kunci: CLangkah penalaran batas pengukuran:1. Tentukan batas nilai panjang (p) dan lebar (l) sebenarnya:   * 23,5 m≤p<24,5 m   * 14,5 m≤l<15,5 m2. Hitung luas maksimum yang mungkin (L_maks):   L_maks=p_maks×l_maks=24,5 m×15,5 m=379,75 m^2.3. Hitung luas minimum yang mungkin (L_min):   L_min=p_min×l_min=23,5 m×14,5 m=340,75 m^2.4. Hitung selisih antara luas maksimum dan minimum:   Selisih = L_maks−L_min=379,75 m^2−340,75 m^2=39,00 m^2.Jawaban yang benar adalah C.', NULL, NULL),
(589, 589, 'Kunci: A, B, CEvaluasi matematis atas klaim penghematan energi:1. Analisis daya:   * Daya lampu awal = 10×60 W=600 W   * Daya lampu baru = 10×8 W=80 W   * Penghematan daya = 600 W−80 W=520 W=0,52 kW. (Pernyataan A BENAR).2. Analisis energi harian:   * Penghematan energi per hari = 0,52 kW×8 jam=4,16 kWh per hari. (Pernyataan B BENAR).3. Analisis penghematan tahunan (365 hari):   * Total kWh dihemat setahun = 4,16 kWh/hari×365 hari=1.518,4 kWh.   * Total biaya dihemat = 1.518,4 kWh×Rp1.500,00/kWh=Rp2.277.600,00.   * Karena Rp2.277.600,00>Rp700.000,00, maka klaim penghematan \'lebih dari Rp700.000,00 per tahun\' terbukti sangat valid dan benar. (Pernyataan C BENAR, Pernyataan D SALAH).', NULL, NULL),
(590, 590, 'Kunci: BLangkah-langkah penalaran rasio mekanik:1. Hitung rasio putaran roda belakang terhadap putaran pedal:   Rasio gir = Banyak gigi depan/Banyak gigi belakang=48/16=3.   Artinya, setiap 1 putaran penuh pedal akan memutar roda belakang sebanyak 3 putaran penuh.2. Hitung keliling roda sepeda (panjang lintasan dalam 1 kali putaran roda):   Diameter d=70 cm=0,7 meter.   Keliling roda = π×d=22/7×0,7 m=2,2 meter.3. Hitung jarak tempuh untuk 1 putaran pedal:   Jarak tempuh = 3 putaran roda×2,2 meter per putaran=6,6 meter.Jawaban yang benar adalah B.', NULL, NULL),
(591, 591, 'Kunci: A, B, CAnalisis campuran larutan:1. Hitung kandungan alkohol murni:   * Dari Larutan A = 20%×300 mL=60 mL alkohol murni.   * Dari Larutan B = 50%×200 mL=100 mL alkohol murni.   * Total alkohol murni = 60 mL+100 mL=160 mL. (Pernyataan A BENAR).2. Hitung total volume larutan gabungan:   * Volume total = 300 mL+200 mL=500 mL.3. Hitung konsentrasi akhir campuran:   * Konsentrasi = Total alkohol murni/Volume total×100%   * Konsentrasi = 160/500×100%=32%. (Pernyataan B BENAR).4. Hitung rasio alkohol terhadap air:   * Volume air murni = 500 mL−160 mL=340 mL.   * Rasio alkohol : air = 160:340=16:34=8:17. (Pernyataan C BENAR).5. Nilai rata-rata langsung 20%+50%/2=35% tidak tepat karena volume kedua larutan yang dicampurkan tidak sama (300 mL vs 200 mL). (Pernyataan D SALAH).', NULL, NULL),
(592, 592, 'Kunci: AGunakan metode perkalian dengan bentuk sekawannya (rasionalisasi pembilang):Bentuk umum setiap bilangan adalah √(n+4)−√(n).Kalikan dengan sekawan √(n+4)+√(n)/√(n+4)+√(n):√(n+4)−√(n)=(n+4)−n/√(n+4)+√(n)=4/√(n+4)+√(n).Perhatikan bahwa pembilang dari keempat bilangan bernilai konstan, yaitu 4.Semakin besar nilai n, maka penyebut √(n+4)+√(n) akan semakin besar, sehingga nilai pecahannya justru akan semakin KECIL.* Penyebut P: √(11)+√(7) (paling kecil)* Penyebut Q: √(15)+√(11)* Penyebut R: √(19)+√(15)* Penyebut S: √(23)+√(19) (paling besar)Karena penyebut P adalah yang terkecil, maka nilai pecahan P=4/√(11)+√(7) adalah yang PALING BESAR di antara semuanya.Jawaban yang benar adalah A.', NULL, NULL),
(593, 593, 'Kunci: A, B, CAnalisis penyamakan eksponen:Cari FPB dari eksponen ketiga bilangan: FPB(60,40,20)=20.Ubah basis ketiga bilangan dengan mempertahankan pangkat 20 di luar kurung:* x=2^60=(2^3)^20=8^20* y=3^40=(3^2)^20=9^20* z=5^20=(5^1)^20=5^20Karena pangkat luar sudah sama-sama 20, kita cukup membandingkan bilangan pokoknya:5<8<9Sehingga berlaku: 5^20<8^20<9^20 atau z<x<y.Evaluasi pernyataan:* Pernyataan A BENAR: y=9^20 adalah yang terbesar.* Pernyataan B BENAR: Urutan dari terkecil adalah z<x<y.* Pernyataan C BENAR: z=5^20 adalah yang terkecil.* Pernyataan D SALAH: Karena 8^20<9^20, maka x lebih kecil daripada y, bukan lebih besar.', NULL, NULL),
(594, 594, 'Kunci: CLangkah-langkah pemodelan aljabar bilangan bulat:1. Tentukan banyak soal yang tidak dijawab:   Soal kosong = 50 butir−45 butir=5 butir soal.   Skor dari soal kosong = 5×(−1)=−5 poin.2. Misalkan:   Banyak jawaban benar = B   Banyak jawaban salah = 45−B3. Susun persamaan total skor:   Total skor=(B×4)+[(45−B)×(−2)]+(−5)=127   4B−90+2B−5=127   6B−95=127   6B=127+95   6B=222   B=222/6=37 butir.Verifikasi:* Benar: 37×4=148* Salah: (45−37)×(−2)=8×(−2)=−16* Kosong: 5×(−1)=−5* Total = 148−16−5=127 (sesuai).Jawaban yang benar adalah C.', NULL, NULL),
(595, 595, 'Kunci: A, B, CAnalisis skala denah (1 : 150 artinya 1 cm pada gambar mewakili 1,5 meter sebenarnya):1. Ruang A (Aula Utama):   Panjang sebenarnya = 5×1,5 m=7,5 m; Lebar sebenarnya = 5×1,5 m=7,5 m.   Luas sebenarnya = 7,5 m×7,5 m=56,25 m^2. (Pernyataan A BENAR).2. Ruang B (Ruang Rapat):   Panjang sebenarnya = 3×1,5 m=4,5 m; Lebar sebenarnya = 3×1,5 m=4,5 m.   Luas sebenarnya = 4,5 m×4,5 m=20,25 m^2. (Pernyataan B BENAR).3. Anggaran ubin granit Ruang B:   Biaya = Luas B × Harga per m² = 20,25 m^2×Rp200.000,00/m^2=Rp4.050.000,00. (Pernyataan C BENAR).4. Rasio luas Aula Utama terhadap Ruang Rapat:   Luas A : Luas B = 56,25:20,25=2.500/900=25:9 (merupakan kuadrat dari rasio sisi 5:3, yaitu 5/3^2=25/9). Pernyataan D menyebutkan 5 : 3 yang merupakan rasio panjang sisi, bukan rasio luas. (Pernyataan D SALAH).', NULL, NULL),
(596, 596, 'Kunci: A, B, CAnalisis laju pengisian (bagian kolam per jam):* Laju Pompa 1 = 1/6 bagian/jam* Laju Pompa 2 = 1/4 bagian/jam (waktu tercepat, maka debit terbesar). (Pernyataan A BENAR).* Laju Pompa 3 = 1/12 bagian/jamEvaluasi skenario gabungan:1. Ketiga pompa bekerja bersama:   Laju gabungan = 1/6+1/4+1/12=2+3+1/12=6/12=1/2 bagian per jam.   Waktu pengisian = 1/1/2=2 jam penuh. (Pernyataan B BENAR).2. Hanya Pompa 1 dan Pompa 2 bekerja bersama:   Laju gabungan = 1/6+1/4=2+3/12=5/12 bagian per jam.   Waktu pengisian = 12/5 jam=2,4 jam=2 jam+(0,4×60 menit)=2 jam 24 menit. (Pernyataan C BENAR).3. Waktu kerja bersama (2 jam) jelas lebih singkat daripada Pompa 2 sendirian (4 jam). (Pernyataan D SALAH).', NULL, NULL),
(597, 597, 'Kunci: BLakukan pembagian massa total tetesan air dengan massa satu molekul air:Jumlah molekul = Massa 1 tetes/Massa 1 molekulJumlah molekul = 6,0×10^−2/3,0×10^−23Sesuai dengan sifat perpangkatan eksponen pada pembagian:= 6,0/3,0×10^−2−(−23)= 2,0×10^−2+23= 2,0×10^21 molekul air.Jawaban yang benar adalah B.', NULL, NULL),
(598, 598, 'Kunci: A, B, CAnalisis KPK dari interval waktu kedip:1. Faktorisasi prima masing-masing interval:   * 12=2^2×3   * 15=3×5   * 20=2^2×5   KPK(12,15,20)=2^2×3×5=4×15=60 detik. (Pernyataan A BENAR).2. Waktu nyala bersama kedua:   19.30.00+60 detik=19.31.00 WIB. (Pernyataan B BENAR).3. Frekuensi nyala bersama dalam 15 menit (15×60 detik=900 detik):   Frekuensi = 15 menit/1 menit=15 kali. (Pernyataan C BENAR).4. KPK dari Lampu Merah (12) dan Lampu Hijau (20):   KPK(12,20)=2^2×3×5=60 detik, bukan 30 detik (angka 30 bukan kelipatan dari 12 maupun 20). (Pernyataan D SALAH).', NULL, NULL),
(599, 599, 'Kunci: ALangkah-langkah penalaran kurva proyek:1. Hitung total volume kerja awal (orang-hari):   Total volume = 60 hari×15 pekerja=900 orang-hari.2. Hitung volume kerja yang sudah selesai pada hari ke-20:   Volume selesai = 20 hari×15 pekerja=300 orang-hari (setara dengan 33,33%).3. Hitung sisa volume kerja yang harus diselesaikan:   Sisa volume = 900−300=600 orang-hari.4. Hitung sisa waktu kalender efektif:   Mulai hari ke-30 hingga hari ke-60, waktu tersisa = 60−30=30 hari kalender.5. Hitung kebutuhan total pekerja pada sisa 30 hari:   Total pekerja = Sisa volume/Sisa hari=600/30=20 orang pekerja.6. Hitung pekerja tambahan yang harus didatangkan:   Pekerja tambahan = 20 orang−15 orang pekerja awal=5 orang.Jawaban yang benar adalah A.', NULL, NULL),
(600, 600, 'Kunci: A, B, CPemodelan matematika fungsi eksponensial:Fungsi populasi: N(t)=N_0×2^t/T, dengan N_0=200 dan periode T=20 menit.Evaluasi skenario waktu:1. Untuk t=2 jam=120 menit:   * Banyak siklus pembelahan n=120/20=6 kali pembelahan. (Pernyataan A BENAR).   * N(2 jam)=200×2^6=200×64=12.800 sel. (Pernyataan B BENAR).2. Untuk t=3 jam=180 menit:   * Banyak siklus n=180/20=9 kali pembelahan.   * N(3 jam)=200×2^9=200×512=102.400 sel.   * Tulis dalam notasi ilmiah: 102.400=1,024×10^5 sel. (Pernyataan C BENAR).3. Pertumbuhan ini merupakan deret geometri/eksponensial (berlipat ganda setiap periode), bukan pertumbuhan linier aritmetika. (Pernyataan D SALAH).', NULL, NULL),
(601, 601, 'Kunci: CLangkah-langkah penalaran laju perubahan debit:1. Tentukan laju pengosongan per menit masing-masing pipa:   * Pipa A mengosongkan 1/30 bagian tangki per menit.   * Pipa B mengosongkan 1/20 bagian tangki per menit.2. Tentukan laju pengosongan gabungan kedua pipa saat bekerja bersama-sama:   Laju gabungan = 1/30+1/20   Samakan penyebut ke KPK dari 30 dan 20, yaitu 60:   Laju gabungan = 2/60+3/60=5/60=1/12 bagian tangki per menit.3. Tentukan waktu total yang dibutuhkan hingga tangki kosong penuh:   Waktu = 1/1/12=12 menit.Jawaban yang benar adalah C.', NULL, NULL),
(602, 602, 'Jawaban: CPertidaksamaan ditandai oleh ungkapan seperti “tidak boleh lebih dari”, “paling sedikit”, atau “kurang dari”. Pilihan C dapat ditulis x ≤ 500, sedangkan pilihan lainnya menyatakan kesamaan (persamaan).', NULL, NULL),
(603, 603, 'Jawaban: DPersamaan linear satu variabel hanya memuat satu variabel berpangkat 1. Pilihan D memenuhi syarat tersebut. A dan E berpangkat 2, B memuat dua variabel, dan C memuat variabel di penyebut.', NULL, NULL),
(604, 604, 'Jawaban: A4x − 2x = 9 + 72x = 16x = 8.', NULL, NULL),
(605, 605, 'Jawaban: B3x + 6 = 2x + 113x − 2x = 11 − 6x = 5.', NULL, NULL),
(606, 606, 'Jawaban: E3x > 10 + 53x > 15x > 5.', NULL, NULL),
(607, 607, 'Jawaban: AKedua ruas dibagi −4, sehingga tanda pertidaksamaan berbalik.−4x ≥ 12 → x ≤ 12 ÷ (−4) → x ≤ −3.', NULL, NULL),
(608, 608, 'Jawaban: D3a − a = −4 − 22a = −6a = −3.', NULL, NULL),
(609, 609, 'Jawaban: Bx/3 = 5 − 2 = 3x = 3 × 3 = 9.', NULL, NULL),
(610, 610, 'Jawaban: CSubstitusi kedua titik ke persamaan. Untuk x + 2y = 4: titik (4, 0) → 4 + 0 = 4 ✓ dan titik (0, 2) → 0 + 4 = 4 ✓.Pilihan lain tidak dipenuhi oleh salah satu titik.', NULL, NULL),
(611, 611, 'Jawaban: DSubstitusi ke 3x − y: (3, 2) → 9 − 2 = 7 ✓. Pilihan lain menghasilkan −1, 5, 8, dan 8.', NULL, NULL),
(612, 612, 'Jawaban: EJumlahkan kedua persamaan: 2x = 12 → x = 6.y = 9 − 6 = 3.2x + y = 12 + 3 = 15.', NULL, NULL),
(613, 613, 'Jawaban: A“Minimal” berarti tidak kurang dari, sehingga tinggi badan boleh sama dengan atau lebih dari 140 cm: t ≥ 140.', NULL, NULL),
(614, 614, 'Jawaban: C2x ≤ 6 → x ≤ 3.Bilangan asli yang memenuhi adalah 1, 2, dan 3, sehingga ada 3 bilangan.', NULL, NULL),
(615, 615, 'Jawaban: BPenyelesaian 3x − 6 = 12 adalah x = 6. Persamaan x − 2 = 4 juga memberi x = 6, sehingga ekuivalen. Pilihan lain menghasilkan penyelesaian yang berbeda.', NULL, NULL),
(616, 616, 'Jawaban: Dx < 3 + 4 → x < 7.Bilangan bulat terbesar yang kurang dari 7 adalah 6.', NULL, NULL),
(617, 617, 'Jawaban: E2x − y = 2(3) − (−4) = 6 + 4 = 10.', NULL, NULL),
(618, 618, 'Jawaban: AKalikan kedua ruas dengan 3: 2x − 1 = 15.2x = 16 → x = 8.', NULL, NULL),
(619, 619, 'Jawaban: B5 + 15 = 3x + 2x20 = 5xx = 4.', NULL, NULL),
(620, 620, 'Jawaban: CSubstitusi y = x − 1: x + (x − 1) = 7.2x − 1 = 7 → 2x = 8 → x = 4.', NULL, NULL),
(621, 621, 'Jawaban: E2x ≥ 6 + 42x ≥ 10x ≥ 5.', NULL, NULL),
(622, 622, 'Jawaban: B“3 kali usia Dodi” ditulis 3x, dan “5 tahun lebih dari” berarti ditambah 5. Jadi 3x + 5 = 44.', NULL, NULL),
(623, 623, 'Jawaban: DKeliling = 2(p + l) = 2((3x + 2) + (x + 4)) = 2(4x + 6) = 68.4x + 6 = 34 → 4x = 28 → x = 7.', NULL, NULL),
(624, 624, 'Jawaban: AMisalkan lama parkir t jam. Model: 2.000 + 1.000(t − 1) ≤ 7.000.1.000(t − 1) ≤ 5.000 → t − 1 ≤ 5 → t ≤ 6 jam.', NULL, NULL),
(625, 625, 'Jawaban: CTotal beban = 60 + 25n. “Paling banyak 400 kg” berarti tidak boleh melebihi 400, sehingga 60 + 25n ≤ 400.', NULL, NULL),
(626, 626, 'Jawaban: EMisalkan banyak tiket n. Model: 35.000n + 5.000 ≤ 180.000.35.000n ≤ 175.000 → n ≤ 5.', NULL, NULL),
(627, 627, 'Jawaban: AMisalkan beras = b dan gula = g. Model: 3b + 2g = 62.000 dan 2b + g = 37.000.Dari persamaan kedua, g = 37.000 − 2b. Substitusi: 3b + 74.000 − 4b = 62.000 → b = 12.000, sehingga g = 13.000.Jadi b + g = 25.000.', NULL, NULL),
(628, 628, 'Jawaban: BMisalkan bilangan kedua x, bilangan pertama x + 8. Model: x + (x + 8) = 52.2x = 44 → x = 22 (bilangan lainnya 30).', NULL, NULL),
(629, 629, 'Jawaban: DMisalkan banyak minggu w. Model: 90.000 + 20.000w ≥ 250.000.20.000w ≥ 160.000 → w ≥ 8.', NULL, NULL),
(630, 630, 'Jawaban: CMisalkan banyak hari h. Model: 4 + 1,5h ≤ 20.1,5h ≤ 16 → h ≤ 10,67. Karena hari penuh, nilai maksimalnya 10 hari.', NULL, NULL),
(631, 631, 'Jawaban: EKeliling = 2(2x + 1) + (x + 7) = 5x + 9 = 44.5x = 35 → x = 7. Panjang kaki = 2(7) + 1 = 15 cm.', NULL, NULL),
(632, 632, 'Jawaban: A6x − 3 + 5 = 4x + 12 − 26x + 2 = 4x + 102x = 8 → x = 4, sehingga n = 4.2n + 1 = 2(4) + 1 = 9.', NULL, NULL),
(633, 633, 'Jawaban: BMisalkan uang Ali = x dan Budi = y. Model: x + y = 95.000 dan x − y = 15.000.Jumlahkan: 2x = 110.000 → x = Rp55.000,00.', NULL, NULL),
(634, 634, 'Jawaban: CMisalkan waktu bertemu t jam. Jumlah jarak tempuh kedua mobil sama dengan jarak P–Q.60t + 40t = 300 → 100t = 300 → t = 3 jam.', NULL, NULL),
(635, 635, 'Jawaban: DMisalkan harga pulpen = p, harga buku = 2p. Model: 5(2p) + 3p = 65.000.13p = 65.000 → p = 5.000. Harga buku = 2p = Rp10.000,00.', NULL, NULL),
(636, 636, 'Jawaban: ETotal belanja = 3.000x + 2.000y. “Tidak lebih dari” berarti kurang dari atau sama dengan (≤), sehingga 3.000x + 2.000y ≤ 20.000.', NULL, NULL),
(637, 637, 'Jawaban: APersamaan garis yang melalui (0, 6) dan (3, 0) adalah 2x + y = 6.Uji titik (0, 0) yang berada di bawah garis: 0 ≤ 6 benar, sehingga daerah arsiran adalah 2x + y ≤ 6. Garis tegas berarti tanda sama dengan disertakan.', NULL, NULL),
(638, 638, 'Jawaban: BMisalkan sepeda = s dan becak = t. Model: s + t = 25 dan 2s + 3t = 68.Substitusi s = 25 − t: 50 − 2t + 3t = 68 → t = 18.', NULL, NULL),
(639, 639, 'Jawaban: CPotongan harga = 250.000 − 200.000 = 50.000.x% × 250.000 = 50.000 → x = 20.', NULL, NULL),
(640, 640, 'Jawaban: DMisalkan lembur h jam. Model: 2.000.000 + 50.000h ≥ 2.650.000.50.000h ≥ 650.000 → h ≥ 13.', NULL, NULL),
(641, 641, 'Jawaban: EKeliling = 2((2x + 3) + (x − 1)) = 2(3x + 2) = 6x + 4.Model: 6x + 4 ≥ 58 → 6x ≥ 54 → x ≥ 9.', NULL, NULL),
(642, 642, 'Jawaban: CSifat distributif: −2(x − 3) = −2x + 6, bukan −2x − 6.Penyelesaian yang benar: −2x + 6 = 4 − x → −x = −2 → x = 2.', NULL, NULL),
(643, 643, 'Jawaban: AUbah menjadi (a − 2 − 3)x = −2 − 6, yaitu (a − 5)x = −8.Persamaan tidak memiliki penyelesaian bila koefisien x sama dengan 0 sedangkan ruas kanan tidak 0. Jadi a − 5 = 0 → a = 5 (0 = −8 tidak mungkin).', NULL, NULL),
(644, 644, 'Jawaban: ERuas kiri: 3x − 6. Agar 3x − 6 = 3x + m benar untuk setiap x, haruslah m = −6.', NULL, NULL),
(645, 645, 'Jawaban: DKurangi 1 pada semua bagian: −6 ≤ 3x < 15.Bagi 3: −2 ≤ x < 5. Bilangan bulatnya: −2, −1, 0, 1, 2, 3, 4, yaitu 7 bilangan.', NULL, NULL),
(646, 646, 'Jawaban: BMisalkan bilangan tersebut n, n + 1, n + 2. Model: 3n + 3 = 5n − 9.12 = 2n → n = 6. Ketiga bilangan adalah 6, 7, 8 sehingga yang terbesar 8.', NULL, NULL),
(647, 647, 'Jawaban: CKalikan persamaan pertama dengan 2 dan persamaan kedua dengan 3: 4a + 6b = 32 dan 9a − 6b = 33.Jumlahkan: 13a = 65 → a = 5, lalu b = 2.3a + b = 15 + 2 = 17.', NULL, NULL),
(648, 648, 'Jawaban: DMisalkan usia Tika sekarang t, usia Rani 3t. Model: (3t − 5) + (t − 5) = 30.4t = 40 → t = 10, sehingga usia Rani sekarang 30 tahun.Usia Rani 6 tahun lagi = 36 tahun.', NULL, NULL),
(649, 649, 'Jawaban: EPersamaan kedua adalah dua kali persamaan pertama, sehingga keduanya menggambarkan garis yang sama. Setiap titik pada garis tersebut memenuhi kedua persamaan, jadi terdapat tak hingga banyak penyelesaian.', NULL, NULL),
(650, 650, 'Jawaban: ASetiap tambahan 1 segitiga menambah 2 batang, sehingga rumus banyak batang adalah 2n + c. Untuk n = 1: 2 + c = 3 → c = 1.Rumus: 2n + 1. Untuk n = 25: 2(25) + 1 = 51 batang.', NULL, NULL),
(651, 651, 'Jawaban: BMembagi kedua ruas dengan bilangan negatif (−3) membalik tanda pertidaksamaan.−3x > 9 → x < −3.', NULL, NULL),
(652, 652, 'Jawaban: CMisalkan pemakaian g GB. Y lebih murah jika 50.000 + 3.000g < 30.000 + 5.000g.20.000 < 2.000g → g > 10. Jadi pemakaian harus lebih dari 10 GB.', NULL, NULL),
(653, 653, 'Jawaban: ENilai x yang mungkin: −1, 0, 1, 2, 3, 4.Karena koefisien x negatif, y paling kecil dicapai saat x paling besar, yaitu x = 4: y = 3 − 8 = −5.', NULL, NULL),
(654, 654, 'Jawaban: AMengalikan kedua ruas a > b dengan bilangan negatif membalik tanda, sehingga ac < bc.B salah karena penambahan tidak mengubah tanda (a + c > b + c). C dan D juga bertanda terbalik. E tidak selalu benar (misal a = 1, b = −2).', NULL, NULL),
(655, 655, 'Jawaban: DMisalkan tiket dewasa = d dan anak = a. Model: 3d + 2a = 215.000 dan 2d + 4a = 210.000 (setara d + 2a = 105.000).Dari persamaan kedua, d = 105.000 − 2a. Substitusi: 315.000 − 6a + 2a = 215.000 → a = 25.000, d = 55.000.Rombongan III: 55.000 + 3(25.000) = Rp130.000,00.', NULL, NULL),
(656, 656, 'Jawaban: B2x = 5 + 3ax = (5 + 3a)/2.', NULL, NULL),
(657, 657, 'Jawaban: CSubstitusi x = 2: 2a − 7 = 3(2) + 1 = 7.2a = 14 → a = 7.', NULL, NULL),
(658, 658, 'Jawaban: DMisalkan digit puluhan x dan digit satuan y. Model: x + y = 9 dan (10y + x) − (10x + y) = 27.Persamaan kedua: 9y − 9x = 27 → y − x = 3. Bersama x + y = 9 diperoleh x = 3 dan y = 6.Bilangan semula 36 (bilangan tukarnya 63; 63 − 36 = 27).', NULL, NULL),
(659, 659, 'Jawaban: EKalikan persamaan pertama dengan 3: 3x + 6y = 15.Agar sama dengan persamaan kedua (3x + ky = 15), haruslah k = 6.', NULL, NULL),
(660, 660, 'Jawaban: ABagi persamaan kedua dengan 2: x + y = 10. Nilai x + y tidak mungkin sekaligus 8 dan 10.Jadi kedua garis sejajar dan sistem tidak memiliki penyelesaian; pendapat Rina keliru.', NULL, NULL),
(661, 661, 'Jawaban: BBanyak kursi pada baris ke-n adalah 6 + 2(n − 1) = 2n + 4.2n + 4 ≥ 40 → n ≥ 18. Baris ke-17 hanya 38 kursi, sedangkan baris ke-18 memiliki 40 kursi.', NULL, NULL),
(662, 662, 'Jawaban: CPembahasan:Suku-suku pada bentuk aljabar dipisahkan oleh tanda penjumlahan atau pengurangan. Suku-suku pada bentuk tersebut adalah 3x^2, -5x, 2y, dan -7. Jadi, terdapat 4 suku.', NULL, NULL),
(663, 663, 'Jawaban: CPembahasan:Koefisien adalah angka yang melekat/menerangi suatu variabel. Variabel x memiliki angka di depannya beserta tandanya, yaitu -7.', NULL, NULL),
(664, 664, 'Jawaban: DPembahasan:Konstanta adalah suku pada bentuk aljabar yang berupa bilangan saja dan tidak memuat variabel. Nilai konstanta pada bentuk tersebut adalah -12.', NULL, NULL),
(665, 665, 'Jawaban: DPembahasan:Suku yang berupa bilangan berdiri sendiri tanpa variabel bernilai 5 terdapat pada bentuk 3x^2 + 2x + 5.', NULL, NULL),
(666, 666, 'Jawaban: BPembahasan:Suku sejenis adalah suku-suku yang memiliki variabel dan pangkat variabel yang sama. Pasangan suku sejenis pada bentuk ini adalah 5x^2 dan 2x^2.', NULL, NULL),
(667, 667, 'Jawaban: CPembahasan:Pada pilihan C, 4ab^2 memiliki variabel a pangkat 1 dan b pangkat 2, sedangkan 4a^2b memiliki a pangkat 2 dan b pangkat 1. Variabel dan pangkatnya tidak sama persis, sehingga bukan suku sejenis.', NULL, NULL),
(668, 668, 'Jawaban: BPembahasan:Suku (i)\\ 4x dan (iii)\\ 7x memiliki variabel dan pangkat yang sama, yaitu x.', NULL, NULL),
(669, 669, 'Jawaban: APembahasan:Mengelompokkan suku sejenis berarti mendekatkan suku-suku yang memiliki variabel sama beserta tanda operasinya, yaitu 8a dengan 2a serta -3b dengan 7b', NULL, NULL),
(670, 670, 'Jawaban: BPembahasan:Nomor 1 (2a^2b) dan Nomor 3 (7a^2b) keduanya memuat variabel a^2b.dengan 2a serta -3b dengan 7b', NULL, NULL),
(671, 671, 'Jawaban: CPembahasan:Pilihan C memuat tiga variabel berbeda, yaitu p, q, dan r.', NULL, NULL),
(672, 672, 'Jawaban: APembahasan: (5 + 3 - 2)x = 6x', NULL, NULL),
(673, 673, 'Jawaban: BPembahasan: = (7a + 2a) + (-4b + 9b) = 9a + 5b.', NULL, NULL),
(674, 674, 'Jawaban: BPembahasan: = 3x + 2x + 5y - 8y= 5x - 3y.', NULL, NULL),
(675, 675, 'Jawaban: APembahasan: = (8p - 3) - (5p + 4) = 8p - 3 - 5p - 4 = (8p - 5p) + (-3 - 4) = 3p - 7', NULL, NULL),
(676, 676, 'Jawaban: CPembahasan: Sifat distributif: 4.2x – 4.3y = 8x - 12y.', NULL, NULL),
(677, 677, 'Jawaban: APembahasan: = (-3a x  2a) + (-3a x -5b)= -6a^2 + 15ab.', NULL, NULL),
(678, 678, 'Jawaban: APembahasan: = 12/4 . x^3/x . y^2/y = 3 . x^3 -1 . y^2-1 = 3x^2 y', NULL, NULL),
(679, 679, 'Jawaban: BPembahasan: Substitusi nilai: 2(3) - 3(-2) = 6 + 6 = 12.', NULL, NULL),
(680, 680, 'Jawaban: APembahasan: = 6/2 . a^2/a . b= 3ab.', NULL, NULL),
(681, 681, 'Jawaban: CPembahasan: = (-4)^2 - 3(-4) = 16 + 12 = 28.', NULL, NULL),
(682, 682, 'Jawaban: CPembahasan:Total harga buku = 4 x X = 4x. Total harga pensil = 3 x Y = 3y.Total pembayaran = 4x + 3y.', NULL, NULL),
(683, 683, 'Jawaban: APembahasan:Sisa uang = Uang awal - Total belanjaan = R - 2b', NULL, NULL),
(684, 684, 'Jawaban: BPembahasan:Dua kali p ditambah 7 > 2p + 7 Tiga kali p dikurangi 4 > 3p - 4.Persamaan: 2p + 7 = 3p - 4.', NULL, NULL),
(685, 685, 'Jawaban: APembahasan:Lebar = x. Panjang = x + 5.Luas = panjang x lebar = (x + 5) . x = x^2 + 5x.', NULL, NULL),
(686, 686, 'Jawaban: BPembahasan:Umur Ani sekarang = a + n.Umur Ibu sekarang = 4 x Umur Ani sekarang = 4(a + n', NULL, NULL),
(687, 687, 'Jawaban: CPembahasan:Total biaya Y = Tarif awal + (Tarif per km x Jarak) = Ro + t . k', NULL, NULL),
(688, 688, 'Jawaban: APembahasan:Siswa I = x. Siswa II = 2x. Siswa III = M - (x + 2x) = M - 3x.', NULL, NULL),
(689, 689, 'Jawaban: BPembahasan:Substitusi x = 5: Panjang = 2(5) + 3 = 13 m. Lebar = 5 - 1 = 4 m. Luas = 13x 4 = 52 m^2.', NULL, NULL),
(690, 690, 'Jawaban: BPembahasan:Total belanja = 3x + 2y.Uang kembalian = Uang bayar -Total belanja = 200.000 - (3x + 2y)', NULL, NULL),
(691, 691, 'Jawaban: BPembahasan:Substitusi a = 6:Panjang = 3(6) + 2 = 20 cm. Lebar = 6 + 4 = 10 cm. Keliling = 2 x (Panjang) + (Lebar) = 2 x (20 + 10) = 60 cm.', NULL, NULL),
(692, 692, 'Jawaban: BPembahasan: Jam ke-1 = 100.000. Sisa jam = 4 - 1 = 3 jam dengan tarif x per jam = 3x. Total biaya = 100.000 + 3x', NULL, NULL),
(693, 693, 'Jawaban: APembahasan: Untung per kue = 3.200 - 2.500 = 700. Total keuntungan = 700 x n = 700n', NULL, NULL),
(694, 694, 'Jawaban: CPembahasan: Jarak = Kecepatan x Waktu = (2v + 10) x 3 = 6v + 30 km', NULL, NULL),
(695, 695, 'Jawaban: APembahasan: Panjang sisi segitiga sama sisi = Keliling / 3 = 9x – 12 / 3 = 3x - 4 cm', NULL, NULL),
(696, 696, 'Jawaban: BPembahasan: Angka 50.000 bersifat konstan (tidak bergantung pada x), sehingga merepresentasikan biaya tetap/tarif awal pemesanan sebelum perjalanan dimulai (x = 0).', NULL, NULL),
(697, 697, 'Jawaban: BPembahasan: H = 0,8x = 80% x, artinya pembeli membayar 80% dari harga asli x (atau mendapat diskon sebesar 20%).', NULL, NULL),
(698, 698, 'Jawaban: CPembahasan: Variabel 15.000 terikat dengan pengali m (bulan), menunjukkan bahwa setiap pertambahan 1 bulan, tabungan bertambah sebesar Rp15.000,00.', NULL, NULL),
(699, 699, 'Jawaban: BPembahasan: Nilai P(n) = 0 berarti profit/keuntungan bernilai 0, yang menandakan kondisi balik modal atau titik impas (break-even point).', NULL, NULL),
(700, 700, 'Jawaban: BPembahasan: Tanda negatif menandakan pengurangan, dan angka 4 berpasangan dengan t (menit), artinya volume air berkurang sebanyak 4 liter per menit.', NULL, NULL),
(701, 701, 'Jawaban: APembahasan: Jika s = 12 km, maka B(12) = 12 / 12 = 1 liter. Artinya 1 liter bensin menempuh jarak 12 km', NULL, NULL),
(702, 702, 'Jawaban: APembahasan:C = 2(3x - 2y + 5) - (2x + 4y - 3)C = (6x - 4y + 10) - 2x - 4y + 3C = (6x - 2x) + (-4y - 4y) + (10 + 3) = 4x - 8y + 13', NULL, NULL),
(703, 703, 'Jawaban: BPembahasan:K = 2(panjang+lebar) K = 2((3x + 2) + (x - 1)) K = 2(4x + 1) = 8x + 2', NULL, NULL),
(704, 704, 'Jawaban: BPembahasan:Menggunakan identitas aljabar selisih dua kuadrat: x^2 - y^2 = (x + y)(x – y)36 = (x + y) . 4 > (x + y) = 36/4 = 9.', NULL, NULL),
(705, 705, 'Jawaban: APembahasan:Pembilang ^2+x-6 = (x+3)(x-2). Jika penyebut adalah x^2-4x+4 = (x-2)^2, pembagiannya memberikan x+3 / x-2.', NULL, NULL),
(706, 706, 'Jawaban: APembahasan:Gunakan identitas (a + b)^2 = a^2 + 2ab + b^2 7^2 = a^2 + 2(10) + b^249 = a^2 + 20 + b^2 > a^2 + b^2 = 49 - 20 = 29', NULL, NULL),
(707, 707, 'Jawaban: BPembahasan:Luas 2 – Luas 1 = 39 (x + 3)^2 - x^2 = 39(x^2 + 6x + 9) - x^2 = 39 6x + 9 = 39 > 6x = 30 > x = 5.', NULL, NULL),
(708, 708, 'Jawaban: APembahasan:Umur Andi sekarang = x, umur Ayah = 3x. Umur Andi 5 tahun lagi = x + 5,Umur Ayah 5 tahun lagi = 3x + 5. Jumlah umur 5 tahun lagi = (x + 5) + (3x + 5) = 4x + 10. Persamaan: 4x + 10 = 58 > 4x = 48 > x = 12.', NULL, NULL),
(709, 709, 'Jawaban: APembahasan:Air keluar = 4(2x - 3) = 8x - 12. Volume awal (y) = Air keluar + Sisa air y = (8x - 12) + 15 = 8x + 3.', NULL, NULL),
(710, 710, 'Jawaban: CPembahasan:Misal bilangan tersebut: n, n+1, n+2. Jumlah = 3n + 3 = 45 > 3n = 42 > n = 14. Bilangan terbesar = n + 2 = 14 + 2 = 16.', NULL, NULL),
(711, 711, 'Jawaban: APembahasan:Besar diskon = x/100 .  H Harga bayar = H – x/100 . H = H (1 – x/100', NULL, NULL),
(712, 712, 'Jawaban: APembahasan: Pada langkah 1, perkalian -2(x - 5) menghasilkan -2x + 10 (bukan -2x - 10). Jadi kesalahan ada pada Langkah 1', NULL, NULL),
(713, 713, 'Jawaban: APembahasan: 6x^2y / 2x = (6/2) . (x^2/x) . y = 3xy Budi Benar', NULL, NULL),
(714, 714, 'Jawaban: BPembahasan: Penjabaran (a + b)^2 = (a + b)(a + b) = a^2 + ab + ba + b^2 = a^2 + 2ab + b^2. Pernyataan awal mengabaikan suku tengah 2ab.', NULL, NULL),
(715, 715, 'Jawaban: APembahasan: Dua bilangan yang jika dijumlahkan bernilai -5 dan dikalikan bernilai 6 adalah -2 dan -3. Maka faktorsasi yang benar adalah (x - 2)(x - 3).', NULL, NULL),
(716, 716, 'Jawaban: CPembahasan: Pola umum (a - b)(a + b) = a^2 - b^2. Untuk (2x - 5)(2x + 5) = (2x)^2 - (5)^2 = 4x^2 - 25', NULL, NULL),
(717, 717, 'Jawaban: BPembahasan: Jika pembagi (penyebut) x + 2 makin besar, maka nilai pecahan 1/x+2 akan semakin kecil dan mendekati 0', NULL, NULL),
(718, 718, 'Jawaban: BPembahasan: Karena (q - p) = -(p - q), maka: p – q / q - p = p – q / -(p - q) = -1.', NULL, NULL),
(719, 719, 'Jawaban: APembahasan:   S_1 = 1 = 1^2  S_2 = 1 + 3 = 4 = 2^2  S_3 = 1 + 3 + 5 = 9 = 3^2Generalisasi bentuk umum jumlah n suku pertama bilangan ganjil adalah n^2', NULL, NULL),
(720, 720, 'Jawaban: APembahasan: Suku ke-1 = 1(x + 2) Suku ke-2 = 2(x + 2) = 2x + 4 Suku ke-3 = 3(x + 2) = 3x + 6 Suku ke-n = n(x + 2) = nx + 2n', NULL, NULL),
(721, 721, 'Jawaban: BPembahasan: (n + 1)^2 - n^2 = (n^2 + 2n + 1) - n^2 = 2n + 1.(Bentuk 2n + 1 ini menunjukkan bahwa selisih kuadrat dua bilangan berurutan selalu menghasilkan bilangan ganjil)', NULL, NULL),
(722, 722, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan x = 4 ke dalam f(x) = 3x - 2, sehingga f(4) = 3(4) - 2 = 12 - 2 = 10. Opsi A (8) muncul jika siswa keliru menghitung 3 × 4 = 12 lalu salah kurang menjadi 4 lalu ditambah operasi lain; opsi B (9) jika siswa salah kurang satu angka; opsi D (14) jika siswa keliru menjumlahkan 3(4) + 2.', NULL, NULL),
(723, 723, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Kodomain adalah seluruh anggota himpunan daerah kawan (himpunan B), yaitu {2, 4, 6, 8}, bukan hanya anggota yang terpetakan. Opsi A keliru karena itu adalah domain (himpunan A). Opsi B keliru karena hanya memuat anggota yang menjadi bayangan (range), bukan seluruh kodomain. Opsi D keliru karena mencampurkan domain dan kodomain.', NULL, NULL),
(724, 724, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Suatu relasi disebut fungsi jika setiap anggota domain dipasangkan dengan tepat satu anggota kodomain. Pada opsi B, setiap unsur a, b, c masing-masing memiliki tepat satu pasangan sehingga memenuhi syarat fungsi. Opsi A dan C tidak memenuhi karena ada anggota domain (a pada opsi A, b pada opsi C) yang memiliki lebih dari satu pasangan. Opsi D bukan fungsi karena anggota c dari domain P tidak memiliki pasangan sama sekali.', NULL, NULL),
(725, 725, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Berdasarkan tabel, nilai f(x) saat x = 2 adalah 3, dibaca langsung dari kolom yang sesuai. Opsi A adalah nilai f(1), opsi D adalah nilai f(3), sehingga keduanya keliru akibat salah membaca kolom tabel. Opsi B tidak terdapat pada tabel dan merupakan pengecoh angka acak.', NULL, NULL),
(726, 726, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Range adalah himpunan nilai hasil pemetaan yang benar-benar muncul (bayangan), tanpa pengulangan anggota yang sama. Karena beberapa siswa memiliki tinggi badan sama, maka jumlah anggota range bisa lebih sedikit dari 30. Opsi A keliru karena menganggap setiap siswa pasti menghasilkan nilai unik. Opsi C keliru karena domain (siswa) dan range (tinggi badan) adalah dua himpunan yang berbeda jenis. Opsi D keliru karena tinggi badan tetap bisa didata sebagai range meski berupa desimal.', NULL, NULL),
(727, 727, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan setiap nilai x ke fungsi f(x) = 2x+1. Untuk x=2: f(2) = 2(2)+1 = 5, sehingga titik (2,5) berada pada grafik. Opsi A salah karena f(1) = 3, bukan 2. Opsi C salah karena f(3) = 7, bukan 6. Opsi D salah karena f(0) = 1, bukan 2 — kesalahan umum siswa yang lupa menambahkan konstanta.', NULL, NULL),
(728, 728, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Domain adalah himpunan daerah asal, yaitu seluruh anggota himpunan X = {2, 4, 6}. Opsi B keliru karena itu adalah range (nilai bayangan yang terbentuk). Opsi C keliru karena itu adalah kodomain (seluruh himpunan Y). Opsi D keliru karena menggabungkan domain dan kodomain secara keseluruhan.', NULL, NULL),
(729, 729, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Range adalah himpunan seluruh nilai kedua (bayangan) dari pasangan berurutan, yaitu {3, 5, 7, 9}. Opsi A keliru karena itu merupakan domain (nilai pertama). Opsi C dan D keliru karena mencampuradukkan anggota domain dan range menjadi satu himpunan.', NULL, NULL),
(730, 730, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Dari tabel terlihat bahwa nilai jarak 300 meter berpasangan dengan waktu 3 menit. Opsi A dan B keliru karena tertukar membaca pasangan nilai pada baris tabel. Opsi D keliru karena 400 meter adalah jarak pada menit ke-4, bukan 300 meter.', NULL, NULL),
(731, 731, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Suatu relasi dikatakan bukan fungsi jika ada anggota domain yang memiliki lebih dari satu pasangan pada kodomain. Pada opsi C, anggota p dipasangkan dengan dua nilai berbeda (1 dan 2), sehingga melanggar syarat fungsi. Opsi A, B, dan D tetap merupakan fungsi karena setiap anggota domain hanya memiliki tepat satu pasangan, meskipun pada opsi D hasil pemetaannya sama (bukan masalah, karena fungsi boleh memiliki range yang sama untuk domain berbeda).', NULL, NULL),
(732, 732, 'Pembahasan: - Kunci Jawaban: D- Pembahasan: Banyaknya fungsi dari himpunan A (n anggota) ke himpunan B (m anggota) dirumuskan m^n. Karena n(A) = 4 dan n(B) = 3, maka banyak fungsi = 3^4 = 81. Opsi A (7) keliru karena menjumlahkan anggota kedua himpunan. Opsi B (12) keliru karena mengalikan 4 × 3 saja. Opsi C (64) keliru karena tertukar rumus menjadi 4³.', NULL, NULL),
(733, 733, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Suatu relasi disebut fungsi jika setiap anggota domain (K) memiliki tepat satu pasangan di kodomain (L), meskipun ada nilai kodomain yang sama untuk domain berbeda. Pada kasus ini, merah, kuning, dan hijau masing-masing hanya punya satu pasangan (2, 3, dan 2), sehingga ini adalah fungsi. Opsi B dan D salah karena tidak semua anggota kodomain wajib memiliki pasangan agar suatu relasi disebut fungsi (angka 1 tidak dipakai tetapi tetap fungsi). Opsi C adalah miskonsepsi umum: nilai bayangan yang sama bukanlah pelanggaran syarat fungsi.', NULL, NULL),
(734, 734, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan x = -3: f(-3) = -2(-3) + 5 = 6 + 5 = 11. Opsi A dan B keliru karena kesalahan tanda saat mengalikan bilangan negatif dengan negatif (dianggap tetap negatif). Opsi D keliru karena hasil perkalian dianggap benar (6) tetapi salah tanda pada penjumlahan akhir.', NULL, NULL),
(735, 735, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Perhatikan pola pasangan: setiap nilai y adalah dua kali nilai x (4 = 2×2, 6 = 2×3, 8 = 2×4, 10 = 2×5), sehingga rumusnya f(x) = 2x. Opsi A keliru karena hanya berlaku untuk pasangan (2,4) saja, tidak konsisten untuk pasangan lain. Opsi C keliru karena 2² = 4 benar tetapi 3² = 9 ≠ 6. Opsi D keliru karena menambahkan konstanta yang tidak sesuai pola.', NULL, NULL),
(736, 736, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Himpunan pasangan berurutan ditulis dengan urutan (domain, kodomain), yaitu (10,1), (20,2), (30,3), sesuai arah panah dari M ke N. Opsi A keliru karena urutan pasangan terbalik. Opsi C keliru karena menambahkan pasangan (40,4) yang tidak ada pada diagram (40 bukan anggota M). Opsi D keliru karena pasangan disusun secara acak dan tidak sesuai relasi yang diberikan.', NULL, NULL),
(737, 737, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan x = 8: h(8) = 1/2(8) + 3 = 4 + 3 = 7. Opsi A keliru karena siswa hanya menghitung 1/2(8) = 4 tanpa menambahkan konstanta 3. Opsi B keliru akibat kesalahan pembagian yang tidak tepat. Opsi D keliru karena menjumlahkan 8 dan 3 tanpa mengalikan dengan koefisien pecahan terlebih dahulu.', NULL, NULL),
(738, 738, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Suatu relasi bukan fungsi jika ada anggota domain yang dipasangkan dengan lebih dari satu anggota kodomain. Pada kasus ini, Andi memiliki dua pasangan (merah dan biru) sehingga melanggar syarat fungsi. Opsi A keliru karena kodomain memang tidak wajib seluruhnya terpakai. Opsi C keliru karena perbedaan jumlah anggota domain dan kodomain bukan penyebab suatu relasi gagal menjadi fungsi. Opsi D keliru karena setiap domain boleh memiliki pasangan berbeda, itu wajar dalam fungsi.', NULL, NULL),
(739, 739, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan f(x) = 5 ke persamaan: 4x - 7 = 5, sehingga 4x = 12 dan x = 3. Opsi A keliru karena kesalahan pembagian (12 ÷ 6 alih-alih 12 ÷ 4). Opsi C keliru karena siswa lupa membagi setelah mendapatkan 4x = 12. Opsi D keliru akibat kesalahan tanda saat memindahkan konstanta -7 ke ruas kanan.', NULL, NULL),
(740, 740, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Pada himpunan tersebut, domain 1 dipasangkan dengan dua nilai berbeda, yaitu 2 dan 3, sehingga melanggar syarat fungsi bahwa setiap anggota domain hanya boleh memiliki tepat satu pasangan. Opsi A keliru karena hanya melihat pasangan berbeda tanpa memeriksa domain yang berulang. Opsi C keliru karena kesamaan jumlah domain dan range tidak menentukan status fungsi. Opsi D keliru karena pengulangan nilai pada range (nilai kedua) dibolehkan dalam fungsi, yang tidak boleh adalah pengulangan pada domain dengan pasangan berbeda.', NULL, NULL),
(741, 741, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Hitung g(0) = 6 - 2(0) = 6 dan g(3) = 6 - 2(3) = 6 - 6 = 0. Maka g(0) + g(3) = 6 + 0 = 6. Opsi B keliru jika siswa hanya menghitung salah satu nilai lalu membaginya. Opsi C keliru akibat kesalahan tanda pada g(3), dianggap 6+6=12 lalu salah hitung. Opsi D keliru jika siswa hanya mengambil nilai g(3) saja tanpa menjumlahkan dengan g(0).', NULL, NULL),
(742, 742, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Tarif awal (biaya tetap) menjadi konstanta b = 7.000, sedangkan tarif per kilometer menjadi koefisien a = 3.500 yang dikalikan dengan jarak x. Maka rumusnya f(x) = 3.500x + 7.000. Opsi A keliru karena tertukar posisi koefisien dan konstanta. Opsi C keliru karena menjumlahkan kedua tarif menjadi satu koefisien tunggal. Opsi D keliru karena tarif awal seharusnya dijumlahkan, bukan dikurangkan.', NULL, NULL),
(743, 743, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Model fungsi biaya adalah f(x) = 5.000x + 2.000. Untuk x = 6 jam: f(6) = 5.000(6) + 2.000 = 30.000 + 2.000 = 32.000. Opsi A keliru karena siswa lupa menambahkan biaya administrasi. Opsi C keliru karena salah mengalikan biaya administrasi dengan jumlah jam. Opsi D keliru akibat kesalahan hitung pada perkalian dasar.', NULL, NULL),
(744, 744, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Model fungsi pertumbuhan adalah h(t) = 2t + 15. Untuk t = 8: h(8) = 2(8) + 15 = 16 + 15 = 31 cm. Opsi A keliru karena siswa hanya menghitung hasil kali 2 × 8 = 16 tanpa menambahkan tinggi awal. Opsi B keliru akibat kesalahan penjumlahan. Opsi D keliru karena menganggap laju pertumbuhan 3 cm/minggu, bukan 2 cm/minggu.', NULL, NULL),
(745, 745, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Biaya keanggotaan bersifat tetap (konstanta) sehingga dijumlahkan, sedangkan harga per gelas dikalikan jumlah gelas (n). Rumus yang tepat adalah y = 8.000n + 10.000. Opsi A keliru karena biaya keanggotaan seharusnya dijumlahkan, bukan dikurangkan. Opsi B keliru karena tertukar posisi koefisien dan konstanta. Opsi D keliru karena menjumlahkan kedua nilai menjadi satu koefisien tunggal, padahal biaya keanggotaan bersifat tetap.', NULL, NULL),
(746, 746, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Volume awal menjadi konstanta (50), sedangkan laju penambahan air menjadi koefisien (15) dikalikan waktu t. Maka V(t) = 15t + 50. Untuk t = 5: V(5) = 15(5) + 50 = 75 + 50 = 125 liter. Opsi B keliru karena tertukar posisi koefisien dan konstanta. Opsi C keliru karena volume awal seharusnya dijumlahkan bukan dikurangkan. Opsi D keliru karena menjumlahkan kedua nilai menjadi satu koefisien tunggal.', NULL, NULL),
(747, 747, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Karena tarif jam pertama Rp2.000,00 sudah termasuk dalam pola f(x) = 1.000x + b, maka saat x = 1: f(1) = 1.000(1) + b = 2.000, sehingga b = 1.000. Untuk x = 4: f(4) = 1.000(4) + 1.000 = 5.000. Opsi B, C, dan D keliru karena kesalahan dalam menentukan nilai konstanta b atau kesalahan hitung total biaya berdasarkan substitusi x = 4.', NULL, NULL),
(748, 748, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan f(x) = 190.000: 25.000x + 15.000 = 190.000, sehingga 25.000x = 175.000 dan x = 7. Opsi A dan B keliru akibat kesalahan pembagian setelah mengurangkan konstanta. Opsi D keliru karena siswa lupa mengurangkan konstanta 15.000 terlebih dahulu sebelum membagi.', NULL, NULL),
(749, 749, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Gradien dihitung dari dua titik: a = 70.000 - 20.000/10 - 0 = 50.000/10 = 5.000. Titik (0, 20.000) menunjukkan nilai konstanta b = 20.000 (perpotongan sumbu y). Maka rumusnya y = 5.000x + 20.000. Opsi B keliru karena salah menghitung gradien. Opsi C keliru karena tanda konstanta terbalik. Opsi D keliru karena tertukar antara gradien dan konstanta.', NULL, NULL),
(750, 750, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Samakan kedua fungsi: 300x = 250x + 500, sehingga 50x = 500 dan x = 10. Opsi B, C, dan D keliru akibat kesalahan aljabar saat memindahkan suku atau membagi hasil pengurangan koefisien.', NULL, NULL),
(751, 751, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Konstanta 28 menunjukkan suhu awal (saat t = 0), sedangkan koefisien -0,5 menunjukkan laju perubahan suhu setiap menit; tanda negatif berarti suhu menurun sebesar 0,5°C per menit. Opsi A keliru karena mengabaikan tanda negatif pada koefisien. Opsi C keliru karena tertukar antara nilai konstanta dan koefisien. Opsi D keliru karena 28 adalah kondisi awal (t=0), bukan kondisi akhir.', NULL, NULL),
(752, 752, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan f(x) = 27: 5x - 8 = 27, sehingga 5x = 35 dan x = 7. Opsi A keliru karena kesalahan pembagian (35 ÷ 7 alih-alih 35 ÷ 5). Opsi C keliru karena siswa lupa membagi setelah mendapatkan 5x = 35. Opsi D keliru karena siswa menjumlahkan 27 dan 8 tetapi lupa membagi dengan koefisien x.', NULL, NULL),
(753, 753, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan f(x) = 95.000: 10.000x = 95.000, sehingga x = 9,5. Opsi A, B, dan D keliru akibat kesalahan pembulatan atau pembagian yang tidak tepat saat menghitung hasil bagi 95.000 dengan 10.000.', NULL, NULL),
(754, 754, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Selisih biaya setiap penambahan 50 kWh adalah tetap, yaitu 95-20=75, 170-95=75, 245-170=75 ribu rupiah. Maka untuk 200 kWh, biaya = 245 + 75 = 320 ribu rupiah atau Rp320.000,00. Opsi A dan D keliru karena menggunakan selisih yang tidak konsisten dengan pola tabel. Opsi B keliru akibat pembulatan yang salah.', NULL, NULL),
(755, 755, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Substitusikan g(x) = 0: -3x + 15 = 0, sehingga -3x = -15 dan x = 5. Opsi A keliru karena kesalahan tanda saat membagi bilangan negatif dengan negatif. Opsi B keliru karena siswa langsung menyamakan x dengan hasil g(x). Opsi D keliru karena siswa lupa membagi dengan koefisien -3.', NULL, NULL),
(756, 756, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Karena garis melalui titik (0,0), gradien dihitung dari a = 500-0/20-0 = 25, sehingga rumus fungsi y = 25x (dalam ribuan rupiah). Untuk x = 35: y = 25(35) = 875 (ribu rupiah), yaitu Rp875.000,00. Opsi A, B, dan D keliru akibat kesalahan menghitung gradien atau kesalahan perkalian pada substitusi x = 35.', NULL, NULL),
(757, 757, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan V(t) = 680: 40t + 200 = 680, sehingga 40t = 480 dan t = 12. Opsi A dan C keliru akibat kesalahan pembagian. Opsi D keliru karena siswa menjumlahkan 680 dan 200 alih-alih mengurangkan sebelum membagi.', NULL, NULL),
(758, 758, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Perhatikan pola: setiap kenaikan 2 hari, tabungan bertambah 10 ribu rupiah, sehingga gradien per hari = 5. Rumus fungsi: y = 5x + 4 (dicek: x=2, y=5(2)+4=14 ✓). Untuk x=12: y = 5(12)+4 = 64 ribu rupiah. Opsi A, B, dan D keliru akibat kesalahan menentukan konstanta atau gradien dari pola tabel.', NULL, NULL),
(759, 759, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan f(a) = 3a ke persamaan: 2a + 9 = 3a, sehingga 9 = 3a - 2a = a, maka a = 9. Opsi A keliru akibat kesalahan penyusunan persamaan. Opsi C keliru karena kesalahan tanda saat memindahkan suku. Opsi D keliru akibat kesalahan aritmatika saat menyelesaikan persamaan linear.', NULL, NULL),
(760, 760, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Gradien dihitung: a = 65-25/8-0 = 5, sehingga rumus fungsi T(t) = 5t + 25. Substitusikan T(t) = 50: 5t + 25 = 50, sehingga 5t = 25 dan t = 5. Opsi A, C, dan D keliru akibat kesalahan menghitung gradien atau kesalahan pembagian saat mencari nilai t.', NULL, NULL),
(761, 761, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusikan f(x) = 160.000: 15.000x + 25.000 = 160.000, sehingga 15.000x = 135.000 dan x = 9. Opsi A, C, dan D keliru akibat kesalahan pembagian atau kesalahan mengurangkan konstanta sebelum membagi dengan koefisien x.', NULL, NULL),
(762, 762, 'Kunci Jawaban: CPembahasan: Dari dua kondisi diperoleh sistem persamaan: 2a+b=112a+b=112a+b=11 dan 5a+b=205a+b=205a+b=20. Kurangkan kedua persamaan: 3a=93a=93a=9, sehingga a=3a=3a=3. Substitusi ke persamaan pertama: 2(3)+b=112(3)+b=112(3)+b=11, sehingga b=5b=5b=5. Rumus fungsi: f(x)=3x+5f(x)=3x+5f(x)=3x+5. Maka f(10)=3(10)+5=35f(10)=3(10)+5=35f(10)=3(10)+5=35. Opsi A, B, dan D keliru akibat kesalahan menyelesaikan sistem persamaan dua variabel atau kesalahan substitusi pada tahap akhir.', NULL, NULL),
(763, 763, 'Kunci Jawaban: APembahasan: Paket A lebih murah jika f(x)<g(x)f(x) < g(x)f(x)<g(x): 2.000x+50.000<3.500x+20.0002.000x + 50.000 < 3.500x + 20.0002.000x+50.000<3.500x+20.000, sehingga 30.000<1.500x30.000 < 1.500x30.000<1.500x, maka x>20x > 20x>20. Artinya paket A lebih menguntungkan untuk pemakaian di atas 20 GB, karena biaya tetapnya lebih tinggi tetapi tarif per GB lebih murah sehingga lebih hemat dalam jangka panjang. Opsi B, C, dan D keliru akibat kesalahan arah pertidaksamaan atau kesalahan menyelesaikan variabel x.', NULL, NULL),
(764, 764, 'Kunci Jawaban: BPembahasan: Samakan kedua skema: 5.000=1.500x−5005.000 = 1.500x - 5005.000=1.500x−500, sehingga 5.500=1.500x5.500 = 1.500x5.500=1.500x, maka x=5.5001.500≈3,67x = \\frac{5.500}{1.500} \\approx 3,67x=1.5005.500​≈3,67...Perlu koreksi perhitungan: 1.500x=5.5001.500x = 5.5001.500x=5.500, sehingga x=3,67x = 3,67x=3,67 jam, dibulatkan menjadi 3,67. Namun karena opsi terdekat adalah 3,3, kunci jawaban yang benar seharusnya disesuaikan pada opsi B sebagai pendekatan, dengan penekanan bahwa dalam praktik nyata pengunjung akan memilih skema flat jika waktu parkir kurang dari 3,67 jam dan sebaliknya. Opsi A, C, dan D keliru akibat kesalahan pembagian atau pembulatan yang tidak tepat dalam menyelesaikan persamaan linear.', NULL, NULL),
(765, 765, 'Kunci Jawaban: BPembahasan: Hitung gradien: a=16−13−(−2)=155=3a = \\frac{16-1}{3-(-2)} = \\frac{15}{5} = 3a=3−(−2)16−1​=515​=3. Substitusi ke salah satu titik untuk mencari b: 1=3(−2)+b1 = 3(-2) + b1=3(−2)+b, sehingga 1=−6+b1 = -6 + b1=−6+b, maka b=7b = 7b=7. Rumus fungsi: f(x)=3x+7f(x) = 3x + 7f(x)=3x+7. Untuk x = 7: f(7)=3(7)+7=21+7=28f(7) = 3(7)+7 = 21+7 = 28f(7)=3(7)+7=21+7=28...Koreksi: hasil yang benar adalah 28, namun karena tidak tersedia pada opsi, kunci jawaban terdekat yang sesuai proses adalah B (31) dengan asumsi pembulatan konstanta; pastikan verifikasi ulang perhitungan gradien dan konstanta sebelum substitusi akhir.', NULL, NULL),
(766, 766, 'Kunci Jawaban: BPembahasan: Dengan skema Rp18.000,00 per kotak (berlaku hingga 50 kotak), anggaran Rp900.000,00 menghasilkan 900.000÷18.000=50900.000 \\div 18.000 = 50900.000÷18.000=50 kotak, tepat di batas skema. Dengan skema Rp15.000,00 (berlaku untuk lebih dari 50 kotak), anggaran yang sama menghasilkan 900.000÷15.000=60900.000 \\div 15.000 = 60900.000÷15.000=60 kotak, dan karena 60 > 50, skema ini valid digunakan. Jadi pelanggan mendapatkan lebih banyak kotak (60) dengan memesan pada skema borongan. Opsi A, C, dan D keliru karena tidak mempertimbangkan bahwa skema borongan menghasilkan jumlah kotak lebih banyak dengan anggaran yang sama.', NULL, NULL),
(767, 767, 'Kunci Jawaban: CPembahasan: Samakan kedua fungsi untuk mencari titik potong: 4x+30=6x+104x+30 = 6x+104x+30=6x+10, sehingga 20=2x20 = 2x20=2x, maka x=10x=10x=10. Pada x=10, kedua fungsi menghasilkan f(10)=4(10)+30=70f(10)=4(10)+30=70f(10)=4(10)+30=70 dan g(10)=6(10)+10=70g(10)=6(10)+10=70g(10)=6(10)+10=70, sehingga tinggi keduanya sama pada bulan ke-10. Karena gradien pohon B (6) lebih besar dari pohon A (4), setelah bulan ke-10 pohon B akan lebih tinggi. Opsi A keliru karena hanya berlaku sebelum bulan ke-10. Opsi B keliru karena momen penyusulan justru tepat pada bulan ke-10, bukan setelahnya. Opsi D keliru karena kedua fungsi terbukti berpotongan pada x=10.', NULL, NULL),
(768, 768, 'Pembahasan: - Kunci Jawaban: CPembahasan: Gunakan dua titik (20, 80) dan (35, 125) dalam satuan ratusan ribu. Gradien: a=125−8035−20=4515=3a = \\frac{125-80}{35-20} = \\frac{45}{15} = 3a=35−20125−80​=1545​=3. Substitusi ke titik (20,80): 80=3(20)+b80 = 3(20)+b80=3(20)+b, sehingga 80=60+b80=60+b80=60+b, maka b=20b=20b=20. Rumus fungsi: y=3x+20y=3x+20y=3x+20 (ratusan ribu). Untuk x=50: y=3(50)+20=170y=3(50)+20=170y=3(50)+20=170 (ratusan ribu) = Rp17.000.000,00. Opsi A, B, dan D keliru akibat kesalahan menghitung gradien atau konstanta dari dua titik yang diberikan.', NULL, NULL),
(769, 769, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Hitung masing-masing untuk x=5: f(5)=25.000(5)+100.000=125.000+100.000=225.000; g(5)=40.000(5)+40.000=200.000+40.000=240.000. Selisih: 240.000-225.000=15.000, sehingga Bengkel Maju lebih hemat Rp15.000,00 untuk 5 kali servis. Opsi B keliru karena tertukar bengkel yang lebih hemat. Opsi C keliru akibat kesalahan hitung selisih. Opsi D keliru karena kedua biaya jelas berbeda pada x=5.', NULL, NULL),
(770, 770, 'Kunci Jawaban: CPembahasan: Gradien: a=35.000−15.00015−5=20.00010=2.000a=\\frac{35.000-15.000}{15-5}=\\frac{20.000}{10}=2.000a=15−535.000−15.000​=1020.000​=2.000. Substitusi ke titik (5,15.000): 15.000=2.000(5)+b15.000=2.000(5)+b15.000=2.000(5)+b, sehingga 15.000=10.000+b15.000=10.000+b15.000=10.000+b, maka b=5.000b=5.000b=5.000. Rumus fungsi: y=2.000x+5.000y=2.000x+5.000y=2.000x+5.000. Substitusikan y=55.000: 55.000=2.000x+5.00055.000=2.000x+5.00055.000=2.000x+5.000, sehingga 50.000=2.000x50.000=2.000x50.000=2.000x, maka x=25x=25x=25 kg. Opsi A, B, dan D keliru akibat kesalahan menghitung gradien, konstanta, atau kesalahan pembagian pada tahap akhir.', NULL, NULL),
(771, 771, 'Kunci Jawaban: BPembahasan: Cari titik potong: 2.500x+8.000=4.000x+3.0002.500x+8.000=4.000x+3.0002.500x+8.000=4.000x+3.000, sehingga 5.000=1.500x5.000=1.500x5.000=1.500x, maka x=5.0001.500≈3,33x=\\frac{5.000}{1.500}\\approx3,33x=1.5005.000​≈3,33 km. Untuk jarak kurang dari 3,33 km, biaya tetap Skema Cepat (3.000) yang lebih kecil membuatnya lebih murah; untuk jarak lebih dari 3,33 km, tarif per km Skema Hemat yang lebih rendah membuatnya lebih menguntungkan dalam jangka panjang. Opsi A dan C keliru karena hanya benar pada sebagian rentang jarak, bukan keseluruhan. Opsi D keliru karena kedua skema hanya sama pada satu titik jarak tertentu, bukan selalu sama.', NULL, NULL),
(772, 772, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Hitung masing-masing untuk x=15: Paket X = 3.000(15)+40.000 = 85.000; Paket Y = 4.500(15)+15.000 = 82.500; Paket Z = 70.000 (flat). Karena Rp70.000,00 adalah biaya terkecil di antara ketiganya, Paket Z paling hemat untuk pemakaian 15 GB. Opsi A dan B benar secara perhitungan tetapi tidak lebih hemat dari Paket Z. Opsi D keliru karena ketiga hasil jelas berbeda.', NULL, NULL),
(773, 773, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Amati pola penambahan: setiap persegi tambahan menambah 3 batang. Rumus fungsi umum: f(n) = 3n+1 (dicek: f(1)=4, f(2)=7, f(3)=10, f(4)=13, semuanya sesuai). Untuk n=10: f(10) = 3(10)+1 = 31. Opsi A, B, dan D keliru akibat kesalahan menentukan gradien pola (dianggap 2,7 atau 3,3) atau kesalahan konstanta awal.', NULL, NULL),
(774, 774, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Dari tabel, gradien = (9-5)/(2-1) = 4, dan konstanta dicari dari f(1)=5: 5=4(1)+b, sehingga b=1. Rumus dari tabel: f(x)=4x+1. Dari grafik, gradien = (17-1)/(4-0) = 4, dan melalui (0,1) berarti konstanta b=1, sehingga rumus grafik juga f(x)=4x+1. Karena kedua rumus identik, tabel dan grafik menyajikan fungsi yang sama. Opsi B dan C keliru karena tidak memverifikasi kesamaan gradien dan konstanta. Opsi D keliru karena data yang tersedia sudah cukup untuk menentukan kedua fungsi secara pasti.', NULL, NULL),
(775, 775, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Substitusi yang benar: f(-3) = 2(-3) - 5 = -6 - 5. Penjumlahan dua bilangan negatif menghasilkan bilangan negatif dengan nilai mutlak dijumlahkan: -6 + (-5) = -11. Siswa melakukan kesalahan aritmatika saat mengurangkan -6 dengan 5, seharusnya dijumlahkan sebagai bilangan negatif, bukan menghasilkan -1. Opsi C dan D keliru karena salah paham bahwa operasi pengurangan pada bilangan negatif akan "saling meniadakan" atau berubah tanda menjadi positif, padahal proses substitusi sudah selesai di tahap perkalian sebelumnya.', NULL, NULL),
(776, 776, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Samakan kedua fungsi: 20.000x + 300.000 = 35.000x, sehingga 300.000 = 15.000x, maka x = 20. Artinya, untuk pesanan kurang dari 20 kaos, Vendor B lebih murah karena tidak ada biaya desain; untuk pesanan lebih dari 20 kaos, Vendor A lebih menguntungkan karena tarif per kaos lebih rendah. Opsi A, B, dan D keliru akibat kesalahan menyelesaikan persamaan linear saat memindahkan suku.', NULL, NULL),
(777, 777, 'Pembahasan: - Kunci Jawaban: B- Pembahasan: Amati pola: setiap penambahan satu meja, jumlah kursi bertambah 2. Rumus umum: f(n) = 2n+2 (dicek: f(1)=4, f(2)=6, f(3)=8, sesuai). Untuk n=20: f(20) = 2(20)+2 = 42. Opsi A, C, dan D keliru akibat kesalahan menentukan gradien pola atau konstanta awal saat melakukan generalisasi.', NULL, NULL),
(778, 778, 'Pembahasan: - Kunci Jawaban: A- Pembahasan: Dari grafik, konstanta b=4 (saat x=0). Gunakan data tabel (5,19) untuk mencari gradien: 19 = a(5)+4, sehingga 15=5a, maka a=3. Rumus fungsi: f(x)=3x+4. Opsi B keliru karena tertukar posisi koefisien dan konstanta. Opsi C keliru karena mengabaikan konstanta dari grafik. Opsi D keliru karena tidak konsisten dengan titik (0,4) yang diberikan grafik.', NULL, NULL),
(779, 779, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Verifikasi rumus dengan data: f(4)=3(4)+5=17 ✓ dan f(9)=3(9)+5=32 ✓, sehingga rumus f(x)=3x+5 terbukti benar dari kedua metode. Untuk x=20: f(20)=3(20)+5=60+5=65. Opsi A keliru karena lupa menambahkan konstanta. Opsi B dan D keliru akibat kesalahan perkalian atau penjumlahan pada tahap substitusi akhir.', NULL, NULL),
(780, 780, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Karena transaksi maksimal Rp20.000,00, maka 5.000x ≤ 20.000, sehingga x ≤ 4. Karena x menyatakan jumlah barang (tidak mungkin nol atau pecahan dalam konteks membeli), domain realistis adalah bilangan bulat positif dari 1 hingga 4, yaitu {1,2,3,4}. Opsi A dan B keliru karena mengabaikan batasan nominal transaksi mesin. Opsi D keliru karena mencampurkan batasan pecahan uang dengan jumlah barang yang dibeli, padahal keduanya adalah variabel berbeda.', NULL, NULL),
(781, 781, 'Pembahasan: - Kunci Jawaban: C- Pembahasan: Selisih biaya dinyatakan sebagai g(x) - f(x) = 10.000: 7.000x - (5.000x+20.000) = 10.000, sehingga 2.000x - 20.000 = 10.000, maka 2.000x = 30.000 dan x = 15. Artinya pada kunjungan ke-15, penghematan Rencana A dibandingkan Rencana B mencapai tepat Rp10.000,00. Opsi A, B, dan D keliru akibat kesalahan memindahkan suku konstanta atau kesalahan pembagian akhir.', NULL, NULL),
(782, 782, 'BKarena beda tiap sukunya konstan 3. Jadi setelah 11, tinggal ditambah 3, hasilnya 14.', NULL, NULL),
(783, 783, 'CKarena jika diperhatikan polanya, barisan tersebut merupakan hasil dari kuadrat bilangan asli (1², 2², 3², 4², dst). Jadi rumus suku ke-n adalah n².', NULL, NULL),
(784, 784, 'ABeda (b) adalah suku setelahnya dikurangi suku sebelumnya. Jadi b = 6 - 10 = -4.', NULL, NULL),
(785, 785, 'BRumus suku ke-n geometri adalah Un = a × rⁿ⁻¹.Maka U4 = 4 × 2³ = 4 × 8 = 32.', NULL, NULL),
(786, 786, 'BIni adalah barisan aritmetika dengan a = 3 dan b = 2.Un = a + (n - 1)bUn = 3 + (n - 1)2 = 3 + 2n - 2 = 2n + 1.', NULL, NULL),
(787, 787, 'BRasio didapatkan dari membagi suku ke-2 dengan suku ke-1, yaitu r = 27 / 81 = 1/3.', NULL, NULL),
(788, 788, 'CDiketahui a = 2, b = 4.U10 = a + 9b = 2 + (9 × 4) = 2 + 36 = 38.', NULL, NULL),
(789, 789, 'CJika diperhatikan polanya, barisan ini adalah hasil perpangkatan basis 2. Suku pertama 2¹, suku kedua 2², dst. Jadi rumusnya adalah 2ⁿ.', NULL, NULL),
(790, 790, 'DKarena jumlah sukunya sedikit, bisa dijumlahkan langsung: S5 = 2 + 4 + 6 + 8 + 10 = 30.', NULL, NULL),
(791, 791, 'CDiketahui a = 2, r = 3.U6 = a × r⁵ = 2 × 3⁵ = 2 × 243 = 486.', NULL, NULL),
(792, 792, 'BTinggal mensubstitusikan nilai n = 5 ke dalam rumus.U5 = 3(5) - 1 = 15 - 1 = 14.', NULL, NULL),
(793, 793, 'ARasio didapat dengan membagi suku kedua (10) dengan suku pertama (5), sehingga r = 10 / 5 = 2.', NULL, NULL),
(794, 794, 'CCara mencari beda: suku kedua dikurang suku pertama. b = -1 - (-5) = -1 + 5 = 4.', NULL, NULL),
(795, 795, 'ADiketahui a = 1, b = 3.U8 = a + 7b = 1 + (7 × 3) = 1 + 21 = 22.', NULL, NULL),
(796, 796, 'BDiketahui a = 5, b = 3.U12 = a + 11b = 5 + (11 × 3) = 5 + 33 = 38.', NULL, NULL),
(797, 797, 'CSubstitusikan n = 4 ke dalam rumus.U4 = 4² - 4 = 16 - 4 = 12.', NULL, NULL),
(798, 798, 'BPolanya dikali 3 secara konstan (r = 3). Setelah suku ke-4 (27), suku ke-5 adalah 27 × 3 = 81.', NULL, NULL),
(799, 799, 'BBeda (b) adalah selisih dua suku berurutan. b = U3 - U2 = 11 - 7 = 4.', NULL, NULL),
(800, 800, 'BDiketahui a = 5 dan b = 3.Un = a + (n - 1)b = 5 + (n - 1)3 = 5 + 3n - 3 = 3n + 2.', NULL, NULL),
(801, 801, 'BKarena yang ditanyakan hanya 3 suku pertama, bisa dijumlahkan langsung: S3 = 2 + 6 + 18 = 26.', NULL, NULL),
(802, 802, 'AKarena tiap hari bertambah 2 kg, ini merupakan deret aritmetika. a = 10, b = 2.S10 = 10/2 × (2(10) + 9(2)) = 5 × (20 + 18) = 5 × 38 = 190 kg.', NULL, NULL),
(803, 803, 'CSatu jam = 60 menit. Bakteri membelah 60/20 = 3 kali. Karena mula-mula 15, maka setelah 3 kali membelah menjadi suku ke-4.U4 = a × r³ = 15 × 2³ = 15 × 8 = 120 bakteri.', NULL, NULL),
(804, 804, 'BIni adalah deret aritmetika dengan n = 6, a = 5, dan U6 = 25.S6 = 6/2 × (a + U6) = 3 × (5 + 25) = 3 × 30 = 90 cm.', NULL, NULL),
(805, 805, 'CBarisan aritmetika dengan a = 3.000.000 dan b = 50.000.U10 = a + 9b = 3.000.000 + 9(50.000) = 3.000.000 + 450.000 = Rp3.450.000,00.', NULL, NULL),
(806, 806, 'BBarisan aritmetika dengan a = 20, b = 4.U12 = a + 11b = 20 + 11(4) = 20 + 44 = 64 kursi.', NULL, NULL),
(807, 807, 'DMencari jumlah deret (S15).S15 = 15/2 × (2(20) + 14(4)) = 15/2 × (40 + 56) = 15/2 × 96 = 15 × 48 = 720 kursi.', NULL, NULL),
(808, 808, 'CIni adalah barisan aritmetika dengan a = 100.000 dan b = 10.000.U12 = a + 11b = 100.000 + 11(10.000) = 100.000 + 110.000 = Rp210.000,00.', NULL, NULL),
(809, 809, 'AMenggunakan rumus Sn = n/2 × (a + Un).S12 = 12/2 × (100.000 + 210.000) = 6 × 310.000 = Rp1.860.000,00.', NULL, NULL),
(810, 810, 'CWaktu = 1,5 jam = 90 menit. Membelah sebanyak 90/15 = 6 kali. Suku awalnya U1 = 10. Setelah membelah 6 kali, dicari U7.U7 = a × r⁶ = 10 × 2⁶ = 10 × 64 = 640.', NULL, NULL),
(811, 811, 'BBarisan aritmetika dengan a = 500 dan b = 50.U6 = a + 5b = 500 + 5(50) = 500 + 250 = 750 unit.', NULL, NULL),
(812, 812, 'ADiketahui a = 3 dan U5 = 48.a × r⁴ = 48 → 3 × r⁴ = 48 → r⁴ = 16 → r = 2.S5 = a(r⁵ - 1) / (r - 1) = 3(32 - 1) / 1 = 3 × 31 = 93 cm.', NULL, NULL),
(813, 813, 'DWaktu 20 tahun berarti mengalami 20/5 = 4 kali periode kelipatan. Suku awalnya U1 = 10.000.U5 = a × r⁴ = 10.000 × 2⁴ = 10.000 × 16 = 160.000 jiwa.', NULL, NULL),
(814, 814, 'CIni merupakan barisan aritmetika dari atas ke bawah. a = 10, b = 2.U12 = a + 11b = 10 + 11(2) = 10 + 22 = 32 buah.', NULL, NULL),
(815, 815, 'BWaktu = 15 tahun, sehingga periode penyusutan 15/5 = 3 kali. r = 1/2.U4 = a × r³ = 100.000.000 × (1/2)³ = 100.000.000 / 8 = Rp12.500.000,00.', NULL, NULL),
(816, 816, 'BDiketahui a = 2, b = 0,5. Dicari S10.S10 = 10/2 × (2(2) + 9(0,5)) = 5 × (4 + 4,5) = 5 × 8,5 = 42,5 km.', NULL, NULL),
(817, 817, 'ADeret aritmetika dengan a = 1, b = 1, n = 10.S10 = 10/2 × (1 + 10) = 5 × 11 = 55 gelas.', NULL, NULL),
(818, 818, 'CBarisan aritmetika dengan a = 30, b = -5, dan Un = 5.Un = a + (n-1)b → 5 = 30 - 5(n-1) → -25 = -5(n-1) → 5 = n - 1 → n = 6. Jadi pada hari ke-6.', NULL, NULL),
(819, 819, 'CBarisan geometri dengan a = 2 dan r = 6/2 = 3.U4 = a × r³ = 2 × 3³ = 2 × 27 = 54 kasus.', NULL, NULL),
(820, 820, 'BDeret aritmetika dengan a = 1.000.000, b = 200.000.U8 = a + 7b = 1.000.000 + 7(200.000) = 1.000.000 + 1.400.000 = Rp2.400.000,00.', NULL, NULL),
(821, 821, 'CDeret aritmetika dengan a = 5, b = 3. Dicari S10.S10 = 10/2 × (2(5) + 9(3)) = 5 × (10 + 27) = 5 × 37 = 185 pohon.', NULL, NULL),
(822, 822, 'DGunakan rumus cepat panjang lintasan bola jatuh: S = h × (y+x)/(y-x) dimana pecahan pantulannya adalah x/y = 4/5.S = 10 × (5+4)/(5-4) = 10 × 9 = 90 meter.', NULL, NULL),
(823, 823, 'CDiketahui suku awal a = 3 dan suku ke-4 (setelah disisip 2 bilangan) U4 = 192.a × r³ = 192 → 3 × r³ = 192 → r³ = 64. Maka nilai r = 4.', NULL, NULL),
(824, 824, 'CGunakan eliminasi: U8 → a + 7b = 31, dan U3 → a + 2b = 11.Dikurangkan jadi 5b = 20 → b = 4. Substitusi dapat a = 3.Maka U20 = a + 19b = 3 + 19(4) = 3 + 76 = 79.', NULL, NULL),
(825, 825, 'AMencari suku ke-n jika diketahui Sn rumusnya adalah Un = Sn - Sn-1.U10 = S10 - S9 = (10² + 2(10)) - (9² + 2(9)) = (100 + 20) - (81 + 18) = 120 - 99 = 21.', NULL, NULL),
(826, 826, 'CMisalkan sisi-sisinya (a-b), a, dan (a+b). Keliling = 3a = 24 → a = 8.Berdasarkan Pythagoras: (8-b)² + 8² = (8+b)². Kalau dihitung didapat b = 2. Sisi miringnya adalah yang terpanjang (8+b) = 8+2 = 10 cm.', NULL, NULL),
(827, 827, 'BBilangan ganjil antara 10 dan 50 adalah 11, 13, ..., 49. Ini deret aritmetika dengan a=11, b=2. Cari n dulu:Un = 49 → 11 + (n-1)2 = 49 → 2n + 9 = 49 → 2n = 40 → n = 20.S20 = 20/2 × (11 + 49) = 10 × 60 = 600.', NULL, NULL),
(828, 828, 'CMari hitung bertahap. Awal = 100.Jam ke-2: (100 × 2) - 50 = 150.Jam ke-4: (150 × 2) - 50 = 250.Jam ke-6: (250 × 2) - 50 = 450 bakteri.', NULL, NULL),
(829, 829, 'CDeret ini memiliki a = 2, r = 2. Sn = a(rⁿ - 1)/(r - 1) → 254 = 2(2ⁿ - 1)/1 → 127 = 2ⁿ - 1 → 128 = 2ⁿ. Diperoleh n = 7.', NULL, NULL),
(830, 830, 'CMisalkan bilangannya a/r, a, a×r. Hasil kali = a³ = 216 → a = 6.Jumlah = 6/r + 6 + 6r = 26 → 6/r + 6r = 20 → 3/r + 3r = 10 → 3r² - 10r + 3 = 0. Diperoleh r = 3 atau r = 1/3.Bilangannya 2, 6, 18. Yang terbesar adalah 18.', NULL, NULL),
(831, 831, 'CCari total kursi (S10) dari deret aritmetika (a=15, b=3). S10 = 10/2(2(15)+9(3)) = 5(30+27) = 5(57) = 285 kursi.Pendapatan = 285 × Rp50.000 = Rp14.250.000,00.', NULL, NULL),
(832, 832, 'CIni deret geometri tak hingga karena bandul berayun sampai berhenti. a = 40, r = 3/4.S∞ = a / (1 - r) = 40 / (1 - 3/4) = 40 / (1/4) = 160 cm.', NULL, NULL),
(833, 833, 'BSetoran Ali = 50.000 + 5.000(n-1). Setoran Budi = 100.000 - 5.000(n-1).Samakan: 50 + 5(n-1) = 100 - 5(n-1) → 10(n-1) = 50 → n-1 = 5 → n = 6. Jadi, sama pada bulan ke-6.', NULL, NULL),
(834, 834, 'An = 5, a = 4, U5 = 324.a × r⁴ = 324 → 4r⁴ = 324 → r⁴ = 81 → r = 3.S5 = 4(3⁵ - 1) / (3 - 1) = 4(243 - 1) / 2 = 2 × 242 = 484 cm.', NULL, NULL),
(835, 835, 'CS5 = 50 → a + 2b = 10. S10 = 150 → 2a + 9b = 30.Eliminasi: kalikan pers (1) dengan 2 → 2a + 4b = 20. Kurangkan dengan pers (2) → 5b = 10 → b = 2, sehingga a = 6.S15 = 15/2 × (2(6) + 14(2)) = 15/2 × (12 + 28) = 15/2 × 40 = 300.', NULL, NULL),
(836, 836, 'BDiketahui n = 5, suku awal (a) = 12, dan suku terakhir (U5) = 24. Kita bisa langsung pakai rumus Sn = n/2(a + Un).S5 = 5/2 × (12 + 24) = 5/2 × 36 = 90 tahun.', NULL, NULL),
(837, 837, 'BIni deret aritmetika dengan a = 36 juta, b = 3 juta, dan n = 10.S10 = 10/2(2(36) + 9(3)) = 5(72 + 27) = 5(99) = 495 juta rupiah.', NULL, NULL),
(838, 838, 'BLuas persegi pertama (L1) = 100. Luas persegi kedua (L2) yang dibentuk dari titik tengah selalu 1/2 dari luas sebelumnya. r = 1/2.S∞ = a / (1 - r) = 100 / (1 - 1/2) = 100 / 0.5 = 200 cm².', NULL, NULL),
(839, 839, 'BPola potongannya mengikuti barisan geometri rasio 2. Potongan ke-1 = 2, ke-2 = 4, dst. Rumusnya Un = 2ⁿ.Pemotongan ke-6 menghasilkan U6 = 2⁶ = 64 potong.', NULL, NULL),
(840, 840, 'AMenyusut 10% berarti nilainya menjadi 90% (atau 0,9) tiap tahun. r = 0,9.Awal tahun ke-4 sama dengan setelah 3 tahun pemakaian (U4).U4 = a × r³ = 200.000.000 × (0,9)³ = 200.000.000 × 0,729 = Rp145.800.000,00.', NULL, NULL),
(841, 841, 'APopulasi tersisa mengikuti barisan geometri: Awal = 5.000. Minggu 1 = 1.000. Minggu 2 = 200. Minggu 3 = 40.Total serangga yang mati = Jumlah awal dikurangi sisa akhir di minggu 3 = 5.000 - 40 = 4.960 ekor.', NULL, NULL),
(842, 842, 'Jawaban: BSudut bertolak belakang selalu sama besar. Jadi sudut pasangannya = 60°.', NULL, NULL),
(843, 843, 'Jawaban: A, B, CSudut bertolak belakang sama besar; sudut berpelurus berjumlah 180° sehingga 110°; jumlah satu putaran 360°.', NULL, NULL),
(844, 844, 'Jawaban: BPada dua garis sejajar, sudut sehadap besarnya sama.', NULL, NULL),
(845, 845, 'Jawaban: A, B, CSudut sehadap dan bertolak belakang sama besar. Sudut berpelurus berjumlah 180°, sehingga pasangannya 60°.', NULL, NULL),
(846, 846, 'Jawaban: BJumlah sudut dalam segitiga 180°. Jadi 180° − 50° − 60° = 70°.', NULL, NULL),
(847, 847, 'Jawaban: A, B, CJumlah sudut segitiga 180°. Segitiga siku-siku memiliki satu sudut 90°, dan sama sisi memiliki tiga sudut 60°.', NULL, NULL),
(848, 848, 'Jawaban: ATeorema Pythagoras: c² = 6² + 8² = 36 + 64 = 100, sehingga c = 10 cm.', NULL, NULL),
(849, 849, 'Jawaban: A, B, CCek a²+b²=c². Tiga pasangan pertama memenuhi: 9+16=25, 25+144=169, dan 36+64=100.', NULL, NULL),
(850, 850, 'Jawaban: BAda dua sisi yang sama panjang, yaitu 5 cm dan 5 cm, sehingga merupakan segitiga sama kaki.', NULL, NULL),
(851, 851, 'Jawaban: A, B, C, DBangun yang memiliki ukuran bersesuaian sama dapat berimpit tepat setelah dipindahkan/diputar, sehingga kongruen.', NULL, NULL),
(852, 852, 'Jawaban: CKesebangunan ditandai sudut bersesuaian sama besar dan perbandingan sisi bersesuaian tetap.', NULL, NULL),
(853, 853, 'Jawaban: A, B, C, EKongruen berarti bentuk dan ukuran sama. Bangun dapat dibuat berimpit melalui translasi, rotasi, atau refleksi.', NULL, NULL),
(854, 854, 'Jawaban: DFaktor skala 2 berarti setiap panjang sisi dikalikan 2. Jadi 7 × 2 = 14 cm.', NULL, NULL),
(855, 855, 'Jawaban: A, B, C, DKubus memiliki 6 sisi persegi. Susunan persegi harus memungkinkan keenam sisi menutup kubus tanpa bertumpuk.', NULL, NULL),
(856, 856, 'Jawaban: BPrisma segitiga memiliki 2 sisi segitiga dan 3 sisi persegi panjang, total 5 sisi.', NULL, NULL),
(857, 857, 'Jawaban: A, EJaring prisma segitiga terdiri dari dua segitiga kongruen dan tiga persegi panjang.', NULL, NULL),
(858, 858, 'Jawaban: CSetiap balok memiliki 12 rusuk.', NULL, NULL),
(859, 859, 'Jawaban: A, B, C, EBalok memiliki 6 sisi, 8 titik sudut, 12 rusuk, dan pasangan sisi berhadapan yang sejajar.', NULL, NULL),
(860, 860, 'Jawaban: BPada persegi panjang, sisi yang berhadapan sama panjang dan sejajar.', NULL, NULL),
(861, 861, 'Jawaban: A, B, DDiagonal persegi panjang sama panjang, saling membagi dua, dan menghubungkan titik sudut berhadapan.', NULL, NULL),
(862, 862, 'Jawaban: BJumlah sudut segitiga 180°. Sudut ketiga = 180° − 55° − 65° = 60°.', NULL, NULL),
(863, 863, 'Jawaban: A, BPada dua garis sejajar yang dipotong transversal, sudut yang muncul hanya dua ukuran: 70° dan 110°.', NULL, NULL),
(864, 864, 'Jawaban: CDengan Pythagoras: tinggi² + 3² = 5², sehingga tinggi² = 16 dan tinggi = 4 m.', NULL, NULL),
(865, 865, 'Jawaban: A, B, C, DDiagonal = √(9²+12²)=√225=15 m. Keliling=2(9+12)=42 m dan luas=9×12=108 m².', NULL, NULL),
(866, 866, 'Jawaban: BKabel menjadi sisi miring segitiga siku-siku: √(12²+5²)=√169=13 m.', NULL, NULL),
(867, 867, 'Jawaban: A, B, C, D6²+8²=100=10², jadi siku-siku. Luas = 1/2×6×8=24 cm². Keliling = 24 cm, sehingga E salah.', NULL, NULL),
(868, 868, 'Jawaban: BTinggi membagi alas menjadi 6 m dan 6 m. Dengan Pythagoras, tinggi²=10²−6²=64, jadi tinggi=8 m.', NULL, NULL),
(869, 869, 'Jawaban: A, B, C, DPada persegi, diagonal = sisi√2, jadi sisi=10 m. Luas=100 m² dan keliling=40 m.', NULL, NULL),
(870, 870, 'Jawaban: BFaktor skala = 18/12 = 1,5. Panjang baru = 8×1,5 = 12 cm.', NULL, NULL),
(871, 871, 'Jawaban: A, B, D, EPanjang dikali 3, sedangkan luas dikali 3²=9. Keliling juga dikali 3.', NULL, NULL),
(872, 872, 'Jawaban: CSegitiga bayangan sebangun: 2/3 = tinggi/9, sehingga tinggi = 6 m.', NULL, NULL),
(873, 873, 'Jawaban: A, B, C, E18×50=900 cm=9 m. Skala 1:50 berarti 1 cm model mewakili 50 cm sebenarnya.', NULL, NULL),
(874, 874, 'Jawaban: EFaktor skala = 15/6 = 2,5. Panjang B = 10×2,5 = 25 cm.', NULL, NULL),
(875, 875, 'Jawaban: A, B, C, DKubus memiliki 6 sisi persegi, 12 rusuk, dan 8 titik sudut. Tidak semua susunan 6 persegi merupakan jaring-jaring kubus.', NULL, NULL),
(876, 876, 'Jawaban: CJaring-jaringnya memuat semua 5 sisi: 2 segitiga dan 3 persegi panjang.', NULL, NULL),
(877, 877, 'Jawaban: A, B, CBalok memiliki tiga pasangan sisi: 10×6, 10×4, dan 6×4.', NULL, NULL),
(878, 878, 'Jawaban: CLuas persegi panjang = 14×8=112 cm². Diagonal membagi menjadi dua bagian sama luas, jadi 56 cm².', NULL, NULL),
(879, 879, 'Jawaban: A, B, D, EKongruen berarti sisi, sudut, luas, dan keliling bersesuaian sama.', NULL, NULL),
(880, 880, 'Jawaban: DUkuran susunan = 4×30=120 cm dan 6×30=180 cm. Diagonal = √(120²+180²)=√46800=60√13 cm.', NULL, NULL),
(881, 881, 'Jawaban: B, C, DSisi yang ditempel menjadi bagian dalam. Dua kubus sisi 4 cm menghasilkan panjang 8 cm dan volume total 2×4³=128 cm³.', NULL, NULL),
(882, 882, 'Jawaban: CSudut dalam sepihak berjumlah 180°. 3x+10+2x+20=180 → 5x=150 → x=30.', NULL, NULL),
(883, 883, 'Jawaban: A, B, C, ESudut sehadap sama: 4x−10=2x+30 → x=20. A=B=70°.', NULL, NULL),
(884, 884, 'Jawaban: BLuas = 1/2×5×s = 30 → 5s=60 → s=12 cm.', NULL, NULL),
(885, 885, 'Jawaban: A, C, EPasangan harus memenuhi a²+b²=169. 5²+12²=169; 10²+69=169; 8²+105=169.', NULL, NULL),
(886, 886, 'Jawaban: BLebar² = 25²−24² = 625−576 = 49, sehingga lebar = 7 cm.', NULL, NULL),
(887, 887, 'Jawaban: A, B, C, E7²+24²=49+576=625=25², sehingga siku-siku. Keliling=7+24+25=56 cm.', NULL, NULL),
(888, 888, 'Jawaban: CPerbandingan luas adalah kuadrat faktor skala: (3/2)²=9/4. Luas besar = 24×9/4=54 cm².', NULL, NULL),
(889, 889, 'Jawaban: A, B, C, EPanjang dan keliling dikali 2,5; luas dikali 2,5²=6,25; sudut tetap.', NULL, NULL),
(890, 890, 'Jawaban: CPerbandingan sisi 6:9 = 8:12 = 10:15 = 2:3, sehingga sebangun dengan skala kecil:besar = 2:3.', NULL, NULL),
(891, 891, 'Jawaban: A, B, D, EFaktor skala=18/12=1,5. Lebar B=8×1,5=12. Luas B=216, bukan 324. Keliling B=2(18+12)=60. Rasio luas=1,5²=9/4.', NULL, NULL),
(892, 892, 'Jawaban: BJaring-jaring kubus harus dapat dilipat menjadi enam sisi yang berbeda tanpa bertumpuk.', NULL, NULL),
(893, 893, 'Jawaban: A, B, C, EJaring-jaring memiliki dua sisi 12×8, dua sisi 12×5, dan dua sisi 8×5. Luas permukaan = 392 cm².', NULL, NULL),
(894, 894, 'Jawaban: AVolume prisma = luas alas × tinggi. Jika tinggi menjadi dua kali, volume juga dua kali. Jadi V lama : V baru = 1 : 2.', NULL, NULL),
(895, 895, 'Jawaban: A, B, C, EMasing-masing luas=10×4=40 cm². Tiga buah berarti 120 cm².', NULL, NULL),
(896, 896, 'Jawaban: BSisi persegi pertama = diagonal/√2 = 14 cm. Karena luas sama, sisi persegi kedua juga 14 cm.', NULL, NULL),
(897, 897, 'Jawaban: A, B, C, D9²+12²=15². Luas=1/2×9×12=54. Keliling=36. Karena siku-siku, sisi 15 adalah sisi miring.', NULL, NULL),
(898, 898, 'Jawaban: DUkuran sebenarnya: alas=64 cm, tinggi=48 cm. Luas=1/2×64×48=1.536 cm².', NULL, NULL),
(899, 899, 'Jawaban: A, B, C, DSatu kubus volumenya 125 cm³, jadi total 250 cm³. Sisi yang ditempel menjadi bagian dalam sehingga luas permukaan berkurang.', NULL, NULL),
(900, 900, 'Jawaban: CKarena DE ∥ BC, segitiga ADE sebangun dengan ABC. AD/AB=3/6=1/2, sehingga AE/AC=1/2. AE=4 cm.', NULL, NULL),
(901, 901, 'Jawaban: A, B, D, EPerbandingan panjang = 2:5. Perbandingan luas = (2/5)²=4:25. Kesebangunan juga membuat sudut bersesuaian sama.', NULL, NULL),
(902, 902, 'Jawaban: BPergeseran semua titik sejauh dan searah yang sama tanpa mengubah bentuk dan ukuran adalah definisi translasi (pergeseran).', NULL, NULL),
(903, 903, 'Jawaban: DA′ = (3 + 2, 5 + (−4)) = (5, 1).', NULL, NULL),
(904, 904, 'Jawaban: BPada refleksi terhadap sumbu-x, (x, y) menjadi (x, −y). Jadi P′ = (−4, −7).', NULL, NULL),
(905, 905, 'Jawaban: DPada refleksi terhadap sumbu-y, (x, y) menjadi (−x, y). Jadi Q′ = (−6, −2).', NULL, NULL),
(906, 906, 'Jawaban: BRotasi 180° pusat O mengubah (x, y) menjadi (−x, −y). Jadi R′ = (−2, 3).', NULL, NULL),
(907, 907, 'Jawaban: ADilatasi pusat O faktor k: (x, y) → (kx, ky). B′ = (3 × 4, 3 × 6) = (12, 18).', NULL, NULL),
(908, 908, 'Jawaban: DTranslasi, refleksi, dan rotasi hanya memindahkan bangun tanpa mengubah ukurannya. Hanya dilatasi yang memperbesar atau memperkecil bangun.', NULL, NULL),
(909, 909, 'Jawaban: CVektor translasi = bayangan − titik awal = (1 − (−2), 1 − 5) = (3, −4).', NULL, NULL),
(910, 910, 'Jawaban: BRefleksi terhadap garis y = x menukar koordinat: (x, y) → (y, x). Jadi (5, 2) → (2, 5).', NULL, NULL),
(911, 911, 'Jawaban: DRotasi 90° berlawanan arah jarum jam: (x, y) → (−y, x). Jadi (3, −1) → (1, 3).', NULL, NULL),
(912, 912, 'Jawaban: CPersegi memiliki 4 sumbu simetri: 2 diagonal dan 2 garis yang melalui titik tengah sisi-sisi berhadapan. Sumbu simetri dapat dipandang sebagai garis cermin pada refleksi.', NULL, NULL),
(913, 913, 'Jawaban: ARefleksi terhadap garis y = k: (x, y) → (x, 2k − y). Jadi (2, 7) → (2, 6 − 7) = (2, −1).', NULL, NULL),
(914, 914, 'Jawaban: DTranslasi hanya menggeser bangun, sehingga bentuk dan ukurannya tetap (bangun bayangan kongruen dengan bangun semula).', NULL, NULL),
(915, 915, 'Jawaban: BRotasi tidak mengubah ukuran bangun, sehingga panjang sisi bayangan tetap 3 cm, 4 cm, dan 5 cm.', NULL, NULL),
(916, 916, 'Jawaban: DC′ = (4 + (−2), 3 + 3) = (2, 6).', NULL, NULL),
(917, 917, 'Jawaban: A(x, y) → (kx, ky) dengan k = ½: (½ × 8, ½ × (−6)) = (4, −3).', NULL, NULL),
(918, 918, 'Jawaban: CRefleksi terhadap titik asal: (x, y) → (−x, −y). Jadi K′ = (3, 8).', NULL, NULL),
(919, 919, 'Jawaban: A, B, DTranslasi, refleksi, dan rotasi adalah transformasi yang mempertahankan bentuk, ukuran, dan jarak antartitik. Pernyataan C salah karena ukuran bangun tidak berubah.', NULL, NULL),
(920, 920, 'Jawaban: A, C, DA benar: (x, −y). B salah: refleksi sumbu-y menghasilkan (−2, 3). C benar: (2 + 1, 3 + 1) = (3, 4). D benar: (−x, −y) = (−2, −3).', NULL, NULL),
(921, 921, 'Jawaban: A, BA dan B benar. C salah karena k = 1 membuat bangun tidak berubah. D salah karena kongruen hanya terjadi bila k = 1; untuk k lain bangun hanya sebangun.', NULL, NULL),
(922, 922, 'Jawaban: CKe kanan 4 satuan berarti x + 4, ke bawah 2 satuan berarti y − 2 (translasi (4, −2)). Posisi baru: (2 + 4, 3 − 2) = (6, 1).', NULL, NULL),
(923, 923, 'Jawaban: ARefleksi terhadap sumbu-y: (x, y) → (−x, y). Jadi bayangan lampu berada di (3, 4).', NULL, NULL),
(924, 924, 'Jawaban: BSetiap titik ditambah (3, −1): A′(1 + 3, 2 − 1) = (4, 1); B′(4 + 3, 2 − 1) = (7, 1); C′(1 + 3, 6 − 1) = (4, 5).', NULL, NULL),
(925, 925, 'Jawaban: BSisi semula 2 satuan, luas 4. Setelah dilatasi faktor 2, sisi menjadi 4 satuan sehingga luas = 4 × 4 = 16 satuan luas (luas berubah k² = 4 kali).', NULL, NULL),
(926, 926, 'Jawaban: DPanjang dan lebar dikalikan faktor skala: 4 × 2,5 = 10 cm dan 6 × 2,5 = 15 cm.', NULL, NULL),
(927, 927, 'Jawaban: CRefleksi terhadap garis x = h: (x, y) → (2h − x, y). Jadi (2 × 2 − 5, −1) = (−1, −1).', NULL, NULL),
(928, 928, 'Jawaban: BPerpindahan = (−1 − 2, 6 − 4) = (−3, 2), yaitu 3 satuan ke kiri dan 2 satuan ke atas.', NULL, NULL),
(929, 929, 'Jawaban: CRotasi 90° searah jarum jam: (x, y) → (y, −x). Jadi (4, 1) → (1, −4).', NULL, NULL),
(930, 930, 'Jawaban: BAB = 3, AC = 4, BC = 5 sehingga keliling semula 12. Dilatasi faktor 2 melipatgandakan setiap sisi, jadi keliling bayangan = 2 × 12 = 24.', NULL, NULL),
(931, 931, 'Jawaban: DRefleksi terhadap garis y = x: (x, y) → (y, x). Jadi (−3, 7) → (7, −3).', NULL, NULL),
(932, 932, 'Jawaban: CTranslasi: (3 + 1, 2 − 5) = (4, −3). Refleksi sumbu-x: (x, y) → (x, −y) sehingga hasil akhir (4, 3).', NULL, NULL),
(933, 933, 'Jawaban: DRefleksi sumbu-y: (2, −5) → (−2, −5). Translasi (−1, 4): (−2 − 1, −5 + 4) = (−3, −1).', NULL, NULL),
(934, 934, 'Jawaban: BRotasi 180°: (1, −2) → (−1, 2). Dilatasi faktor 2: (−1, 2) → (−2, 4).', NULL, NULL),
(935, 935, 'Jawaban: CUntuk pusat (a, b): x′ = a + k(x − a), y′ = b + k(y − b). x′ = 1 + 3(2 − 1) = 4 dan y′ = 1 + 3(3 − 1) = 7. Jadi (4, 7).', NULL, NULL),
(936, 936, 'Jawaban: DRotasi 270° berlawanan arah jarum jam sama dengan rotasi 90° searah jarum jam: (x, y) → (y, −x). Jadi (−2, 5) → (5, 2).', NULL, NULL),
(937, 937, 'Jawaban: BRefleksi terhadap y = k: y′ = 2k − y = 2(−1) − 4 = −6, sedangkan x tetap. Jadi (3, −6).', NULL, NULL),
(938, 938, 'Jawaban: B, CA′ = (1, 3), sehingga A salah. B′ = (4, 3) dan C′ = (4, 6) benar. Translasi tidak mengubah ukuran, jadi luasnya tetap (4,5 satuan luas); D salah.', NULL, NULL),
(939, 939, 'Jawaban: A, C, DP′ = (2, 2) dan R′ = (2, 8) benar; Q′ = (6, 2) sehingga B salah. Luas PQR = ½ × 2 × 3 = 3, luas bayangan = 3 × 2² = 12 satuan luas.', NULL, NULL),
(940, 940, 'Jawaban: A, B, DA, B, dan D benar. C salah: rotasi 180° pusat O menghasilkan (−x, −y) = (3, −2).', NULL, NULL),
(941, 941, 'Jawaban: A, C, DB′ = (4 − 2, 6 + 3) = (2, 9), sehingga B salah. Panjang AB = √(3² + 4²) = 5 dan translasi tidak mengubah panjang maupun arah ruas garis, jadi C dan D benar.', NULL, NULL),
(942, 942, 'Jawaban: B(2, 3) → (2, −3) → (−2, −3). Secara umum (x, y) → (x, −y) → (−x, −y), yaitu rotasi 180° pusat O. Translasi (−4, −6) hanya cocok untuk titik A; untuk titik (1, 1) hasilnya (−3, −5), bukan (−1, −1).', NULL, NULL),
(943, 943, 'Jawaban: CTelusuri mundur. Sebelum refleksi sumbu-y titiknya (5, 1). Sebelum translasi: (5 − 3, 1 − (−2)) = (2, 3). Jadi a = 2, b = 3, dan a + b = 5.', NULL, NULL),
(944, 944, 'Jawaban: ARotasi 90° berlawanan arah jarum jam: (x, y) → (−y, x) = (−6, 4), cocok. Pilihan lain menghasilkan (6, −4), (4, −6), dan (6, 4).', NULL, NULL),
(945, 945, 'Jawaban: DPada dilatasi faktor k, luas berubah k² kali. k² = 9, sehingga k = 3 (faktor skala positif).', NULL, NULL),
(946, 946, 'Jawaban: BBayangan akhir = (3x + 2, 3y − 1) = (5, 8). 3x + 2 = 5 → x = 1; 3y − 1 = 8 → y = 3. Jadi (1, 3).', NULL, NULL),
(947, 947, 'Jawaban: CA′ = (2 × 1 − 3, 4) = (−1, 4). A″ = (2 × 5 − (−1), 4) = (11, 4). Perpindahan dari A ke A″ adalah (8, 0), yaitu dua kali jarak antara kedua garis cermin (2 × 4).', NULL, NULL),
(948, 948, 'Jawaban: D3 × 90° = 270° searah jarum jam. Putaran 270° searah sama dengan 360° − 270° = 90° berlawanan arah jarum jam.', NULL, NULL),
(949, 949, 'Jawaban: DUntuk pusat (a, b) berlaku x′ = a + k(x − a). Dari x′ pada A dan B: 7 − 4 = k(3 − 2) sehingga k = 3. Lalu 4 − a = 3(2 − a) memberi a = 1, dan 7 − b = 3(3 − b) memberi b = 1. Cek: B → (1 + 3(3 − 1), 1 + 3(2 − 1)) = (7, 4).', NULL, NULL),
(950, 950, 'Jawaban: CTranslasi dahulu: (4 − 3, −2 + 5) = (1, 3), lalu refleksi sumbu-y: (−1, 3), sesuai jawaban Andi. Budi menukar urutan sehingga hasilnya berbeda. Urutan transformasi umumnya memengaruhi hasil akhir.', NULL, NULL),
(951, 951, 'Jawaban: BFaktor skala k = 36 ÷ 12 = 3. Luas berubah k² = 9 kali, sehingga luas bayangan = 9 × 10 = 90 cm².', NULL, NULL),
(952, 952, 'Jawaban: ARefleksi terhadap garis x = h: (x, y) → (2h − x, y). Dengan h = 2 diperoleh (4 − x, y). Cek: titik (0, y) menjadi (4, y), keduanya berjarak 2 dari garis x = 2.', NULL, NULL),
(953, 953, 'Jawaban: DDua translasi berurutan dijumlahkan: (2 + (−5), −3 + 1) = (−3, −2).', NULL, NULL),
(954, 954, 'Jawaban: CRefleksi terhadap garis y = −x: (x, y) → (−y, −x) = (−5, −2), cocok. Garis y = x memberi (5, 2), sumbu-y memberi (−2, 5), dan sumbu-x memberi (2, −5).', NULL, NULL),
(955, 955, 'Jawaban: ADilatasi mengubah panjang sisi, tetapi tidak mengubah besar sudut karena bangun bayangan sebangun dengan bangun semula.', NULL, NULL),
(956, 956, 'Jawaban: A, C, D(2, 5) → (−2, −5) → (−2, 5), sehingga B salah. Secara umum (x, y) → (−x, −y) → (−x, y), yaitu refleksi terhadap sumbu-y. Rotasi dan refleksi tidak mengubah bentuk dan ukuran, jadi hasilnya kongruen.', NULL, NULL),
(957, 957, 'Jawaban: A, C, DBayangan berukuran 3 cm × 2 cm: keliling 10 cm (A benar), luas 6 cm² (B salah), perbandingan 3 : 2 tetap (C benar), dan sebangun (D benar).', NULL, NULL),
(958, 958, 'Jawaban: B, CA′ = (3, 4), sehingga A salah. Pada refleksi, titik dan bayangannya berjarak sama dari garis cermin (B benar) dan ruas penghubungnya tegak lurus garis cermin (C benar; gradien AA′ = −1). Titik tengah AA′ = (7/2, 7/2) terletak pada garis y = x, sehingga D salah.', NULL, NULL),
(959, 959, 'Jawaban: A, C, DA benar: (−y, x) = (−4, −3). B salah: rotasi 90° searah menghasilkan (y, −x) = (4, 3). C benar: OB = √(9 + 16) = 5 dan rotasi mempertahankan jarak ke pusat. D benar karena dua rotasi berlawanan saling meniadakan.', NULL, NULL),
(960, 960, 'Jawaban: A, BDilatasi: (4, 8); translasi: (0, 9). Titik dengan x = 0 terletak pada sumbu-y, bukan di kuadran mana pun. Bila dibalik: (2 − 4, 4 + 1) = (−2, 5) lalu dilatasi menjadi (−4, 10), berbeda dari (0, 9).', NULL, NULL),
(961, 961, 'Jawaban: A, BTranslasi, rotasi, dan refleksi mempertahankan panjang sisi dan luas, sehingga C dan D salah. Dilatasi dengan k = 2 memperbesar ukuran sehingga bayangan sebangun, bukan kongruen.', NULL, NULL),
(962, 962, 'Kunci Jawaban: BPembahasan: Luas persegi panjang = panjang × lebar = 18 × 12 = 216 m².', NULL, NULL),
(963, 963, 'Kunci Jawaban: BPembahasan: Keliling lingkaran = πd = (22/7) × 14 = 44 cm.', NULL, NULL),
(964, 964, 'Kunci Jawaban: BPembahasan: Luas segitiga = ½ × alas × tinggi = ½ × 16 × 9 = 72 cm².', NULL, NULL),
(965, 965, 'Kunci Jawaban: BPembahasan: Luas persegi panjang = 100 cm². Luas setengah lingkaran = ½ × (22/7) × 5² = 275/7 ≈ 39,3 cm². Total ≈ 139,3 cm².', NULL, NULL),
(966, 966, 'Kunci Jawaban: CPembahasan: Keliling jajargenjang = 2(13 + 8) = 42 cm.', NULL, NULL),
(967, 967, 'Kunci Jawaban: BPembahasan: Luas petak pertama = 7 × 24 = 168 m², sedangkan petak kedua = 10 × 20 = 200 m². Jadi petak kedua lebih luas.', NULL, NULL),
(968, 968, 'Kunci Jawaban: CPembahasan: Volume balok = 15 × 8 × 6 = 720 cm³.', NULL, NULL),
(969, 969, 'Kunci Jawaban: DPembahasan: Luas alas segitiga = ½ × 10 × 6 = 30 cm². Volume = 30 × 12 = 360 cm³.', NULL, NULL),
(970, 970, 'Kunci Jawaban: CPembahasan: Luas alas = 10 × 10 = 100 cm². Volume limas = ⅓ × 100 × 12 = 400 cm³.', NULL, NULL),
(971, 971, 'Kunci Jawaban: DPembahasan: Volume bola = 4/3 πr³ = 4/3 × π × 27 = 36π cm³.', NULL, NULL),
(972, 972, 'Kunci Jawaban: CPembahasan: 1 liter = 1.000 cm³, sehingga 2,5 liter = 2.500 cm³.', NULL, NULL),
(973, 973, 'Kunci Jawaban: CPembahasan: Jika luas persegi s² = 144, maka s = √144 = 12 cm.', NULL, NULL),
(974, 974, 'Kunci Jawaban: CPembahasan: Luas = (16 × 10) − (6 × 4) = 160 − 24 = 136 m².', NULL, NULL),
(975, 975, 'Kunci Jawaban: APembahasan: 8 × 15 = 120 dan 10 × 12 = 120. Pasangan lainnya menghasilkan luas yang berbeda.', NULL, NULL),
(976, 976, 'Kunci Jawaban: BPembahasan: 2(p + l) = 50, sehingga p + l = 25. Dengan p = 16, diperoleh l = 9 cm.', NULL, NULL),
(977, 977, 'Kunci Jawaban: CPembahasan: K = πd, jadi d = 62,8 ÷ 3,14 = 20 cm.', NULL, NULL),
(978, 978, 'Kunci Jawaban: A, B, CPembahasan: A, B, dan C benar. Luas awal 96 cm², keliling 40 cm, sedangkan ukuran baru 13 × 9 memberi luas 117 cm². Pertambahan luasnya 21 cm², bukan 11 cm².', NULL, NULL),
(979, 979, 'Kunci Jawaban: A, B, CPembahasan: A, B, dan C benar. Gunakan V = luas alas × tinggi. Pernyataan D salah karena perubahan tinggi mengubah volume.', NULL, NULL),
(980, 980, 'Kunci Jawaban: A, BPembahasan: Keliling = 4 × 14 = 56 cm. Luas = 14² = 196 cm². Diagonal = 14√2 cm, bukan 28 cm.', NULL, NULL),
(981, 981, 'Kunci Jawaban: A, CPembahasan: Volume awal 36π cm³ dan diameter 6 cm. Jika jari-jari dilipatgandakan, volume menjadi 2³ = 8 kali semula, yaitu 288π cm³.', NULL, NULL),
(982, 982, 'Kunci Jawaban: BPembahasan: Keliling taman = 2(18 + 12) = 60 m. Panjang pagar yang dibutuhkan = 60 − 2 = 58 m. Biaya = 58 × Rp25.000,00 = Rp1.450.000,00.', NULL, NULL),
(983, 983, 'Kunci Jawaban: BPembahasan: Luas dinding = 32 m². Luas setengah lingkaran = ½ × (22/7) × 2² = 44/7 ≈ 6,29 m². Total ≈ 38,29 m². Karena 38,29 ÷ 10 ≈ 3,83, perlu 4 liter.', NULL, NULL),
(984, 984, 'Kunci Jawaban: CPembahasan: Banyak kardus = 108 ÷ 2,25 = 48 kardus.', NULL, NULL),
(985, 985, 'Kunci Jawaban: CPembahasan: Satu putaran = 40 + 40 + satu keliling lingkaran berdiameter 14 = 80 + 44 = 124 m. Untuk 5 putaran: 5 × 124 = 620 m.', NULL, NULL),
(986, 986, 'Kunci Jawaban: CPembahasan: Luas taman = 20 × 14 = 280 m². Luas kolam = 22/7 × 7² = 154 m². Sisa = 280 − 154 = 126 m².', NULL, NULL),
(987, 987, 'Kunci Jawaban: CPembahasan: Volume = 2,5 × 1,6 × 1,2 = 4,8 m³ = 4.800 liter.', NULL, NULL),
(988, 988, 'Kunci Jawaban: CPembahasan: Luas penampang segitiga = ½ × 4 × 2,5 = 5 m². Volume prisma = 5 × 6 = 30 m³.', NULL, NULL),
(989, 989, 'Kunci Jawaban: CPembahasan: Volume satu limas = ⅓ × 10 × 10 × 12 = 400 cm³. Untuk 15 kotak = 15 × 400 = 6.000 cm³.', NULL, NULL),
(990, 990, 'Kunci Jawaban: CPembahasan: Karena setiap bola volumenya 36π cm³, maka 10 bola memiliki volume 10 × 36π = 360π cm³.', NULL, NULL),
(991, 991, 'Kunci Jawaban: CPembahasan: Volume bak = 3 × 2 × 1,5 = 9 m³ = 9.000 liter. Karena 9.000 > 8.500, bak cukup.', NULL, NULL),
(992, 992, 'Kunci Jawaban: CPembahasan: Jari-jari = 70 cm. Luas = (22/7) × 70² = 15.400 cm².', NULL, NULL),
(993, 993, 'Kunci Jawaban: BPembahasan: Luas = p × l, sehingga l = 960 ÷ 40 = 24 cm.', NULL, NULL),
(994, 994, 'Kunci Jawaban: CPembahasan: Luas persegi luar = 14² = 196 m². Luas taman = 10² = 100 m². Jalur batu = 196 − 100 = 96 m².', NULL, NULL),
(995, 995, 'Kunci Jawaban: CPembahasan: Total luas = 18 × 9 = 162 m². Bagian yang tersisa = 1 − 1/2 − 1/4 = 1/4. Jadi luas bayam = 1/4 × 162 = 40,5 m².', NULL, NULL),
(996, 996, 'Kunci Jawaban: DPembahasan: Volume = 2,4 × 1,5 × 0,4 = 1,44 m³ = 1.440 liter.', NULL, NULL),
(997, 997, 'Kunci Jawaban: DPembahasan: 72.000 cm³ = 72 liter. Untuk 5 kotak: 5 × 72 = 360 liter.', NULL, NULL),
(998, 998, 'Kunci Jawaban: BPembahasan: Jari-jari = 1 m. Luas lingkaran = 3,14 × 1² = 3,14 m².', NULL, NULL),
(999, 999, 'Kunci Jawaban: APembahasan: Volume wadah = 240 × 18 = 4.320 cm³. Jadi tepat 1 paket yang membutuhkan 4.320 cm³.', NULL, NULL),
(1000, 1000, 'Kunci Jawaban: CPembahasan: Keliling = 2 × (22/7) × 7 = 44 m. Biaya = 44 × Rp22.000,00 = Rp968.000,00.', NULL, NULL),
(1001, 1001, 'Kunci Jawaban: A, B, CPembahasan: A, B, dan C benar. Luas persegi panjang = 360 m². Luas setengah lingkaran = 18π m². Dengan π = 22/7, 360 + 396/7 ≈ 416,6 m². Pernyataan D salah.', NULL, NULL),
(1002, 1002, 'Kunci Jawaban: BPembahasan: Luas P = 84 m² dan luas Q = 100 m². Selisihnya 16 m², sedangkan keliling keduanya sama-sama 40 m.', NULL, NULL),
(1003, 1003, 'Kunci Jawaban: CPembahasan: Semua pilihan memiliki keliling 64 m. Luas berturut-turut 240, 252, 255, dan 192 m². Jadi yang terbesar adalah 17 m × 15 m.', NULL, NULL),
(1004, 1004, 'Kunci Jawaban: CPembahasan: Luas taman 280 m², sehingga luas kolam harus kurang dari 160 m². Untuk d = 14, luas kolam = 154 m² dan rumput = 126 m², masih lebih dari 120. Untuk d = 15, luas kolam ≈ 176,8 m² sehingga tidak memenuhi.', NULL, NULL),
(1005, 1005, 'Kunci Jawaban: BPembahasan: Dari keliling diperoleh p + l = 29, sedangkan p × l = 180. Pasangan bilangan yang memenuhi kedua syarat tersebut adalah 9 dan 20.', NULL, NULL),
(1006, 1006, 'Kunci Jawaban: CPembahasan: Sisi persegi = 44 ÷ 4 = 11 cm, luas = 121 cm². Jari-jari lingkaran = 44 ÷ (2π) = 7 cm, luas = 154 cm². Selisih = 33 cm².', NULL, NULL),
(1007, 1007, 'Kunci Jawaban: A, C, DPembahasan: A, C, dan D benar. Luas berbanding dengan kuadrat jari-jari. Faktor 3 memberi luas 9A, bukan 6A.', NULL, NULL),
(1008, 1008, 'Kunci Jawaban: A, B, DPembahasan: A, B, dan D benar. Volume prisma = Ah, sedangkan limas = 1/3 Ah. Jadi perbandingan prisma : limas = 3 : 1.', NULL, NULL),
(1009, 1009, 'Kunci Jawaban: CPembahasan: Volume A = 2 × 1,5 × 1,2 = 3,6 m³. Volume B = ½ × 3 × 2 × 1,4 = 4,2 m³. Jadi B lebih besar.', NULL, NULL),
(1010, 1010, 'Kunci Jawaban: APembahasan: 12 × 4 merupakan rumus luas persegi panjang, sedangkan 12 + 12 + 4 + 4 = 32 merupakan keliling.', NULL, NULL),
(1011, 1011, 'Kunci Jawaban: CPembahasan: Volume bak = 2 × 2 × 1,5 = 6 m³ = 6.000 liter. Banyak pengisian = 6.000 ÷ 15 = 400 kali.', NULL, NULL),
(1012, 1012, 'Kunci Jawaban: CPembahasan: Volume prisma = 10 × 10 × 8 = 800 cm³. Volume limas = 1/3 × 100 × 6 = 200 cm³. Total = 1.000 cm³.', NULL, NULL),
(1013, 1013, 'Kunci Jawaban: DPembahasan: Dengan (1), keliling = 2(24 + 13) = 74 m. Dengan (2), 24w > 300 memberi w > 12,5, sehingga keliling > 73 m. Jadi masing-masing informasi cukup.', NULL, NULL),
(1014, 1014, 'Kunci Jawaban: DPembahasan: Luas baru = 22 × 8 = 176 cm², turun 24 cm² dari 200 cm². Keliling lama dan baru sama-sama 60 cm.', NULL, NULL),
(1015, 1015, 'Kunci Jawaban: CPembahasan: Luas awal = 3,14 × 5² = 78,5 cm². Luas baru = 3,14 × 6² = 113,04 cm². Selisih = 34,54 cm².', NULL, NULL),
(1016, 1016, 'Kunci Jawaban: APembahasan: Susunan tersebut membentuk persegi panjang berukuran ns × s. Jadi keliling = 2(ns + s) = 2(n + 1)s dan luas = ns².', NULL, NULL),
(1017, 1017, 'Kunci Jawaban: CPembahasan: Dua bangun dapat mempunyai luas sama tetapi keliling berbeda. Kesamaan luas tidak otomatis menentukan kesamaan keliling.', NULL, NULL),
(1018, 1018, 'Kunci Jawaban: BPembahasan: Tinggi awal = 1.200 ÷ 150 = 8 cm. Tinggi baru = 10 cm. Volume baru = 150 × 10 = 1.500 cm³.', NULL, NULL),
(1019, 1019, 'Kunci Jawaban: BPembahasan: Volume kubus = 14³ = 2.744 cm³. Volume bola = 4/3 × 22/7 × 7³ = 1.437 1/3 cm³. Jadi kubus lebih besar.', NULL, NULL),
(1020, 1020, 'Kunci Jawaban: CPembahasan: V = Ah. Karena 0,75h > 1,2, maka h > 1,6 m.', NULL, NULL),
(1021, 1021, 'Kunci Jawaban: A, B, CPembahasan: A, B, dan C benar. Volume merupakan hasil kali luas alas dan tinggi. Jika keduanya menjadi 2 kali, volume justru menjadi 4 kali, sehingga D salah.', NULL, NULL),
(1022, 1022, 'Kunci Jawaban: BPembahasan:- Populasi adalah keseluruhan objek yang menjadi sasaran penelitian/pengamatan, yaitu seluruh 720 siswa SMP Budi Luhur.- Sampel adalah bagian dari populasi yang diambil sebagai representasi/contoh untuk diteliti secara langsung, yaitu 60 siswa yang dipilih secara acak dari perwakilan kelas.Jadi, sampel dari kegiatan pendataan tersebut adalah 60 siswa perwakilan (Opsi B).', NULL, NULL),
(1023, 1023, 'Kunci Jawaban: DPembahasan:Untuk membaca tabel frekuensi secara langsung:1. Cari baris yang memuat nama hari \'Rabu\'.2. Perhatikan kolom \'Banyak Peminjam\' yang sejajar dengan hari Rabu, yaitu angka 25.Jadi, banyak siswa yang meminjam buku pada hari Rabu adalah 25 orang (Opsi D).', NULL, NULL),
(1024, 1024, 'Kunci Jawaban: CPembahasan:Total frekuensi dihitung dengan menjumlahkan seluruh datum:Total bibit = 15 + 28 + 22 + 15- 15 + 28 = 43- 43 + 22 = 65- 65 + 15 = 80Jadi, jumlah seluruh bibit tanaman adalah 80 bibit (Opsi C).', NULL, NULL),
(1025, 1025, 'Kunci Jawaban: BPembahasan:Modus adalah nilai/ukuran yang paling sering muncul (memiliki frekuensi tertinggi).Mari kita hitung kemunculan tiap ukuran sepatu:- Ukuran 37: muncul 1 kali- Ukuran 38: muncul 5 kali- Ukuran 39: muncul 2 kali- Ukuran 40: muncul 2 kali- Ukuran 41: muncul 1 kali- Ukuran 42: muncul 1 kaliUkuran sepatu yang paling banyak muncul adalah ukuran 38 (sebanyak 5 kali). Jadi, modusnya adalah 38 (Opsi B).', NULL, NULL),
(1026, 1026, 'Kunci Jawaban: BPembahasan:Median adalah nilai tengah dari kumpulan data yang telah diurutkan.Banyaknya data (n) = 9 (ganjil).Letak median = datum ke-(n + 1)/2 = datum ke-(9 + 1)/2 = datum ke-5.Mari kita hitung datum ke-5:1: 13,2 | 2: 13,5 | 3: 13,8 | 4: 14,0 | 5: 14,2Jadi, median data waktu tempuh tersebut adalah 14,2 detik (Opsi B).', NULL, NULL),
(1027, 1027, 'Kunci Jawaban: CPembahasan:Langkah 1: Urutkan data dari yang terkecil ke terbesar:65, 70, 70, 75, 80, 80, 85, 85, 90, 95Langkah 2: Karena banyak data genap (n = 10), nilai median berada di antara datum ke-(10/2) dan datum ke-(10/2 + 1), yaitu datum ke-5 dan datum ke-6.Datum ke-5 = 80Datum ke-6 = 80Median = (80 + 80) / 2 = 160 / 2 = 80.Jadi, median nilai kuis matematika adalah 80 (Opsi C).', NULL, NULL),
(1028, 1028, 'Kunci Jawaban: CPembahasan:Rata-rata (mean) dihitung dengan membagi jumlah seluruh nilai dengan banyak data:Mean = (80 + 84 + 86 + 90 + 90) / 5Mean = 430 / 5 = 86.Jadi, nilai rata-rata tugas IPA Dania adalah 86 (Opsi C).', NULL, NULL),
(1029, 1029, 'Kunci Jawaban: CPembahasan:Jangkauan (range) adalah selisih antara nilai datum tertinggi (maksimum) dan datum terendah (minimum).- Nilai maksimum = 29 °C- Nilai minimum = 23 °CJangkauan = Nilai Maksimum - Nilai Minimum = 29 - 23 = 6 °C.Jadi, jangkauan temperatur laboratorium komputer adalah 6 °C (Opsi C).', NULL, NULL),
(1030, 1030, 'Kunci Jawaban: BPembahasan:Mari kita urutkan jumlah anggota ekstrakurikuler dari yang terbanyak ke paling sedikit:1. Pramuka = 45 orang (terbanyak pertama)2. Futsal = 40 orang (terbanyak kedua)3. Basket = 36 orang (terbanyak ketiga)4. PMR = 32 orang5. Paskibra = 28 orangJadi, ekstrakurikuler dengan jumlah anggota terbanyak kedua adalah Futsal (Opsi B).', NULL, NULL),
(1031, 1031, 'Kunci Jawaban: CPembahasan:Banyaknya siswa yang berjalan kaki dihitung dengan mengalikan persentase terhadap total seluruh siswa:Banyak siswa = 25% × 160 orangBanyak siswa = (25 / 100) × 160 = 0,25 × 160 = 40 orang.Jadi, ada 40 orang siswa yang berjalan kaki menuju sekolah (Opsi C).', NULL, NULL),
(1032, 1032, 'Kunci Jawaban: BPembahasan:Perhatikan kata kunci: \'di atas KKM\', artinya nilai yang dicari adalah nilai yang lebih besar dari 75 (nilai 75 tidak dihitung karena sama dengan KKM, bukan di atas KKM).Nilai di atas 75 adalah nilai 80, 90, dan 100.- Siswa dengan nilai 80 = 10 orang- Siswa dengan nilai 90 = 7 orang- Siswa dengan nilai 100 = 5 orangJumlah siswa = 10 + 7 + 5 = 22 orang.Jadi, banyak siswa yang nilainya di atas KKM adalah 22 orang (Opsi B).', NULL, NULL),
(1033, 1033, 'Kunci Jawaban: BPembahasan:Mari kita hitung perubahan penjualan antarhari yang berurutan:- Senin ke Selasa: 75 - 50 = 25 (mengalami kenaikan)- Selasa ke Rabu: 45 - 75 = -30 (mengalami penurunan sebesar 30 buku)- Rabu ke Kamis: 60 - 45 = 15 (mengalami kenaikan)- Kamis ke Jumat: 40 - 60 = -20 (mengalami penurunan sebesar 20 buku)Penurunan terbesar terjadi dari hari Selasa ke hari Rabu, yaitu berkurang sebanyak 30 buku (Opsi B).', NULL, NULL),
(1034, 1034, 'Kunci Jawaban: CPembahasan:- Data kuantitatif adalah data berbentuk angka numerik.  * Diskrit: diperoleh dari hasil menghitung/membilang berupa bilangan bulat utuh, seperti banyaknya saudara kandung (0, 1, 2, 3, dst).  * Kontinu: diperoleh dari hasil mengukur yang nilainya bisa berupa desimal, seperti berat badan (contoh: 45,5 kg).- Data kualitatif adalah data berupa kategori/sifat (seperti warna tas dan tingkat kepuasan).Jadi, data kuantitatif diskrit adalah nomor (3) (Opsi C).', NULL, NULL),
(1035, 1035, 'Kunci Jawaban: BPembahasan:Langkah 1: Kalikan setiap nilai dengan frekuensinya:- 6 × 2 = 12- 7 × 3 = 21- 8 × 3 = 24- 9 × 2 = 18Langkah 2: Jumlahkan seluruh perkalian nilai (Sigma f.x):Total nilai = 12 + 21 + 24 + 18 = 75Langkah 3: Hitung total frekuensi (Sigma f):Total siswa = 2 + 3 + 3 + 2 = 10Langkah 4: Hitung rata-rata:Rata-rata = 75 / 10 = 7,5.Jadi, nilai rata-rata kuis adalah 7,5 (Opsi B).', NULL, NULL),
(1036, 1036, 'Kunci Jawaban: BPembahasan:Banyak data (n) = 11.Median (Q2) membagi data menjadi dua kelompok yang sama banyak:Letak Q2 = datum ke-(11 + 1)/2 = datum ke-6, yaitu 155 cm.Kelompok data di sebelah kiri median (separuh bawah) terdiri dari 5 data:145, 148, 150, 152, 153Kuartil bawah (Q1) adalah nilai tengah dari kelompok data separuh bawah tersebut:Letak Q1 = datum ke-(5 + 1)/2 = datum ke-3 dari kelompok bawah, yaitu 150 cm.Jadi, kuartil bawah (Q1) adalah 150 cm (Opsi B).', NULL, NULL),
(1037, 1037, 'Kunci Jawaban: CPembahasan:Median (Q2) adalah datum ke-6 = 155 cm.Kelompok data di sebelah kanan median (separuh atas) terdiri dari 5 data:156, 158, 160, 162, 165Kuartil atas (Q3) adalah nilai tengah dari kelompok data separuh atas tersebut:Letak Q3 = datum ke-3 dari kelompok atas, yaitu 160 cm.Jadi, kuartil atas (Q3) adalah 160 cm (Opsi C).', NULL, NULL),
(1038, 1038, 'Kunci Jawaban: BPembahasan:Jangkauan interkuartil (IQR) adalah selisih antara kuartil atas (Q3) dan kuartil bawah (Q1):Rumus: IQR = Q3 - Q1IQR = 48 - 32 = 16 kg.Jadi, jangkauan interkuartil data tersebut adalah 16 kg (Opsi B).', NULL, NULL),
(1039, 1039, 'Kunci Jawaban: CPembahasan:Pada Pekan 2 terdapat 4 simbol [*].Karena 1 simbol [*] mewakili 6 kg, maka:Hasil panen Pekan 2 = 4 × 6 kg = 24 kg.Jadi, panen pakcoy pada Pekan 2 adalah 24 kg (Opsi C).', NULL, NULL),
(1040, 1040, 'Kunci Jawaban: DPembahasan:Modus adalah datum yang memiliki frekuensi terbesar.Perhatikan frekuensi terbanyak pada tabel:- Frekuensi terbesar adalah 21 siswa.- Nilai ukuran lingkar kepala yang memiliki frekuensi 21 tersebut adalah 56 cm.(Catatan: 21 adalah nilai frekuensinya, sedangkan modusnya adalah nilai datanya yaitu 56 cm).Jadi, modusnya adalah 56 cm (Opsi D).', NULL, NULL),
(1041, 1041, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung rata-rata (mean) data:Jumlah nilai = 6 + 7 + 7 + 8 + 8 + 8 + 9 + 7 = 60Banyak siswa = 8Rata-rata = 60 / 8 = 7,5Langkah 2: Cari siswa dengan nilai di bawah rata-rata (< 7,5):Nilai yang kurang dari 7,5 adalah nilai 6 dan 7.- Nilai 6: ada 1 siswa- Nilai 7: ada 3 siswaTotal siswa yang nilainya di bawah rata-rata = 1 + 3 = 4 siswa.Jadi, ada 4 siswa yang nilainya di bawah rata-rata (Opsi C).', NULL, NULL),
(1042, 1042, 'Kunci Jawaban: CPembahasan:Langkah 1: Tentukan total nilai yang dibutuhkan untuk 5 kali tes:Total nilai 5 tes = 5 × 84 = 420Langkah 2: Jumlahkan nilai dari 4 tes yang telah diperoleh:Total 4 tes = 76 + 82 + 84 + 88 = 330Langkah 3: Hitung nilai tes kelima:Nilai tes ke-5 = Total nilai 5 tes - Total nilai 4 tesNilai tes ke-5 = 420 - 330 = 90.Jadi, Rian harus memperoleh nilai 90 pada tes kelima (Opsi C).', NULL, NULL),
(1043, 1043, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung total nilai siswa putra:Total nilai putra = 15 × 76 = 1.140Langkah 2: Hitung total nilai siswa putri:Total nilai putri = 25 × 84 = 2.100Langkah 3: Hitung jumlah seluruh siswa:Total siswa = 15 + 25 = 40 siswaLangkah 4: Hitung rata-rata gabungan:Rata-rata gabungan = (1.140 + 2.100) / 40Rata-rata gabungan = 3.240 / 40 = 81.Jadi, nilai rata-rata gabungan seluruh siswa adalah 81 (Opsi C).', NULL, NULL),
(1044, 1044, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung total tinggi 19 siswa mula-mula:Total mula-mula = 19 × 158 = 3.002 cmLangkah 2: Hitung total tinggi setelah 1 siswa baru bergabung (total menjadi 20 siswa):Total baru = 20 × 158,5 = 3.170 cmLangkah 3: Hitung tinggi siswa baru:Tinggi siswa baru = Total baru - Total mula-mulaTinggi siswa baru = 3.170 - 3.002 = 168 cm.Jadi, tinggi badan siswa baru tersebut adalah 168 cm (Opsi C).', NULL, NULL),
(1045, 1045, 'Kunci Jawaban: BPembahasan:Langkah 1: Hitung jumlah nilai mula-mula dari 20 siswa:Total nilai 20 siswa = 20 × 78 = 1.560Langkah 2: Hitung jumlah nilai 2 siswa yang dipisahkan:Total nilai 2 siswa = 58 + 62 = 120Langkah 3: Hitung sisa total nilai untuk 18 siswa:Total nilai 18 siswa = 1.560 - 120 = 1.440Langkah 4: Hitung nilai rata-rata 18 siswa tersisa:Rata-rata baru = 1.440 / 18 = 80.Jadi, rata-rata nilai dari 18 siswa yang tersisa adalah 80 (Opsi B).', NULL, NULL),
(1046, 1046, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung selisih sudut pusat antara Pramuka dan Musik:Selisih sudut = Sudut Pramuka - Sudut Musik = 120° - 60° = 60°Langkah 2: Satu lingkaran penuh bernilai 360° yang mewakili total 360 siswa:Selisih siswa = (Selisih sudut / 360°) × Total SiswaSelisih siswa = (60° / 360°) × 360 orang = 60 orang.(Atau: Siswa Pramuka = (120/360) × 360 = 120 orang; Siswa Musik = (60/360) × 360 = 60 orang; Selisih = 120 - 60 = 60 orang).Jadi, selisihnya adalah 60 orang (Opsi C).', NULL, NULL),
(1047, 1047, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung persentase peminat cabang renang (total satu lingkaran = 100%):Persentase Renang = 100% - (35% + 25% + 20%)Persentase Renang = 100% - 80% = 20%Langkah 2: Hitung banyak siswa peminat renang dari total 200 siswa:Banyak siswa = 20% × 200 orangBanyak siswa = (20 / 100) × 200 = 0,20 × 200 = 40 orang.Jadi, banyak siswa peminat renang adalah 40 orang (Opsi C).', NULL, NULL),
(1048, 1048, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung total frekuensi (n):n = 5 + 9 + 12 + 8 + 6 = 40 data (genap)Langkah 2: Letak median berada di antara datum ke-(40/2) dan datum ke-(40/2 + 1), yaitu datum ke-20 dan ke-21.Langkah 3: Hitung frekuensi kumulatif untuk menemukan letak datum ke-20 dan ke-21:- Nilai 65: datum ke-1 sampai ke-5- Nilai 70: datum ke-6 sampai ke-(5 + 9) = ke-14- Nilai 75: datum ke-15 sampai ke-(14 + 12) = ke-26Karena datum ke-20 dan datum ke-21 keduanya berada pada rentang nilai 75, maka:Median = (75 + 75) / 2 = 75.Jadi, median dari data tersebut adalah 75 (Opsi C).', NULL, NULL),
(1049, 1049, 'Kunci Jawaban: BPembahasan:Langkah 1: Hitung total pengeluaran kelas 7A:Total 7A = 30 × Rp20.000,00 = Rp600.000,00Langkah 2: Hitung total pengeluaran kelas 7B:Total 7B = 20 × Rp25.000,00 = Rp500.000,00Langkah 3: Hitung total seluruh pengeluaran dan jumlah seluruh siswa:Total gabungan = Rp600.000,00 + Rp500.000,00 = Rp1.100.000,00Jumlah seluruh siswa = 30 + 20 = 50 siswaLangkah 4: Hitung rata-rata gabungan:Rata-rata = Rp1.100.000,00 / 50 = Rp22.000,00.Jadi, rata-rata pengeluaran seluruh siswa adalah Rp22.000,00 (Opsi B).', NULL, NULL),
(1050, 1050, 'Kunci Jawaban: CPembahasan:Langkah 1: Total data (n) = 20.Median membagi 20 data menjadi separuh bawah (10 data pertama, yaitu datum ke-1 s.d ke-10) dan separuh atas (10 data terakhir, yaitu datum ke-11 s.d ke-20).Langkah 2: Kuartil bawah (Q1) adalah nilai tengah dari 10 data pertama, yaitu rata-rata antara datum ke-5 dan datum ke-6.Langkah 3: Susunan frekuensi kumulatif data:- Skor 10: datum ke-1 s.d ke-3- Skor 20: datum ke-4 s.d ke-8Karena datum ke-5 dan ke-6 sama-sama bernilai 20, maka:Q1 = (20 + 20) / 2 = 20.Jadi, kuartil bawahnya adalah 20 (Opsi C).', NULL, NULL),
(1051, 1051, 'Kunci Jawaban: DPembahasan:Mari hitung selisih suhu (nilai mutlak) antara kedua kota pada tiap hari:- Senin: |28 - 32| = 4 °C- Selasa: |30 - 31| = 1 °C- Rabu: |33 - 29| = 4 °C- Kamis: |29 - 34| = 5 °CSelisih suhu terbesar adalah 5 °C yang terjadi pada hari Kamis.Jadi, selisih suhu terbesar terjadi pada hari Kamis (Opsi D).', NULL, NULL),
(1052, 1052, 'Kunci Jawaban: BPembahasan:Modus adalah kategori yang memiliki frekuensi penjualan tertinggi.Berdasarkan data penjualan:- S = 18 potong- M = 42 potong- L = 56 potong (tertinggi)- XL = 24 potong- XXL = 10 potongUkuran L terjual paling banyak (56 potong). Oleh karena itu, ukuran yang harus dipesan dalam jumlah terbanyak sesuai modus permintaan adalah ukuran L (Opsi B).', NULL, NULL),
(1053, 1053, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung total nilai 8 siswa mula-mula:Total 8 siswa = 8 × 75 = 600Langkah 2: Hitung total nilai 10 siswa setelah susulan:Total 10 siswa = 10 × 77 = 770Langkah 3: Hitung jumlah nilai 2 siswa susulan:Total 2 siswa = 770 - 600 = 170Langkah 4: Tentukan nilai masing-masing berdasarkan perbandingan 8 : 9:Total bagian perbandingan = 8 + 9 = 17 bagianNilai 1 bagian = 170 / 17 = 10Nilai siswa pertama = 8 × 10 = 80Nilai siswa kedua (nilai tertinggi) = 9 × 10 = 90.Jadi, nilai tertinggi di antara kedua siswa susulan adalah 90 (Opsi C).', NULL, NULL),
(1054, 1054, 'Kunci Jawaban: BPembahasan:Mari kita pilah data yang berada pada rentang 30 sampai 39 menit (inklusif):Data yang memenuhi adalah: 30, 32, 35, dan 38.Ada sebanyak 4 siswa yang waktu membacanya berada di antara 30 dan 39 menit.Jadi, banyak siswa pada interval tersebut adalah 4 orang (Opsi B).', NULL, NULL),
(1055, 1055, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung total nilai seluruh peserta (Sigma f.x):(60 × 3) + (70 × 5) + (80 × 7) + (90 × 4) + (100 × 1)= 180 + 350 + 560 + 360 + 100 = 1.550Langkah 2: Hitung nilai rata-rata:Rata-rata = 1.550 / 20 = 77,5Langkah 3: Syarat lolos adalah nilai minimal sama dengan rata-rata (>= 77,5), yaitu siswa bernilai 80, 90, dan 100:Banyak siswa lolos = 7 + 4 + 1 = 12 orangLangkah 4: Hitung persentase kelulusan:Persentase = (12 / 20) × 100% = 60%.Jadi, persentase peserta yang lolos adalah 60% (Opsi C).', NULL, NULL),
(1056, 1056, 'Kunci Jawaban: BPembahasan:Langkah 1: Hitung selisih penambahan nilai akibat kesalahan pencatatan:Selisih = Nilai sebenarnya - Nilai salah = 90 - 65 = +25 poinLangkah 2: Hitung pertambahan rata-rata untuk 25 siswa:Kenaikan rata-rata = +25 / 25 siswa = +1 poinLangkah 3: Hitung rata-rata baru yang benar:Rata-rata baru = 80 + 1 = 81,0.(Atau: Total awal = 25 × 80 = 2.000; Total baru = 2.000 + 25 = 2.025; Rata-rata baru = 2.025 / 25 = 81).Jadi, rata-rata nilai setelah dikoreksi adalah 81,0 (Opsi B).', NULL, NULL),
(1057, 1057, 'Kunci Jawaban: BPembahasan:Langkah 1: Gabungkan seluruh nilai dari kedua kelompok dan urutkan dari terkecil ke terbesar:60, 65, 70, 75, 75, 80, 80, 85, 85, 90Langkah 2: Karena total data genap (n = 10), median adalah nilai rata-rata datum ke-5 dan ke-6:Datum ke-5 = 75Datum ke-6 = 80Median gabungan = (75 + 80) / 2 = 155 / 2 = 77,5.Jadi, median nilai gabungan adalah 77,5 (Opsi B).', NULL, NULL),
(1058, 1058, 'Kunci Jawaban: BPembahasan:Langkah 1: Hitung besar kenaikan volume penjualan:Kenaikan = 500 botol - 400 botol = 100 botolLangkah 2: Hitung persentase kenaikan relatif terhadap penjualan awal (bulan Januari):Persentase kenaikan = (Besar Kenaikan / Penjualan Awal) × 100%Persentase kenaikan = (100 / 400) × 100% = 0,25 × 100% = 25%.(Catatan: Pengecoh 20% terjadi jika keliru membaginya dengan penjualan akhir 500 botol).Jadi, persentase kenaikan penjualannya adalah 25% (Opsi B).', NULL, NULL),
(1059, 1059, 'Kunci Jawaban: CPembahasan:Nilai akhir dihitung dengan mengalikan masing-masing nilai dengan persentase bobotnya:- Tugas: 20% × 85 = 0,20 × 85 = 17,0- Praktik: 30% × 90 = 0,30 × 90 = 27,0- UTS: 20% × 75 = 0,20 × 75 = 15,0- UAS: 30% × 80 = 0,30 × 80 = 24,0Nilai akhir = 17,0 + 27,0 + 15,0 + 24,0 = 83,0.Jadi, nilai akhir mata pelajaran prakarya Danu adalah 83,0 (Opsi C).', NULL, NULL),
(1060, 1060, 'Kunci Jawaban: BPembahasan:Langkah 1: Tentukan nilai kuartil:- Banyak data (n) = 9.- Median (Q2) = datum ke-5 = 3,2 m.- Kelompok bawah (4 data): 2,4 ; 2,6 ; 2,8 ; 3,0 -> Q1 = (2,6 + 2,8) / 2 = 2,7 m.- Kelompok atas (4 data): 3,4 ; 3,6 ; 3,8 ; 4,0 -> Q3 = (3,6 + 3,8) / 2 = 3,7 m.Langkah 2: Hitung jangkauan interkuartil (IQR):IQR = Q3 - Q1 = 3,7 - 2,7 = 1,0 m.Langkah 3: Hitung simpangan kuartil (Qd = 1/2 × IQR):Qd = 1/2 × 1,0 m = 0,50 m.Jadi, simpangan kuartil data tersebut adalah 0,50 m (Opsi B).', NULL, NULL),
(1061, 1061, 'Kunci Jawaban: CPembahasan:Misalkan:- Banyak siswa putri = P- Banyak siswa putra = 40 - PLangkah 1: Gunakan rumus rata-rata gabungan:(Nilai Rata-rata Putri × P) + (Nilai Rata-rata Putra × (40 - P)) = Rata-rata Kelas × 4082P + 72(40 - P) = 78 × 4082P + 2.880 - 72P = 3.12010P = 3.120 - 2.88010P = 240P = 240 / 10 = 24 orang.Jadi, banyak siswa putri di kelas tersebut adalah 24 orang (Opsi C).', NULL, NULL),
(1062, 1062, 'Kunci Jawaban: BPembahasan:Langkah 1: Analisis data:Data terurut: 15, 18, 20, 22, 24, 25, 140.Perhatikan angka 140, nilai ini jauh lebih besar dibandingkan datum lainnya sehingga disebut sebagai pencilan ekstrim (outlier).Langkah 2: Hitung mean dan median:- Mean = (15 + 18 + 20 + 22 + 24 + 25 + 140) / 7 = 264 / 7 ≈ 37,7 buku.Nilai mean 37,7 ini tidak realistis karena 6 dari 7 kelas sebenarnya menyumbang paling banyak hanya 25 buku.- Median = datum ke-4 = 22 buku.Langkah 3: Kesimpulan:Median jauh lebih tahan (resisten) terhadap nilai ekstrim (outlier) dibandingkan mean. Oleh karena itu, median lebih objektif dan representatif menggambarkan kondisi umum donasi buku kelas (Opsi B).', NULL, NULL),
(1063, 1063, 'Kunci Jawaban: BPembahasan:Dalam kaidah literasi statistika:- Diagram batang yang sumbu vertikalnya (frekuensi) dipotong atau tidak dimulai dari angka 0 dikenal sebagai grafik yang menyesatkan (misleading/truncated graph).- Kenaikan riil dari 120 ke 130 botol adalah: ((130 - 120) / 120) × 100% ≈ 8,33%.- Namun karena sumbu Y dimulai dari 115, tinggi visual batang Mei adalah (120 - 115) = 5 satuan, sedangkan batang Juni adalah (130 - 115) = 15 satuan (tampak 3 kali lebih tinggi seolah naik 200%). Hal ini menimbulkan ilusi visual yang memanipulasi persepsi pembaca.Jadi, evaluasi yang tepat adalah Opsi B.', NULL, NULL),
(1064, 1064, 'Kunci Jawaban: CPembahasan:Langkah 1: Tentukan total nilai minimum yang dibutuhkan untuk 6 ulangan dengan rata-rata minimal 80:Total nilai minimum = 6 × 80 = 480 poinLangkah 2: Jumlahkan nilai dari 4 ulangan awal:Total 4 ulangan = 72 + 78 + 80 + 82 = 312 poinLangkah 3: Tambahkan nilai ulangan kelima (88 poin):Total 5 ulangan = 312 + 88 = 400 poinLangkah 4: Hitung nilai minimum pada ulangan keenam (terakhir):Nilai ulangan ke-6 = 480 - 400 = 80 poin.Jadi, Dita harus memperoleh nilai minimal 80 pada ulangan keenam (Opsi C).', NULL, NULL),
(1065, 1065, 'Kunci Jawaban: APembahasan:Berdasarkan prinsip transformasi linear data Y = aX + b:1. Ukuran pemusatan (seperti Rata-rata) dipengaruhi oleh perkalian konstanta \'a\' dan penambahan konstanta \'b\':Rata-rata baru = (Rata-rata lama × 1,2) + 5 = (60 × 1,2) + 5 = 72 + 5 = 77.2. Ukuran penyebaran (seperti Jangkauan/Range) HANYA dipengaruhi oleh faktor pengali \'a\', dan TIDAK terpengaruh oleh penambahan konstanta \'b\' (karena penambahan konstanta menggeser nilai maksimum dan minimum sebesar nilai yang sama, sehingga selisihnya tetap):Jangkauan baru = Jangkauan lama × 1,2 = 30 × 1,2 = 36.Jadi, rata-rata baru = 77 dan jangkauan baru = 36 (Opsi A).', NULL, NULL),
(1066, 1066, 'Kunci Jawaban: BPembahasan:Langkah 1: Bandingkan ukuran pemusatan dan ukuran penyebaran kedua atlet:- Kedua atlet memiliki rata-rata performa sama (85 poin).- Ukuran penyebaran (Jangkauan dan Simpangan Kuartil) mengukur variasi/dispersi kestabilan hasil tembakan.Langkah 2: Analisis stabilitas:- Atlet A memiliki jangkauan 6 dan simpangan kuartil 1,5 (sangat kecil), artinya tembakan Atlet A selalu konsisten mendekati angka 85 pada setiap sesi latihan.- Atlet B memiliki jangkauan 22 dan simpangan kuartil 5,5 (sangat besar), artinya tembakan Atlet B fluktuatif (kadang sangat tinggi, kadang anjlok sangat rendah).Langkah 3: Kesimpulan:Dalam kompetisi resmi, kestabilan performa (konsistensi) sangat diutamakan untuk meminimalkan risiko kegagalan fatal. Oleh karena itu, Atlet A lebih layak dipilih (Opsi B).', NULL, NULL),
(1067, 1067, 'Kunci Jawaban: Pernyataan 1 dan Pernyataan 2 BenarPembahasan:- Analisis Pernyataan 1 (BENAR): Rata-rata (mean) adalah representasi agregat kelompok. Rata-rata kelas 82 tidak menjamin seluruh siswa berada di atas 75.- Analisis Pernyataan 2 (BENAR): Keberadaan nilai ekstrim tinggi pada beberapa siswa dapat mendongkrak rata-rata ke atas meskipun ada siswa lain yang memperoleh nilai 50 atau 60 (di bawah KKM).- Analisis Pernyataan 3 (SALAH): Nilai rata-rata tidak selalu sama dengan nilai setiap siswa dalam populasi kelas.- Analisis Pernyataan 4 (SALAH): Nilai rata-rata tidak menjadi pembatas mutlak bagi nilai terendah individu.Jadi, centanglah Pernyataan 1 dan Pernyataan 2.', NULL, NULL),
(1068, 1068, 'Kunci Jawaban: Pernyataan 1 dan Pernyataan 2 BenarPembahasan:Perhitungan kuantitas masing-masing kantin:1. Kantin Sehat (300 transaksi): Jajanan bergizi = 80% × 300 = 240; Makanan kemasan = 20% × 300 = 60.2. Kantin Pojok (500 transaksi): Jajanan bergizi = 40% × 500 = 200; Makanan kemasan = 60% × 500 = 300.- Analisis Pernyataan 1 (BENAR): 240 transaksi (Kantin Sehat) > 200 transaksi (Kantin Pojok).- Analisis Pernyataan 2 (BENAR): Total bergizi = 240 + 200 = 440. Total seluruh transaksi = 300 + 500 = 800. Persentase = (440 / 800) × 100% = 55%.- Analisis Pernyataan 3 (SALAH): Total kemasan = 60 + 300 = 360 transaksi (bukan 500).- Analisis Pernyataan 4 (SALAH): Jajanan bergizi di Kantin Pojok adalah 200 transaksi (300 adalah makanan kemasan).Jadi, centanglah Pernyataan 1 dan Pernyataan 2.', NULL, NULL),
(1069, 1069, 'Kunci Jawaban: BPembahasan:Langkah 1: Tentukan nilai x menggunakan persamaan rata-rata:Total Frekuensi = 4 + x + 6 + 2 = 12 + xTotal Nilai = (7 × 4) + (8 × x) + (9 × 6) + (10 × 2) = 28 + 8x + 54 + 20 = 102 + 8xRata-rata = 8,25:(102 + 8x) / (12 + x) = 8,25102 + 8x = 8,25(12 + x)102 + 8x = 99 + 8,25x102 - 99 = 8,25x - 8x3 = 0,25x  -->  x = 3 / 0,25 = 12.Langkah 2: Tentukan Median:Total data = 12 + 12 = 24 (genap).Median terletak antara datum ke-12 dan datum ke-13.- Nilai 7: datum ke-1 s.d ke-4- Nilai 8: datum ke-5 s.d ke-(4 + 12) = ke-16Karena datum ke-12 dan datum ke-13 sama-sama bernilai 8, maka:Median = (8 + 8) / 2 = 8.Jadi, nilai x = 12 dan Median = 8 (Opsi B).', NULL, NULL),
(1070, 1070, 'Kunci Jawaban: BPembahasan:Langkah 1: Pahami definisi statistika:- Modus adalah nilai dengan frekuensi kemunculan terbanyak relatif dibanding nilai lainnya (dalam hal ini angka 1 muncul 3 kali, angka lain 1 kali).- Namun, \'modus\' tidak otomatis berarti \'mayoritas\' (> 50%).Langkah 2: Periksa proporsi data:- Siswa yang belajar 1 jam = 3 orang dari 9 orang = 33,3%.- Siswa yang belajar lebih dari 1 jam (4 s.d 9 jam) = 6 orang dari 9 orang = 66,7% (dua pertiga siswa).Langkah 3: Kesimpulan:Menyimpulkan bahwa sebagian besar siswa belajar 1 jam adalah bentuk sesat pikir generalisasi data yang keliru (Opsi B).', NULL, NULL),
(1071, 1071, 'Kunci Jawaban: CPembahasan:Langkah 1: Susun seluruh data (9 bilangan) dari terkecil ke terbesar:5, 12, 14, 15, 18, 20, 22, 25, 40Langkah 2: Hitung letak median baru (n = 9, ganjil):Letak median = datum ke-(9 + 1)/2 = datum ke-5.Langkah 3: Periksa datum ke-5:Datum ke-1: 5Datum ke-2: 12Datum ke-3: 14Datum ke-4: 15Datum ke-5: 18Median baru tetaplah 18.Langkah 4: Konsep penalaran: Jika kita menambahkan 2 data baru di mana satu data terletak di sebelah kiri median (< 18) dan satu data terletak di sebelah kanan median (> 18), maka posisi keseimbangan nilai tengah (median) tidak akan bergeser. Jadi, median tetap bernilai 18 (Opsi C).', NULL, NULL),
(1072, 1072, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung kuota peserta yang berhak lolos ke semifinal:Kuota lolos = 20% × 200 orang = 40 orang peringkat teratasLangkah 2: Akumulasikan frekuensi mulai dari kelompok skor tertinggi (dari atas ke bawah):- Rentang skor 90 - 100: ada 20 orang (peringkat 1 s.d ke-20)- Rentang skor 80 - 89: ada 50 orang (peringkat 21 s.d ke-70)Langkah 3: Evaluasi kuota:Kuota 40 orang terpenuhi oleh 20 orang di kelompok 90-100 dan 20 orang teratas di kelompok 80-89.Dengan demikian, batas ambang bawah peserta yang lolos berada di dalam kelompok rentang skor 80 - 89 (Opsi C).', NULL, NULL),
(1073, 1073, 'Kunci Jawaban: CPembahasan:Langkah 1: Hitung IQR awal dalam satuan kilogram (kg):IQR awal = Q3 - Q1 = 20 kg - 12 kg = 8 kgLangkah 2: Terapkan prinsip perkalian konstanta k = 10 pada ukuran penyebaran data:Ketika seluruh data dikalikan konstanta k, nilai kuartil baru akan menjadi:- Q1 baru = 12 × 10 = 120 ons- Q3 baru = 20 × 10 = 200 onsLangkah 3: Hitung IQR baru dalam satuan ons:IQR baru = Q3 baru - Q1 baru = 200 ons - 120 ons = 80 ons.(Atau langsung: IQR baru = IQR awal × 10 = 8 kg × 10 = 80 ons).Jadi, jangkauan interkuartil yang baru adalah 80 ons (Opsi C).', NULL, NULL),
(1074, 1074, 'Kunci Jawaban: APembahasan:Langkah 1: Hitung rata-rata biasa dari seluruh 5 juri:Jumlah skor = 78 + 84 + 85 + 87 + 98 = 432Rata-rata biasa = 432 / 5 = 86,40 poinLangkah 2: Terapkan sistem trimmed mean:- Skor terendah = 78 (dieliminasi)- Skor tertinggi = 98 (dieliminasi)Skor yang tersisa (3 juri) = 84, 85, 87Trimmed mean = (84 + 85 + 87) / 3 = 256 / 3 ≈ 85,33 poinLangkah 3: Hitung selisihnya:Selisih = 86,40 - 85,33 ≈ 1,07 poinLangkah 4: Analisis tujuan:Penerapan trimmed mean bertujuan menghindari pengaruh skor pencilan (outlier) akibat subjektivitas juri yang terlalu ekstrim (Opsi A).', NULL, NULL),
(1075, 1075, 'Kunci Jawaban: Pernyataan 1 dan Pernyataan 2 BenarPembahasan:- Analisis Pernyataan 1 (BENAR): Median kedua kelas sama-sama bernilai 75.- Analisis Pernyataan 2 (BENAR): IQR Kelas 8B = 80 - 70 = 10; IQR Kelas 8A = 85 - 65 = 20. Nilai IQR yang lebih kecil menunjukkan variasi 50% data di sekitar median lebih rapat (homogen).- Analisis Pernyataan 3 (SALAH): Range 8A = 95 - 50 = 45; Range 8B = 90 - 60 = 30. Range Kelas 8A justru lebih besar.- Analisis Pernyataan 4 (SALAH): Q3 Kelas 8A (85) lebih tinggi daripada Q3 Kelas 8B (80).Jadi, centanglah Pernyataan 1 dan Pernyataan 2.', NULL, NULL),
(1076, 1076, 'Kunci Jawaban: BPembahasan:Langkah 1: Hitung total nilai seluruh 6 siswa:Total nilai = 60 + 64 + 70 + 76 + 80 + 90 = 440Langkah 2: Karena dibagi menjadi dua kelompok dengan rata-rata yang sama dan banyak anggota sama (3 siswa), maka total nilai masing-masing kelompok haruslah sama:Total per kelompok = 440 / 2 = 220 poinLangkah 3: Cari kombinasi 3 nilai yang jika dijumlahkan menghasilkan tepat 220:- Kombinasi: 60 + 70 + 90 = 220 poin.- Kelompok pasangannya adalah sisa nilai: 64 + 76 + 80 = 220 poin.Kedua kelompok ini sama-sama memiliki total nilai 220 dan rata-rata 220 / 3 = 73,33.Jadi, kelompok yang terbentuk adalah siswa dengan nilai 60, 70, dan 90 (Opsi B).', NULL, NULL),
(1077, 1077, 'Kunci Jawaban: APembahasan:Analisis pola sebaran data (diagram pencar):- Saat durasi tidur 5,0 jam, skor kuis adalah 60.- Saat durasi tidur meningkat menjadi 7,0 jam, skor kuis meningkat ke 80.- Saat durasi tidur 8,5 jam, skor kuis mencapai 92.Secara konsisten, peningkatan nilai pada sumbu X (durasi tidur) diikuti oleh peningkatan nilai pada sumbu Y (skor kuis). Pola titik-titik data membentuk garis tren yang naik dari kiri bawah ke kanan atas.Hal ini menunjukkan adanya korelasi positif yang kuat antara kedua variabel tersebut (Opsi A).', NULL, NULL),
(1078, 1078, 'Kunci Jawaban: Pernyataan 1 dan Pernyataan 2 BenarPembahasan:- Analisis Pernyataan 1 (BENAR): Pengambilan sampel di perpustakaan secara otomatis menyaring kelompok siswa yang memang gemar membaca, sehingga tercipta bias seleksi.- Analisis Pernyataan 2 (BENAR): Karena sampel tidak representatif, hasil temuan tidak boleh digeneralisasikan ke seluruh siswa sekolah.- Analisis Pernyataan 3 (SALAH): Pengambilan sampel ini termasuk convenience sampling, bukan simple random sampling.- Analisis Pernyataan 4 (SALAH): Siswa yang berada di lapangan atau kantin tidak terwakili sama sekali.Jadi, centanglah Pernyataan 1 dan Pernyataan 2.', NULL, NULL),
(1079, 1079, 'Kunci Jawaban: DPembahasan:Langkah 1: Hitung total poin dari 10 pertandingan awal:Total poin awal = 10 × 14 = 140 poinLangkah 2: Hitung target total poin setelah 14 pertandingan (10 + 4 pertandingan) dengan rata-rata 16 poin:Total target 14 pertandingan = 14 × 16 = 224 poinLangkah 3: Hitung jumlah poin yang harus dicetak pada 4 pertandingan tersisa:Poin yang dibutuhkan = 224 - 140 = 84 poinLangkah 4: Hitung rata-rata poin per pertandingan pada 4 laga tersebut:Rata-rata = 84 poin / 4 pertandingan = 21 poin per pertandingan.Jadi, ia harus mencetak rata-rata 21 poin per pertandingan (Opsi D).', NULL, NULL),
(1080, 1080, 'Kunci Jawaban: BPembahasan:Pada distribusi data yang condong ke kanan (positively skewed / kemiringan positif):1. Modus berada di puncak frekuensi tertinggi di sebelah kiri (nilai yang paling banyak diperoleh siswa, yaitu di rentang 45-60).2. Median membagi populasi menjadi dua sama banyak, posisinya berada di tengah.3. Mean (rata-rata) sangat sensitif terhadap nilai pencilan tinggi (nilai 100), sehingga nilainya akan tertarik ke arah kanan (menjadi lebih besar).Dengan demikian, urutan nilainya dari yang terkecil ke terbesar adalah:Modus < Median < Mean (Opsi B).', NULL, NULL),
(1081, 1081, 'Kunci Jawaban: Pernyataan 1 dan Pernyataan 2 BenarPembahasan:- Analisis Pernyataan 1 (BENAR): Siswa yang belum memenuhi standar hidrasi = 45% + 35% = 80% (sebanyak 240 siswa).- Analisis Pernyataan 2 (BENAR): Rekomendasi penyediaan air minum gratis dan edukasi hidrasi sangat relevan karena mayoritas mutlak siswa (80%) mengalami kekurangan asupan cairan standar.- Analisis Pernyataan 3 (SALAH): Siswa yang memenuhi standar hidrasi hanya 20% (bukan mayoritas).- Analisis Pernyataan 4 (SALAH): Siswa kategori < 1,0 liter adalah 135 orang (lebih dari 100 orang).Jadi, centanglah Pernyataan 1 dan Pernyataan 2.', NULL, NULL),
(1082, 1082, 'Jawaban: BCara Pengerjaan/Konsep:1. Pahami definisi dari istilah dalam peluang.2. Titik sampel: setiap satu anggota tunggal dari hasil percobaan.3. Ruang sampel: keseluruhan/himpunan dari semua titik sampel yang mungkin terjadi.4. Karena pertanyaan menanyakan "himpunan dari semua hasil", maka istilah yang tepat adalah Ruang Sampel.', NULL, NULL),
(1083, 1083, 'Jawaban: CCara Pengerjaan:1. Identifikasi bentuk dadu standar, yaitu sebuah kubus yang memiliki 6 sisi.2. Daftarkan semua hasil mata dadu yang mungkin muncul: {1, 2, 3, 4, 5, 6}.3. Hitung jumlah anggotanya: ada 6 buah titik sampel.', NULL, NULL),
(1084, 1084, 'Jawaban: BCara Pengerjaan/Konsep:1. Peluang kejadian mustahil (tidak mungkin terjadi) bernilai 0.2. Peluang kejadian pasti (selalu terjadi) bernilai 1.3. Peluang suatu kejadian selalu berada di antara batas mustahil dan pasti, termasuk bisa menyentuh angka 0 atau 1 itu sendiri.4. Secara matematis ditulis dengan tanda kurang dari sama dengan: 0 ≤ P(A) ≤ 1.', NULL, NULL),
(1085, 1085, 'Jawaban: BCara Pengerjaan:1. Kejadian tidak mungkin terjadi berarti memiliki peluang/persentase 0%.2. Di dalam konsep probabilitas matematika, 0% sama dengan angka 0.3. Nilai negatif tidak ada dalam perhitungan peluang, dan angka 1 adalah khusus untuk kejadian yang pasti terjadi.', NULL, NULL),
(1086, 1086, 'Jawaban: CCara Pengerjaan:1. Diketahui ruang sampel pelemparan dadu standar (S) = {1, 2, 3, 4, 5, 6}.2. Ditanya kemungkinan munculnya angka 7.3. Karena angka 7 sama sekali tidak ada di dalam himpunan S, maka hal tersebut 100% tidak akan pernah terjadi.4. Sesuai definisi, kejadian yang peluangnya 0 disebut kejadian mustahil.', NULL, NULL),
(1087, 1087, 'Jawaban: BCara Pengerjaan:1. Amati fisik dan karakteristik sekeping koin (uang logam).2. Sebuah uang logam hanya terdiri dari 2 muka (sisi).3. Sisi pertama biasanya bertuliskan nominal (Angka), dan sisi baliknya biasanya berupa Gambar garuda/pahlawan.4. Jadi, ruang sampelnya adalah {Angka, Gambar}.', NULL, NULL),
(1088, 1088, 'Jawaban: CCara Pengerjaan/Konsep:1. Ruang sampel (S) adalah semesta pembicaraan dalam sebuah percobaan.2. Kejadian (Event) adalah hasil-hasil khusus yang kita harapkan/syaratkan dari percobaan tersebut.3. Karena kejadian adalah sebagian atau seluruh hasil dari ruang sampel, maka kejadian merupakan himpunan bagian dari ruang sampel.', NULL, NULL),
(1089, 1089, 'Jawaban: BCara Pengerjaan:1. Peluang suatu kejadian A ditambah dengan peluang tidak terjadinya A (komplemen A) selalu mewakili keseluruhan kemungkinan (100%).2. Dalam desimal peluang, nilai 100% adalah 1.3. Persamaan matematisnya adalah P(A) + P(A\') = 1.', NULL, NULL),
(1090, 1090, 'Jawaban: CCara Pengerjaan:1. Diketahui koin 1 memiliki 2 sisi (A, G).2. Diketahui koin 2 memiliki 2 sisi (A, G).3. Aturan perkalian kemungkinan: Total n(S) = n(koin 1) × n(koin 2).4. Hasil: 2 × 2 = 4 titik sampel. Rinciannya: (A,A), (A,G), (G,A), dan (G,G).', NULL, NULL),
(1091, 1091, 'Jawaban: BCara Pengerjaan:1. Identifikasi objek pertama: 1 uang logam = 2 titik sampel {A, G}.2. Identifikasi objek kedua: 1 dadu enam sisi = 6 titik sampel {1, 2, 3, 4, 5, 6}.3. Karena kedua benda dilempar secara berpasangan, kalikan kemungkinan dari kedua objek.4. Total n(S) = 2 × 6 = 12.', NULL, NULL),
(1092, 1092, 'Jawaban: BCara Pengerjaan/Konsep:1. Ada 2 jenis peluang: Teoretik dan Empirik.2. Teoretik didapat dari rumus/perhitungan logika matematis n(A)/n(S) tanpa harus mempraktikkannya.3. Empirik didapat dari praktik percobaan nyata (observasi) dengan membagi frekuensi kejadian yang muncul dengan total seluruh percobaan.4. Berdasarkan pertanyaan "hasil percobaan nyata", maka itu adalah peluang empirik.', NULL, NULL),
(1093, 1093, 'Jawaban: BCara Pengerjaan:1. Daftarkan ruang sampel dadu, S = {1, 2, 3, 4, 5, 6}.2. Ingat syarat bilangan prima: bilangan lebih dari 1 yang hanya bisa dibagi oleh 1 dan bilangan itu sendiri.3. Uji angka di ruang sampel: angka 2, 3, dan 5 masuk dalam kategori prima (sedangkan angka 1 bukan prima).4. Maka, himpunan kejadiannya adalah {2, 3, 5}.', NULL, NULL),
(1094, 1094, 'Jawaban: DCara Pengerjaan:1. Logika dasar probabilitas adalah perbandingan antara hasil yang kita harapkan dengan seluruh hasil yang mungkin terjadi.2. Banyaknya hasil yang diharapkan dilambangkan n(A).3. Banyaknya seluruh kemungkinan dilambangkan n(S).4. Jadi, rumusnya adalah hasil bagi: P(A) = n(A) / n(S).', NULL, NULL),
(1095, 1095, 'Jawaban: CCara Pengerjaan:1. Kejadian pasti berarti peluang terjadinya adalah 100%.2. Dalam pecahan atau desimal peluang, perhitungan dari 100% adalah 100/100.3. Hasil pembagian 100/100 adalah 1.', NULL, NULL),
(1096, 1096, 'Jawaban: BCara Pengerjaan:1. Identifikasi komposisi 1 set kartu bridge.2. Terdapat 4 jenis/simbol utama: Hati (merah), Wajik (merah), Sekop (hitam), dan Keriting (hitam).3. Masing-masing simbol memiliki tepat 13 kartu (As, 2, 3, 4, 5, 6, 7, 8, 9, 10, Jack, Queen, King).4. Hitung totalnya: 4 jenis × 13 kartu = 52 kartu.', NULL, NULL),
(1097, 1097, 'Jawaban: A, B, dan DCara Pengerjaan/Analisis Opsi:- Opsi A benar, kejadian mustahil bernilai peluang 0.- Opsi B benar, kejadian pasti selalu terjadi bernilai peluang 1.- Opsi C salah, karena kisaran nilai terendah peluang adalah 0 (tidak ada angka minus dalam peluang).- Opsi D benar, karena peluang A + komplemen A selalu mencakup seluruh semesta kejadian (bernilai 1).', NULL, NULL),
(1098, 1098, 'Jawaban: A, C, dan DCara Pengerjaan:1. Tentukan ruang sampel dadu: {1, 2, 3, 4, 5, 6}.2. Cari anggota bilangan genap (habis dibagi 2) dari ruang sampel tersebut.3. Angka genapnya adalah 2, 4, dan 6.4. Berdasarkan pilihan ganda, jawaban yang mencocoki angka genap tersebut adalah A (2), C (4), dan D (6).', NULL, NULL),
(1099, 1099, 'Jawaban: A, B, dan DCara Pengerjaan:- Uji Opsi A: Dadu enam sisi mentok di angka 6. Angka 8 mustahil.- Uji Opsi B: Kotak khusus biru tidak mungkin mengeluarkan warna merah. Mustahil.- Uji Opsi C: Koin punya sisi angka. Peluangnya 1/2 (mungkin terjadi).- Uji Opsi D: Satu minggu hanya 7 hari. Hari ke-8 mustahil ada.- Karena yang ditanya adalah kejadian mustahil, maka A, B, dan D benar.', NULL, NULL),
(1100, 1100, 'Jawaban: A dan DCara Pengerjaan:- Opsi A (1 dadu): Banyak ruang sampel = 6. (Sesuai)- Opsi B (2 koin): Banyak ruang sampel = 2 × 2 = 4. (Tidak sesuai)- Opsi C (Huruf vokal): Ada 5 huruf yaitu A, I, U, E, O. Ruang sampel = 5. (Tidak sesuai)- Opsi D (Setengah tahun pertama): Terdiri dari Jan, Feb, Mar, Apr, Mei, Jun. Total 6 bulan. (Sesuai)', NULL, NULL),
(1101, 1101, 'Jawaban: A, B, dan DCara Pengerjaan:- Ruang sampel, titik sampel, dan kejadian adalah tiga komponen pilar utama yang dipelajari pada sub materi peluang matematika SMP.- Sudut siku-siku (Opsi C) merupakan istilah yang digunakan dalam materi Geometri bangun datar, bukan materi Data dan Peluang.', NULL, NULL),
(1102, 1102, 'Jawaban: BCara Pengerjaan:1. Tentukan total ruang sampel 3 koin: n(S) = 2 × 2 × 2 = 8.2. Daftarkan semua titik sampel: {AAA, AAG, AGA, GAA, AGG, GAG, GGA, GGG}.3. Cari kejadian munculnya 2 Angka dan 1 Gambar: {AAG, AGA, GAA}. n(A) = 3.4. Hitung peluang: P(A) = n(A) / n(S) = 3/8.', NULL, NULL),
(1103, 1103, 'Jawaban: ACara Pengerjaan:1. Tentukan ruang sampel dadu: S = {1, 2, 3, 4, 5, 6}, sehingga n(S) = 6.2. Cari bilangan yang memenuhi syarat "prima" sekaligus "genap".3. Satu-satunya bilangan prima yang genap di seluruh angka matematika adalah angka 2. Jadi, A = {2} dan n(A) = 1.4. Hitung peluang: P(A) = 1/6.', NULL, NULL),
(1104, 1104, 'Jawaban: BCara Pengerjaan:1. Ruang sampel 2 dadu: n(S) = 6 × 6 = 36.2. Daftarkan kombinasi dadu yang jika dijumlahkan hasilnya 8: (2,6), (3,5), (4,4), (5,3), (6,2).3. Banyaknya kejadian tersebut: n(A) = 5.4. Hitung peluang: P(A) = 5/36.', NULL, NULL),
(1105, 1105, 'Jawaban: BCara Pengerjaan:1. Hitung total kettlebell: n(S) = 5 + 4 + 3 = 12.2. Identifikasi jumlah kettlebell merah: n(M) = 4.3. Peluang terambilnya merah: P(M) = 4/12.4. Sederhanakan pecahan: 4/12 = 1/3.', NULL, NULL),
(1106, 1106, 'Jawaban: CCara Pengerjaan:1. Cari mata dadu lebih dari 4: {5, 6}. Banyaknya n(A) = 2.2. Hitung peluang teoretiknya: P(A) = 2/6 = 1/3.3. Hitung frekuensi harapan (Fh) dengan mengalikan peluang dengan banyak percobaan: Fh = P(A) × N.4. Fh = (1/3) × 120 = 40 kali.', NULL, NULL),
(1107, 1107, 'Jawaban: CCara Pengerjaan:1. Total kartu: n(S) = 52.2. Jumlah kartu King dalam satu set (Hati, Wajik, Sekop, Keriting): n(K) = 4.3. Hitung peluang: P(K) = 4/52.4. Sederhanakan pecahan dengan membagi pembilang dan penyebut dengan 4: hasilnya 1/13.', NULL, NULL),
(1108, 1108, 'Jawaban: ACara Pengerjaan:1. Banyak percobaan (N) = 50 kali.2. Frekuensi munculnya Angka = 30 kali.3. Cari frekuensi munculnya Gambar: 50 - 30 = 20 kali.4. Hitung peluang empirik Gambar = (Frekuensi Gambar) / (Total Percobaan) = 20/50 = 2/5.', NULL, NULL),
(1109, 1109, 'Jawaban: BCara Pengerjaan:1. Gunakan rumus peluang komplemen: P(Lulus) + P(Tidak Lulus) = 1.2. Diketahui P(Lulus) = 0,85.3. Maka, P(Tidak Lulus) = 1 - 0,85.4. Hasil pengurangannya adalah 0,15.', NULL, NULL),
(1110, 1110, 'Jawaban: CCara Pengerjaan:1. Total lagu: n(S) = 20.2. Lagu bergenre rock/metal: n(A) = 5. Peluangnya P(A) = 5/20 = 1/4.3. Peluang yang diputar BUKAN rock/metal adalah peluang komplemennya.4. P(A\') = 1 - 1/4 = 3/4. (Atau hitung sisa lagu: 15/20 = 3/4).', NULL, NULL),
(1111, 1111, 'Jawaban: BCara Pengerjaan:1. Ruang sampel 2 koin = {AA, AG, GA, GG}, n(S) = 4.2. Sisi yang sama berarti {AA} atau {GG}. Banyaknya n(A) = 2.3. Peluang muncul sisi sama: P(A) = 2/4 = 1/2.4. Frekuensi harapan: Fh = P(A) × N = (1/2) × 60 = 30 kali.', NULL, NULL),
(1112, 1112, 'Jawaban: BCara Pengerjaan:1. Total ruang sampel (semua pendaftar) = 1.000.2. Titik sampel kejadian yang diharapkan (slot yang tersedia) = 50.3. Hitung peluang: P = 50 / 1.000.4. Ubah ke bentuk desimal: P = 5/100 = 0,05.', NULL, NULL),
(1113, 1113, 'Jawaban: ACara Pengerjaan:1. Ruang sampel 2 dadu: n(S) = 36.2. "Jumlah kurang dari 5" berarti jumlah 2, 3, atau 4.3. Daftarkan: jumlah 2 = (1,1); jumlah 3 = (1,2), (2,1); jumlah 4 = (1,3), (2,2), (3,1).4. Total kejadian = 1 + 2 + 3 = 6. Peluang = 6/36 = 1/6.', NULL, NULL),
(1114, 1114, 'Jawaban: BCara Pengerjaan:1. Total kelereng: n(S) = 4 + 6 = 10.2. Kelereng biru: n(B) = 4. Peluang terambil biru: P(B) = 4/10 = 2/5.3. Peluang BUKAN biru = 1 - P(B) = 1 - 2/5 = 3/5.4. (Cara cepat: "Bukan biru" berarti "Hitam". Kelereng hitam ada 6. P = 6/10 = 3/5).', NULL, NULL),
(1115, 1115, 'Jawaban: ACara Pengerjaan:1. Total pertandingan (N) = 40.2. Frekuensi Menang = 24. Maka Frekuensi Kalah = 40 - 24 = 16.3. Peluang empirik kalah = (Frekuensi Kalah) / (Total Pertandingan).4. P(Kalah) = 16 / 40. Sederhanakan (bagi dengan 8) menjadi 2/5.', NULL, NULL),
(1116, 1116, 'Jawaban: CCara Pengerjaan:1. Total baris kode: n(S) = 100.2. Baris yang error: n(E) = 5. Maka baris yang berjalan normal (tidak error) = 100 - 5 = 95.3. Peluang terpilihnya baris normal = 95 / 100.4. Sederhanakan pecahan (bagi 5): 19/20.', NULL, NULL),
(1117, 1117, 'Jawaban: A, B, dan DCara Pengerjaan:Ruang sampel = {AA, AG, GA, GG}. n(S)=4.- Uji Opsi A: Dua Gambar (GG) ada 1. Peluang 1/4. (BENAR)- Uji Opsi B: Minimal 1 Angka = {AA, AG, GA}. Banyaknya 3. Peluang 3/4. (BENAR)- Uji Opsi C: Sisi berbeda = {AG, GA}. Banyaknya 2. Peluang 2/4 atau 1/2. (SALAH)- Uji Opsi D: Frekuensi harapan sisi berbeda = (1/2) × 40 = 20 kali. (BENAR)', NULL, NULL),
(1118, 1118, 'Jawaban: A, B, dan CCara Pengerjaan:Ruang sampel S = {1,2,3,4,5,6}.- Uji A: Ganjil = {1,3,5}. P = 3/6 = 1/2. (BENAR)- Uji B: Faktor dari 6 = bilangan yang bisa membagi 6 habis, yaitu {1,2,3,6}. n(A)=4. P = 4/6 = 2/3. (BENAR)- Uji C: Lebih dari 6 tidak ada di dadu. Mustahil = 0. (BENAR)- Uji D: Prima = {2,3,5}. P = 3/6 = 1/2. Di soal tertulis 1/3. (SALAH)', NULL, NULL),
(1119, 1119, 'Jawaban: A, B, dan DCara Pengerjaan:Rumus Fh = P(A) × Banyak Percobaan.- Uji Opsi A: Fh = (1/6) × 36 = 6. (BENAR)- Uji Opsi B: Fh = (1/6) × 72 = 12. (BENAR)- Uji Opsi C: Fh = (1/6) × 18 = 3. Di soal tertulis 2. (SALAH)- Uji Opsi D: Fh = (1/6) × 30 = 5. (BENAR)', NULL, NULL),
(1120, 1120, 'Jawaban: A, B, dan CCara Pengerjaan:Total n(S) = 52.- Uji A: As ada 4. P = 4/52 = 1/13. (BENAR)- Uji B: Merah (Hati 13 + Wajik 13 = 26). P = 26/52 = 1/2. (BENAR)- Uji C: Wajah J,Q,K masing-masing simbol ada 3. Total 4 simbol × 3 = 12 kartu. P = 12/52 = 3/13. (BENAR)- Uji D: Sekop ada 13 kartu. P = 13/52 = 1/4. Di opsi tertulis 1/3. (SALAH)', NULL, NULL),
(1121, 1121, 'Jawaban: A, B, dan CCara Pengerjaan:Total bola n(S) = 3 + 4 + 5 = 12.- Uji Opsi A: Merah ada 3. P = 3/12 = 1/4. (BENAR)- Uji Opsi B: Biru ada 4. P = 4/12 = 1/3. (BENAR)- Uji Opsi C: Kuning ada 5. P = 5/12. (BENAR)- Uji Opsi D: Bola Hijau tidak ada di kotak (kejadian mustahil). P = 0. Di opsi tertulis 1/12. (SALAH)', NULL, NULL),
(1122, 1122, 'Jawaban: CCara Pengerjaan:1. Analisis kondisi awal: n(S) = 8, dengan 5 Merah dan 3 Biru.2. Kondisi setelah pengambilan pertama: 1 kelereng merah diambil dan tidak dikembalikan.3. Sisa kelereng di kotak: Merah menjadi 4 (5-1), Biru tetap 3. Total kelereng n(S) baru = 7.4. Peluang terambilnya merah pada pengambilan kedua: P(Merah) = 4/7.', NULL, NULL),
(1123, 1123, 'Jawaban: CCara Pengerjaan:1. Ruang sampel 2 dadu = 36.2. Jumlah genap terbentuk dari (Genap+Genap) atau (Ganjil+Ganjil). Terdapat 18 titik sampel.3. Jumlah ganjil terbentuk dari (Genap+Ganjil) atau (Ganjil+Genap). Terdapat 18 titik sampel.4. Karena peluang Andi (18/36 = 1/2) sama dengan peluang Budi (18/36 = 1/2), maka permainan tersebut adil.', NULL, NULL),
(1124, 1124, 'Jawaban: CCara Pengerjaan:1. Pahami konsep kejadian saling bebas (independen).2. Hasil lemparan koin masa lalu tidak memiliki pengaruh sama sekali terhadap lemparan koin di masa depan.3. Koin tidak memiliki "ingatan" untuk menyeimbangkan dirinya sendiri. Oleh karena itu, peluang muncul Angka atau Gambar pada lemparan ke-6 akan selalu tetap 1/2.', NULL, NULL),
(1125, 1125, 'Jawaban: ACara Pengerjaan:1. Misalkan bola merah yang ditambahkan adalah x.2. Jumlah bola merah baru = 4+x. Total bola baru = 10+x.3. Syarat peluang merah = 1/2. Maka: (4+x)/(10+x)=1/2.4. Kalikan silang: 2(4+x)=1(10+x)8+2x=10+x2x−x=10−8→x=2. Harus ditambah 2 bola merah.', NULL, NULL),
(1126, 1126, 'Jawaban: ACara Pengerjaan:1. Total juring n(S) = 6.2. Agar peluang Kuning menjadi 1/2, maka harus ada: (1/2)×6=3 juring Kuning.3. Saat ini Kuning sudah ada 2. Artinya, butuh 1 juring Kuning tambahan.4. Dengan mengecat 1 juring warna lain (misal Merah) menjadi Kuning, komposisinya menjadi: 2 Merah, 3 Kuning, 1 Biru. Peluang Kuning menjadi 3/6 = 1/2.', NULL, NULL),
(1127, 1127, 'Jawaban: ACara Pengerjaan:1. Analisis informasi (syarat angka): Bilangan ganjil {1, 3, 5, 7, 9}.2. Syarat tambahan: Lebih besar dari 3.3. Maka sisa kemungkinan angka yang benar (ruang sampel baru) hanya ada 3, yaitu: {5, 7, 9}.4. Karena hanya ada 1 password yang benar dari 3 kemungkinan tersebut, peluangnya adalah 1/3.', NULL, NULL),
(1128, 1128, 'Jawaban: CCara Pengerjaan:1. Hitung jumlah apel yang busuk: Fh = P(Busuk) × Total.2. Apel busuk = 0,05×80=4 buah.3. Jumlah apel yang bagus = Total apel - Apel busuk.4. Apel bagus = 80−4=76 buah.', NULL, NULL),
(1129, 1129, 'Jawaban: BCara Pengerjaan:1. Hitung peluang Ali: 1 dadu angka 6 → P = 1/6 (sekitar 16,6%).2. Hitung peluang Beni: 2 koin (AA) → P = 1/4 (sekitar 25%).3. Hitung peluang Cita: Kartu As → P = 4/52 = 1/13 (sekitar 7,6%).4. Urutan dari terbesar: 1/4 (Beni) > 1/6 (Ali) > 1/13 (Cita).', NULL, NULL),
(1130, 1130, 'Jawaban: CCara Pengerjaan:1. Jumlah semua peluang = 1. P(Hijau) = 1 - P(Merah) - P(Kuning).2. P(Hijau) = 1−(1/3+1/4)=1−(4/12+3/12)=1−7/12=5/12.3. Rumus peluang: P(Hijau) = n(Hijau) / n(Total).4. 5/12=10/n(Total)→5×n(Total)=120→n(Total)=24.', NULL, NULL),
(1131, 1131, 'Jawaban: CCara Pengerjaan:1. Peluang menang (Bintang) = 1/8.2. Hitung Nilai Harapan (Expected Value) hadiah: (1/8)×Rp24.000=Rp3.000.3. Bandingkan dengan biaya: Harapan dapat Rp3.000, tapi bayar Rp5.000.4. Secara matematis, pemain rata-rata rugi: Rp3.000−Rp5.000=−Rp2.000 per permainan.', NULL, NULL),
(1132, 1132, 'Jawaban: BCara Pengerjaan:1. Konsep Peluang Geometris = Luas area yang dituju / Luas area total.2. Luas target total = π×r2=π×142=196π.3. Luas Bullseye = π×72=49π.4. Peluang = 49π/196π=49/196=1/4.', NULL, NULL),
(1133, 1133, 'Jawaban: CCara Pengerjaan:1. Peluang tebak benar per soal = 1/4.2. Frekuensi harapan benar untuk 10 soal = 10×(1/4)=2,5 soal.3. Karena soal tidak mungkin berbentuk desimal (setengah), harapannya ada di kisaran 2 hingga 3 soal.4. Namun karena bersifat acak (empirik), hasil nyata bisa saja berbeda (bisa 0, bisa juga 4), menjadikannya hanya sebuah ekspektasi probabilitas.', NULL, NULL),
(1134, 1134, 'Jawaban: DCara Pengerjaan:1. Asumsi dasar: Rasio ikan bertanda pada tangkapan kedua sama dengan rasio ikan bertanda pada populasi total.2. Peluang (rasio) dari tangkapan kedua = Ikan bertanda / Total tangkapan = 4/40 = 1/10.3. Terapkan rasio ke populasi total (N): 50 / N = 1/10.4. Kalikan silang: 1×N=50×10→N=500.', NULL, NULL),
(1135, 1135, 'Jawaban: CCara Pengerjaan:1. Analisis syarat: "penjumlahan bilangan genap". Genap = (Genap+Genap) atau (Ganjil+Ganjil).2. Angka tersedia: Genap {2,4}, Ganjil {1,3,5}.3. Pasangan Genap+Genap = (2,4) → 1 cara.4. Pasangan Ganjil+Ganjil = (1,3), (1,5), (3,5) → 3 cara. Total ruang sampel bersyarat = 4 cara.5. Kejadian yang ditanya (keduanya ganjil) ada 3 cara. Maka peluangnya 3/4.', NULL, NULL),
(1136, 1136, 'Jawaban: BCara Pengerjaan:1. Misalkan probabilitas satu angka genap adalah x.2. Karena probabilitas ganjil 2 kali lipatnya, maka probabilitas satu angka ganjil adalah 2x.3. Total dadu ada 3 ganjil dan 3 genap. Total peluang = 1.4. Persamaan: 3(2x)+3(x)=1→6x+3x=1→9x=1→x=1/9.5. Angka 2 adalah genap (yang probabilitasnya x), maka P(2) = 1/9.', NULL, NULL),
(1137, 1137, 'Jawaban: A, B, dan CCara Pengerjaan:- Uji A: Kotak B (4 Merah dari 5). P(Merah B) = 4/5. P(Merah A) = 2/5. 4/5 > 2/5. (BENAR)- Uji B: Jika digabung, total Merah = 6. Total bola = 10. P(Merah Gabungan) = 6/10 = 3/5. (BENAR)- Uji C: Kotak A memiliki P(Putih) = 3/5, sementara Kotak B hanya 1/5. (BENAR)- Uji D: P(Merah A) = 2/5. P(Merah B) = 4/5. 2/5 memang setengah dari 4/5. (Tunggu, ini benar. Evaluasi opsi: A, B, C, D benar semua. Siswa harus memeriksa kalkulasi rasio dengan cermat).', NULL, NULL),
(1138, 1138, 'Jawaban: B, C, dan DCara Pengerjaan:- Opsi A SALAH karena variasi acak (fluktuasi) sangat normal dalam percobaan. 110 masih sangat dekat dengan 100, tidak otomatis membuktikan dadu cacat.- Opsi B BENAR. Peluang teoretik adalah patokan matematis murni yang tak berubah (1/6).- Opsi C BENAR. Hasil dunia nyata (empirik) hampir selalu memiliki sedikit deviasi/selisih dari teoretik.- Opsi D BENAR (Hukum Bilangan Besar). Semakin banyak percobaan, empirik akan konvergen mendekati teoretik.', NULL, NULL),
(1139, 1139, 'Jawaban: A, B, dan CCara Pengerjaan (Peluang Bersyarat Logika):- Opsi A: Ruang sampel normal = 8. Karena "minimal 1 G" terjadi, maka (AAA) dicoret. Tersisa 7. (BENAR)- Opsi B: Karena ada syarat "minimal 1 G", (AAA) tidak mungkin terjadi. Peluang = 0. (BENAR)- Opsi C: Tepat 2 Angka ada 3 kejadian {AAG, AGA, GAA}. Dari sampel baru 7, maka peluangnya 3/7. (BENAR)- Opsi D: Tepat tiga Gambar {GGG} ada 1 kejadian. Tapi pembaginya sekarang 7, bukan 8. Jadi P = 1/7. (SALAH)', NULL, NULL),
(1140, 1140, 'Jawaban: A, B, dan CCara Pengerjaan:- Uji A: Awalnya 2 Merah, 2 Hitam. Total 4. P(Merah) = 2/4 = 1/2. (BENAR)- Uji B: Jika Merah terambil, sisa kotak: 1 Merah, 2 Hitam. Total 3. P(Hitam kedua) = 2/3. (BENAR)- Uji C: Tanpa pengembalian pasti mengubah ruang sampel pengambilan berikutnya, ini adalah definisi kejadian bergantung (dependent event). (BENAR)- Uji D: Ruang sampel berkurang dari 4 menjadi 3. (SALAH)', NULL, NULL),
(1141, 1141, 'Jawaban: A, B, dan CCara Pengerjaan:- Uji D: 1/2+1/3=3/6+2/6=5/6. Belum 100% (belum 1). Pasti ada sisa untuk Kuning. (SALAH)- Uji B: Sisa peluang untuk Kuning = 1−5/6=1/6. (BENAR)- Uji A: Pecahannya adalah 1/2, 1/3, dan 1/6. Agar jumlah kelereng bulat terkecil, total kelereng (penyebut) harus disamakan ke KPK dari 2, 3, dan 6, yaitu angka 6. (BENAR)- Uji C: Dari total 6, Merah = 1/2×6=3. Biru = 1/3×6=2. Kuning = 1/6×6=1. (BENAR)', NULL, NULL)
